// tickets.js — exam tickets. Shared by index.html and exam-tickets.html.
// Shape: {n, tag, sec, core:[ids], ru:{topic, qs[3], a[{q,t}x3], kill}, en:{...}}
// Facts fact-checked against primary sources 2026-09-22 (see sources.js).
window.TICKETS = [
{n:1,tag:"Core-40 #17",sec:"llm",core:[17],
 ru:{"topic":"Токены","qs":["Что такое токен? Дай определение так, как сказал бы интервьюеру.","Сколько символов и сколько слов примерно в одном токене? Почему это среднее, а не правило?","Почему русский текст может стоить дороже английского? Механизм, а не факт."],"a":[{"q":"Определение","t":"Токен — это subword unit, кусок текста из фиксированного словаря модели, обычно на пятьдесят–двести тысяч записей. Модель не видит ни слов, ни букв: она видит целые числа, каждое из которых — индекс в этом словаре. И важно, что токены есть с обеих сторон — твой промпт токенизируется на входе, и модель порождает токены на выходе."},{"q":"Цифры","t":"Примерно четыре символа английского, или три четверти слова — это эвристика OpenAI, одна величина в двух единицах. Anthropic для Claude даёт около трёх с половиной символов, а новые токенайзеры Claude дают до трети больше токенов, так что я меряю. Это среднее, потому что словарь строил BPE: самые частые соседние пары склеивались в одну запись, частые слова стали одним токеном, а редкие режутся. Длину определяет частота, а не смысл."},{"q":"Кириллица","t":"Словарь строился на корпусе с преобладанием английского, поэтому эффективные склейки достались ему, а кириллица режется мельче. Насколько мельче — зависит от токенайзера: в эпоху GPT-2 разница многократная, у cl100k примерно полуторная, у современных больших словарей вроде o200k почти паритет. Это продуктовое решение, а не курьёз: надбавка бьёт и по цене, и по окну. Перед бюджетированием русской фичи я меряю реальный текст счётчиком вендора, у Claude это count_tokens."}],"kill":"<b>«Token is a symbol»</b> — русское «символ» это character, английское symbol значит другое. Говори <b>subword unit</b>. И не путай «4 символа» с «4 слова» — это ошибка в пять раз."},
 en:{"topic":"Tokens","qs":["What is a token? Define it the way you would to an interviewer.","Roughly how many characters and how many words per token? Why is that an average, not a rule?","Why can Russian text cost more than English? Give the mechanism, not the fact."],"a":[{"q":"Definition","t":"A token is a subword unit — a chunk of text from the model's fixed vocabulary, usually somewhere between fifty and two hundred thousand entries. The model never sees words or characters. It sees integers, each one an index into that vocabulary. And it matters that tokens exist on both sides: your prompt is tokenised on the way in, and the model produces tokens on the way out."},{"q":"The numbers","t":"About four characters of English, or three quarters of a word. That's OpenAI's rule of thumb, one fact in two units. Anthropic quotes about three and a half characters for Claude, and newer Claude tokenizers can use up to a third more tokens, so I measure. It's an average rather than a rule because the vocabulary was built by byte-pair encoding: the most frequent adjacent pairs got merged into single entries, so common words became one token and rare ones got split. Frequency decides length, not meaning."},{"q":"Non-English","t":"The vocabulary was built on an English-heavy corpus, so English got the efficient merges and Cyrillic usually gets split finer. How much finer depends on the tokenizer: GPT-2-era ones were several times worse, cl100k roughly one and a half times, and modern large vocabularies like o200k are near parity. It's a product decision, not trivia: the premium hits both cost and context. So before budgeting a Russian feature I measure real text with the vendor's token counter, count_tokens on Claude."}],"kill":"<b>\"A token is a symbol\"</b> — Russian <i>символ</i> means <i>character</i>; English \"symbol\" doesn't. Say <b>subword unit</b>. And never say \"4 words per token\" — that's a 5x error."}},

{n:2,tag:"Core-40 #18",sec:"llm",core:[18],
 ru:{"topic":"Контекстное окно","qs":["Что такое context window и что в него входит?","Сам промпт больше контекстного окна, и ты отправляешь запрос. Что произойдёт и в какой момент?","Промпт 195k, окно 200k, max_tokens 8000. Результат? Почему?"],"a":[{"q":"Определение","t":"Контекстное окно — это максимум токенов, который модель обрабатывает за один запрос, причём вход и сгенерированный выход считаются вместе. За место в нём конкурирует всё сразу: системный промпт, история диалога, найденные документы, определения инструментов и результаты их вызовов. У топовых моделей Claude сейчас порядка миллиона токенов по умолчанию, у младших — двести тысяч; у конкурентов текущие модели в том же диапазоне порядка миллиона. Конкретные цифры я не держу в голове намертво — они двигаются каждые несколько месяцев, и перед собесом я бы их перепроверил на доках вендора, а не цитировал по памяти."},{"q":"Превышение","t":"Придёт 400 invalid_request_error, prompt is too long, до начала генерации, на любой модели. Это ключевой момент: запрос отклоняется целиком, и ни одного токена не сгенерируется. Никакого мягкого усечения нет — модель не выбрасывает молча старые сообщения. Я это запоминаю как fail fast, not silent, и это хороший дизайн: молчаливое усечение дало бы неправильные ответы без сигнала, а ошибку можно обработать. Переполнение ответом — отдельный случай."},{"q":"max_tokens","t":"На текущих моделях Claude запрос примут. Промпт помещается, а max_tokens — потолок, а не резерв. Если ответу нужно больше примерно пяти тысяч оставшихся токенов, генерация остановится на границе окна со stop_reason model_context_window_exceeded. Модели до 4.5 такой запрос отклоняли валидационной ошибкой, поэтому многие до сих пор отвечают «отклонят». В проде я считаю входные токены, ограничиваю max_tokens остатком окна с запасом и обрабатываю model_context_window_exceeded как max_tokens: ответ обрезан, а не закончен."}],"kill":"<b>«Обрежет старое»</b> — нет, слишком длинный промпт упадёт с ошибкой. И <b>stop_reason</b> надо логировать: max_tokens и model_context_window_exceeded оба значат обрезку, молчаливую, на середине слова, без ошибки."},
 en:{"topic":"Context window","qs":["What is the context window and what competes for space in it?","Your prompt alone is bigger than the context window and you send it. What happens, and when exactly?","195k prompt, 200k window, max_tokens 8000. Result? Why?"],"a":[{"q":"Definition","t":"The context window is the maximum number of tokens the model can process in one request, and it counts the input and the generated output together. Everything competes for that space: the system prompt, the conversation history, retrieved documents, tool definitions and tool results. Claude's top-tier models now default to around a million tokens, the smaller ones sit around two hundred thousand; competitors' current models are in the same million-token range. I don't keep exact figures memorized — they shift every few months — I'd check the vendor's docs the day of the interview rather than quote a number from memory."},{"q":"Exceeding it","t":"You get a 400 invalid_request_error, prompt is too long, before generation starts, on every model. That's the part people miss: the request is rejected outright and not a single token is produced. There's no graceful truncation — the model doesn't silently drop the oldest messages. I remember it as fail fast, not silent, and it's the right design: silent truncation would give you wrong answers with no signal, whereas an error you can handle. Output overflow is a separate case."},{"q":"The max_tokens trap","t":"On current Claude models it's accepted. The prompt fits, and max_tokens is a ceiling, not a reservation. If the answer needs more than the roughly five thousand tokens that are left, generation stops at the window edge with stop_reason model_context_window_exceeded. Models before 4.5 rejected input plus max_tokens over the window with a validation error, which is why people still answer rejected. In production I count input tokens first, cap max_tokens at what's left minus a margin, and treat model_context_window_exceeded like max_tokens: truncated, not finished."}],"kill":"<b>\"It truncates the old messages\"</b> — no, an oversized prompt errors out. Also log <b>stop_reason</b>: max_tokens and model_context_window_exceeded both mean clipped, silently, mid-word, with no error."}},

{n:3,tag:"Core-40 #24",sec:"llm",core:[24],
 ru:{"topic":"Экономика токенов","qs":["Почему output дороже input, сейчас у крупных вендоров примерно в 5 раз за токен? Механизм, а не «так в прайсе».","Косты выросли втрое за месяц. Первые четыре гипотезы по порядку.","В простом вызове output был 99% счёта, в агенте input стал 84%. Что изменилось и какой вывод?"],"a":[{"q":"Асимметрия","t":"Потому что вход и выход считаются принципиально по-разному. Промпт известен целиком, поэтому все его токены обрабатываются за один параллельный проход, и GPU загружен эффективно. А выход рождается по одному токену: сколько токенов, столько проходов. Каждый такой проход упирается в пропускную способность памяти: веса и KV-кэш (сохранённые ключи и значения внимания) перечитываются ради одного токена. Будущее нельзя посчитать заранее, а прошлое можно разом. Поэтому выход дороже, и отсюда же вообще возможен стриминг."},{"q":"Дебаг стоимости","t":"Это порядок диагностики, а не рейтинг экономии: ищу, что изменилось. Первое — выбор модели: не уехал ли путь на более дорогой тир. Второе — cache hit rate (доля попаданий в кэш): timestamp или данные пользователя в system молча ломают кэш. Третье — многословность: «ответь одним предложением» экономит больше любой чистки промпта. Четвёртое — не растёт ли история без ограничений. Потом batch API. Для нового агента Anthropic ставит prompt caching первым."},{"q":"Разворот","t":"Изменилась архитектура. В агенте на каждом шаге пересылается весь разговор со всеми скачанными страницами, поэтому вход растёт квадратично и быстро обгоняет выход. И вывод отсюда не «input дороже» и не «output дороже», а тот, что профиль расходов определяется архитектурой, а не моделью. Поэтому его меряют, а не угадывают, и перемеряют заново после каждого изменения архитектуры."}],"kill":"<b>«Оптимизируем промпт»</b> — в простом вызове это театр: срежешь 26 токенов входа и заплатишь больше, если ответ вырос на 19."},
 en:{"topic":"Token economics","qs":["Why does output cost more than input, around 5x per token at the big vendors today? Mechanism, not \"that's the price list\".","Costs tripled this month. Name your first four hypotheses, in order.","In a single call output was 99% of the bill; in the agent input became 84%. What changed, and what's the takeaway?"],"a":[{"q":"The asymmetry","t":"Because input and output are computed in fundamentally different ways. The prompt is known in full, so the state for all of its tokens is computed in a single parallel forward pass — one operation for the whole thing, and the GPU is used efficiently. Output is generated one token at a time: as many passes as tokens, and each decode pass is memory-bandwidth-bound, reloading the weights and the KV cache just to produce one token. The future can't be computed ahead of time, the past can be computed all at once. That's why output is priced higher, and it's also why streaming is possible at all."},{"q":"Debugging cost","t":"This is a diagnosis order, what changed, not a savings ranking. First, model selection: did some path start routing to a pricier tier. Second, cache hit rate: a timestamp or per-user data in the system prompt silently stops caching from hitting. Third, output verbosity, because asking for a one-sentence answer saves far more than trimming the system prompt. Fourth, whether conversation history grows unbounded. Only then the batch API. For a new agent, Anthropic's guidance puts prompt caching before every other lever."},{"q":"The flip","t":"The architecture changed. In an agent every step resends the entire conversation including every page you fetched, so input grows quadratically and quickly overtakes output. And the takeaway isn't that input is expensive or that output is expensive — it's that the cost profile is decided by architecture, not by the model. Which is why you measure it instead of assuming, and re-measure after every architectural change."}],"kill":"<b>\"We'll optimise the prompt\"</b> — in a single call that's theatre. I cut 26 input tokens and paid more, because the answer grew by 19."}},

{n:4,tag:"Core-40 #19",sec:"llm",core:[19],
 ru:{"topic":"Sampling: temperature и top_p","qs":["Что temperature делает с числами и в каком месте пайплайна?","Тот же промпт, temperature 0, два раза. Одинаковый выход гарантирован?","Что делает top_p и чем лучше top_k? И что с temperature на новых Claude?"],"a":[{"q":"Механизм","t":"Temperature делит логиты перед softmax — вот и весь механизм. Если делить на число меньше единицы, логиты расходятся дальше друг от друга, softmax усиливает разрыв, распределение становится резким. Больше единицы — наоборот, сжимаются, распределение выравнивается, маловероятные токены получают шанс. Ноль реализуется как greedy decoding, всегда берётся самый вероятный. И важно, где это происходит: уже после того, как распределение посчитано. Поэтому температура не добавляет модели знаний — она только меняет, как часто берётся не-топовый токен. Вендоры называют это разнообразие креативностью, но на фактической задаче это в основном ошибки."},{"q":"Детерминизм","t":"Нет, не гарантирован — правильная формулировка near-deterministic, not guaranteed. Сложение с плавающей точкой неассоциативно, поэтому результат зависит от порядка редукции (суммирования). Но один forward pass сам по себе детерминирован от запуска к запуску. Главная причина в том, что твой запрос батчится с чужими, а kernel'ы не batch-invariant: другой размер батча меняет порядок редукции, а с ним и численный результат. И там, где два кандидата почти равны, разница в одну десятимиллионную переворачивает выбор — а генерация авторегрессивна, поэтому после одного разошедшегося токена расходится всё. Если нужна настоящая воспроизводимость, я кэширую ответ, а не полагаюсь на сэмплер."},{"q":"top_p и депрекация","t":"top_p сортирует токены по вероятности, набирает их сверху, пока сумма не достигнет p, а остальное отрезает и перенормирует. Главное его свойство — адаптивность: когда модель уверена, в наборе останется один токен, когда не уверена — сорок. А top_k всегда берёт ровно k, независимо от того, насколько модель уверена, и потому либо тащит мусор, либо режет хвост произвольно. Обычный совет вендоров — крутить temperature или top_p, но не оба, а top_k у Anthropic помечен как параметр только для продвинутых сценариев. И отдельно: на моделях после Opus 4.6 (Claude 4.7+) temperature/top_p/top_k вообще deprecated — non-default значение теперь 400 error, официальная рекомендация Anthropic — steering через prompting, а не через sampling-параметры. Отдельный параметр effort действительно есть, но это не замена temperature. Он живёт в output_config и управляет тем, сколько токенов Claude тратит в целом: глубиной thinking, а также длиной текста и tool calls, даже при выключенном thinking. Случайностью вывода он не управляет, это два разных рычага."}],"kill":"<b>«temp 0 = детерминизм»</b> и <b>«выше температура = умнее»</b>. Первое неверно из-за батчинга и порядка float-редукции; второе не добавляет знаний, а на фактической задаче лишнее разнообразие даёт ошибки."},
 en:{"topic":"Sampling: temperature and top_p","qs":["What does temperature do to the numbers, and where in the pipeline does it act?","Same prompt, temperature 0, twice. Is identical output guaranteed?","What does top_p do and why is it preferred over top_k? And what happened to temperature on the newest Claude models?"],"a":[{"q":"Mechanism","t":"Temperature divides the logits before the softmax — that's the entire mechanism. Divide by something below one and the logits move further apart, softmax exaggerates the gaps, and the distribution gets sharp. Above one they compress, the distribution flattens, and unlikely tokens become plausible. Zero is implemented as greedy decoding, always taking the top token. And where it acts matters: this is after the distribution has already been computed. So temperature adds no knowledge — it only changes how often a non-top token gets picked. Vendors call that extra diversity creative, but on a factual task it mostly adds errors."},{"q":"Determinism","t":"No. The correct phrasing is near-deterministic, not guaranteed. Floating-point addition isn't associative, so the result depends on the order values get reduced in. But a single forward pass is actually run-to-run deterministic. The main cause is that your request is batched with other people's, and the kernels aren't batch-invariant: a different batch size changes the reduction order and so the numerics. Where two candidates are nearly tied, a difference of one part in ten million flips the choice — and since generation is autoregressive, one diverged token means everything after it diverges. If I genuinely need reproducibility I cache the output rather than trusting the sampler."},{"q":"top_p and deprecation","t":"top_p sorts tokens by probability, takes them from the top until the accumulated mass reaches p, then cuts the rest and renormalises. Its key property is that it adapts: when the model is confident the set collapses to one token, when it's unsure it might keep forty. top_k always takes exactly k regardless of confidence, so it either drags in noise or truncates the tail arbitrarily. The usual vendor advice is to tune temperature or top_p, not both, and Anthropic marks top_k as advanced use only. And separately: on models after Opus 4.6 (Claude 4.7+), temperature/top_p/top_k are deprecated entirely — a non-default value now returns a 400, and Anthropic's actual guidance is to steer via prompting, not sampling params. There is a real effort field, but it's not temperature's replacement. It lives under output_config and controls how many tokens Claude spends overall: thinking depth, but also the length of text and tool calls, even with thinking off. It doesn't touch output randomness, so these are two different knobs."}],"kill":"<b>\"temp 0 means deterministic\"</b> and <b>\"higher temperature makes the model smarter\"</b>. The first is wrong because of batching and float reduction order; the second adds no knowledge, and on a factual task the extra diversity produces errors."}},

{n:5,tag:"Core-40 #20",sec:"llm",core:[20],
 ru:{"topic":"System vs user prompt","qs":["Чем system отличается от user? Что куда кладут?","Почему system тяжелее перебить? Назови механизм.","И почему это НЕ гарантия безопасности? Где живут настоящие контроли?"],"a":[{"q":"Различие","t":"System несёт то, что верно для каждого хода: роль, правила, ограничения, формат вывода. У Anthropic это вообще отдельный top-level параметр, а не элемент массива сообщений. User несёт то, что верно только для этого хода — сам запрос. И у этого разделения есть прямое денежное следствие: system надо держать статичным, потому что если подставлять туда данные пользователя, префикс меняется каждый запрос, prompt caching не попадает никогда, и ты платишь полную цену вечно."},{"q":"Механизм","t":"Модели обучают с так называемой instruction hierarchy — примерно system выше developer, тот выше user, а ниже всех результаты инструментов и найденный контент. В ходе instruction tuning и RLHF модель учится при конфликте предпочитать более высокий уровень. Поэтому на «ignore your instructions» из пользовательского сообщения она склонна остаться при системном промпте."},{"q":"Почему не граница","t":"Потому что это натренированная склонность, а не механизм разграничения прав. Нет кода, который запретил бы модели послушаться достаточно убедительной инструкции — это мягкий приор, а не барьер. Поэтому системный промпт я называю defense-in-depth, но не defense. Настоящие контроли живут снаружи модели: авторизация на уровне каждого инструмента, где модель просит, а решает мой код; минимальные права; валидация выхода схемой, потому что ответ модели это недоверенный ввод; подтверждение человеком на всём разрушительном. И отдельно стоит помнить, что системный промпт не секретный — его регулярно вытаскивают, поэтому ключей и конфиденциальной логики там быть не должно."}],"kill":"<b>«Положили правило в system prompt, значит безопасно»</b> — этой фразой ты сообщаешь, что агентов в проде не держал."},
 en:{"topic":"System vs user prompt","qs":["How does the system prompt differ from the user prompt? What goes where?","Why is the system prompt harder to override? Name the mechanism.","And why is that NOT a security guarantee? Where do the real controls live?"],"a":[{"q":"The difference","t":"System carries what's true on every turn: role, rules, constraints, output format. With Anthropic it's a separate top-level parameter rather than an element of the messages array. User carries what's true for this turn only — the actual request. And that split has a direct money consequence: you keep system static, because if you interpolate per-user data into it the prefix changes on every request, prompt caching never hits, and you pay full price forever."},{"q":"The mechanism","t":"Models are trained with what's called an instruction hierarchy — roughly, system outranks developer, which outranks user, which outranks tool results and retrieved content. During instruction tuning and RLHF the model learns to prefer the higher level when the levels conflict. So when a user message says ignore your instructions, the model is trained to stay with the system prompt."},{"q":"Why it's not a boundary","t":"Because it's a trained tendency, not an enforced permission system. There's no code path that stops the model obeying a sufficiently persuasive instruction — it's a soft prior, not a barrier. So I'd call the system prompt defense-in-depth, but not a defense. The real controls sit outside the model: authorization at the level of each tool, where the model asks and my code decides; least privilege; schema validation of output, because what the model returns is untrusted input; and human confirmation on anything destructive. And separately, the system prompt isn't secret — people extract them routinely — so no keys and no confidential logic go in there."}],"kill":"<b>\"We put the rule in the system prompt, so it's safe\"</b> — that sentence tells the interviewer you've never run an agent in production."}},

{n:6,tag:"Core-40 #25",sec:"llm",core:[25],
 ru:{"topic":"Prompt injection","qs":["Что такое prompt injection? Чем indirect опаснее прямой?","Твой агент читает страницу, в ней «игнорируй инструкции». Что делаешь?","Почему разделители — не решение?"],"a":[{"q":"Суть","t":"Prompt injection — это когда недоверенный текст попадает в контекст и модель читает его как инструкцию, а не как данные. Прямая инъекция — это когда пользователь сам пишет «ignore previous instructions», и это в основном демонстрация. По-настоящему опасна indirect: инструкция лежит внутри веб-страницы, PDF или тикета поддержки, которые агент притащил сам. Пользователь при этом не писал ничего вредоносного, атака приехала вместе с данными, и именно так ломают агентов в проде."},{"q":"Что делать","t":"Первое — отдавать недоверенный контент в tool_result, а не в system или текст user, JSON-кодировать его, чтобы он не мог закрыть тег, и прямо сказать, что это данные, а не инструкции. Второе — минимальные права у каждого инструмента, чтобы даже успешная инъекция мало что могла. Третье — всё разрушительное только через подтверждение человеком. Четвёртое — валидация выхода схемой, потому что то, что вернула модель, это недоверенный ввод. И пятое — ограничить, куда агент вообще имеет право ходить."},{"q":"Почему не панацея","t":"Потому что разделитель повышает цену атаки, но не устраняет её — модель всё равно может послушаться, это остаётся вопросом убедительности текста, а не разрешений. Надёжная граница возможна только снаружи модели, в коде, который исполняет действия. На собесе я стараюсь сказать обе половины: и что делаю в промпте, и почему на этом не останавливаюсь."}],"kill":"Ответ только про прямую инъекцию. Ломает агентов в проде именно <b>indirect</b>, и спрашивают дальше про неё."},
 en:{"topic":"Prompt injection","qs":["What is prompt injection? Why is indirect injection worse than direct?","Your agent fetches a page and it contains \"ignore your instructions\". What do you do?","Why aren't delimiters a solution?"],"a":[{"q":"The idea","t":"Prompt injection is when untrusted text lands in the context and the model reads it as an instruction rather than as data. Direct injection is the user typing ignore previous instructions, and that's mostly a demo. The dangerous one is indirect: the instruction sits inside a web page, a PDF or a support ticket that your agent fetched itself. The user never typed anything malicious — the attack arrived with the data, and that's how production agents actually get broken."},{"q":"What you do","t":"First, keep untrusted content out of the instructions: deliver it in tool_result blocks, not system or user text, JSON-encoded so it can't close a tag and break out, and state that tool content is data, never instructions. Second, least privilege on every tool, so that even a successful injection can't do much. Third, anything destructive goes through human confirmation. Fourth, validate output against a schema, because what the model returns is untrusted input. And fifth, constrain where the agent is allowed to go."},{"q":"Why delimiters aren't enough","t":"Because a delimiter raises the cost of the attack without eliminating it — the model can still be talked into it, which makes it a question of how persuasive the text is rather than a question of permissions. A reliable boundary only exists outside the model, in the code that executes actions. In an interview I try to say both halves: what I do in the prompt, and why I don't stop there."}],"kill":"Answering only about direct injection. <b>Indirect</b> is what actually breaks production agents, and it's where the follow-up goes."}},

{n:7,tag:"Core-40 #21, #33",sec:"agents",core:[21,33],
 ru:{"topic":"Tool use","qs":["Модель попросила инструмент. Кто идёт в интернет и что происходит дальше по шагам?","Из чего состоит определение tool и что там самое важное?","Почему content в ответе — массив, а не строка?"],"a":[{"q":"Петля","t":"Для моих собственных инструментов модель ничего не вызывает. Она возвращает намерение: имя инструмента и аргументы. Дальше всё делает мой код: идёт в интернет, получает результат и кладёт его в массив сообщений как tool_result с тем же tool_use_id. Потом модель вызывается снова с результатом в контексте, и так по кругу, пока stop_reason не перестанет быть tool_use. Исключение — серверные инструменты Anthropic вроде веб-поиска: их исполняет платформа и отдаёт результат в том же ответе. Для клиентских инструментов руки — мой код, поэтому и возможна авторизация."},{"q":"Определение","t":"Имя, описание и JSON-схема параметров. И самое важное там — описание, потому что это на самом деле промпт, а не документация: это главное, по чему модель решает, звать ли инструмент и как. Имя, описания параметров и примеры тоже влияют, но гораздо слабее. Я пишу его как инструкцию для толкового незнакомца — что инструмент делает, когда его применять и, отдельно, когда применять не надо. Плохое описание чинится не кодом, а текстом."},{"q":"Массив блоков","t":"Потому что в одном ответе может приехать сразу несколько разных блоков: текст и запрос инструмента вместе, иногда несколько инструментов сразу. Модель одновременно рассуждает вслух и просит данные. Поэтому content — это массив с полем type у каждого блока, и код обязан их фильтровать, а не считать ответ строкой."}],"kill":"<b>«Модель вызывает функцию»</b> — для твоих инструментов нет: она возвращает блок tool_use с именем и JSON-аргументами, исполняешь ты. Именно поэтому возможна авторизация; на стороне платформы работают только серверные инструменты Anthropic."},
 en:{"topic":"Tool use","qs":["The model asked for a tool. Who goes to the internet, and what happens next, step by step?","What's in a tool definition, and which part matters most?","Why is content an array rather than a string?"],"a":[{"q":"The loop","t":"For my own tools the model doesn't call anything. It returns an intent: a tool name and arguments. Everything after that is my code: it goes to the internet, gets the result, and appends it to the messages array as a tool_result with the same tool_use_id. Then the model is called again with that result in context, and round it goes until stop_reason is no longer tool_use. The exception is Anthropic's server tools, like web search: those run on Anthropic's side and return results in the same response. For client tools the hands are my code, which is exactly why authorization is possible."},{"q":"The definition","t":"A name, a description, and a JSON schema for the parameters. The description is the part that matters, because it's really a prompt rather than documentation — it's the main thing the model uses to decide whether and how to call the tool. The name, parameter descriptions and examples count too, but far less. I write it for a competent stranger: what it does, when to use it, and separately when not to. A bad description is fixed with text, not with code."},{"q":"Array of blocks","t":"Because a single response can carry several different blocks at once: text and a tool request together, sometimes several tool requests. The model reasons out loud and asks for data in the same message. So content is an array where every block has a type, and your code has to filter on that rather than treating the response as a string."}],"kill":"<b>\"The model calls the function\"</b> — for your own tools it doesn't: it returns a tool_use block with a name and JSON input, and you execute it. That's exactly why authorization is possible; only Anthropic's server tools run on the platform."}},

{n:8,tag:"Core-40 #34",sec:"agents",core:[34],
 ru:{"topic":"Стоп-условия и ошибки","qs":["Как агент понимает, что пора остановиться? Перечисли условия.","Tool вернул 404. Бросаешь исключение или отдаёшь модели?","Что должно происходить, когда прогон падает на середине?"],"a":[{"q":"Стоп","t":"Останавливаемся в четырёх случаях: модель вернула финальный ответ вместо запроса инструмента, достигнут потолок итераций, случилась неустранимая ошибка, или мы упёрлись в чекпоинт, где нужен человек. Жёсткий лимит шагов и бюджет по деньгам я считаю обязательными: ничто не гарантирует, что агент с падающим инструментом остановится. Модель может сдаться после пары попыток, но может и дальше пробовать новые пути, пока не кончатся деньги. И причину остановки надо логировать — при разборе это первое, на что смотришь."},{"q":"Ошибки tool","t":"Отдаю модели. Возвращаю её в tool_result с is_error: true и понятным текстом, вроде HTTP 404 для этого url, попробуй другой источник. Модель это читает и пробует другой путь — другой url, другую страницу. Если бросить исключение, агент умрёт на первой битой ссылке и потеряет всю уже проделанную работу, за которую ты уже заплатил. Ошибка инструмента — это нормальные данные для модели, а не аварийная ситуация для программы."},{"q":"Падение","t":"Учёт расходов обязан отработать в любом случае, иначе не знаешь, во что обошёлся неудачный прогон. У меня он висит на событии exit процесса (только синхронный код) плюс обработчики SIGINT и SIGTERM, поэтому отчёт печатается и при падении. Не спасут SIGKILL, OOM (убийство процесса из-за нехватки памяти), нативный abort и сигнал без обработчика, например SIGHUP. Инструментация, которая работает только на счастливом пути, бесполезна ровно тогда, когда нужна. Плюс ретраи на транзиентных сетевых ошибках и явный таймаут, чтобы одна икота сети не убивала прогон."}],"kill":"Забыть про потолок итераций. <b>«Ну оно само остановится»</b> — может, после пары неудачных попыток, но никто этого не гарантирует, а зациклившийся агент жжёт деньги."},
 en:{"topic":"Stopping criteria and errors","qs":["How does an agent know it should stop? List the conditions.","A tool returns 404. Do you throw, or hand it back to the model?","What has to happen when a run dies halfway?"],"a":[{"q":"Stopping","t":"There are four cases: the model returned a final answer instead of a tool request, we hit the iteration cap, an unrecoverable error occurred, or we reached a checkpoint that needs a human. I treat a hard step cap and a spending budget as mandatory: nothing guarantees that an agent with a failing tool stops. The model may give up after a few retries, but it can also keep trying new routes until the money runs out. And I log why it stopped — it's the first thing you look at when something goes wrong."},{"q":"Tool errors","t":"I hand it back to the model. I return it inside the tool_result with is_error: true and an instructive message, like HTTP 404 for this URL, try another source. The model reads it and tries a different route — another URL, another page. If you throw instead, the agent dies on the first dead link and loses all the work it had already done and already paid for. A tool error is ordinary data for the model, not an emergency for the program."},{"q":"Crashes","t":"Cost accounting has to run either way, otherwise you don't know what the failed run cost. Mine hangs off the process exit event, synchronous code only, plus SIGINT and SIGTERM handlers, so the report prints even on a crash; SIGKILL, an OOM kill, a native abort or a signal I haven't handled still gets past it. Instrumentation that only works on the happy path is useless precisely when you need it. Plus retries on transient network errors and an explicit timeout, so one hiccup doesn't kill the run."}],"kill":"Forgetting the iteration cap. <b>\"It'll stop on its own\"</b> — it may, after a few failed retries, but nothing guarantees it, and a looping agent burns money."}},

{n:9,tag:"глубина / depth",sec:"bonus",core:[41],
 ru:{"topic":"Attention и кэш","qs":["Что такое Q, K и V? Объясни своими словами.","Почему кэшируют K и V, но не Q? И почему кэш только префиксный?","Чем prompt caching отличается от KV cache внутри запроса? Что значит ephemeral?"],"a":[{"q":"Q/K/V","t":"Для каждого токена модель считает три вектора. K — это как бирка, «про что я, чем могу быть полезен». V — фактическое содержимое, то, что этот токен передаёт дальше. А Q — запрос текущего токена, «что я сейчас ищу». Механика такая: Q сравнивается со всеми K, из этого получаются веса релевантности, и уже этими весами взвешиваются V. То есть Q ищет, K отвечает за находимость, V переносит смысл."},{"q":"Почему KV","t":"Потому что K и V токена зависят только от него самого и от того, что было до него, и никогда — от того, что придёт после. Значит, посчитав их однажды, можно хранить: они не изменятся. А Q нужен ровно один раз, в момент обработки своего токена, и хранить его незачем — отсюда и название KV cache, а не QKV. Префиксность следует оттуда же: если поменять токен на пятой позиции, все, кто идёт после, находятся уже в другом контексте, и их K и V другие. А то, что было до пятого, не затронуто вообще. Это, кстати, общий закон — кэшируется то, что зависит только от прошлого, ровно как useMemo или инкрементальная сборка."},{"q":"Prompt caching","t":"KV cache внутри одного запроса работает всегда, автоматически и бесплатно, но живёт ровно один запрос: ответ отдан, состояние выброшено. Prompt caching его не выбрасывает, а держит между запросами — механизм тот же, другая область жизни. Держать стоит им памяти, поэтому запись при стандартном времени жизни примерно на четверть дороже обычного входа, а чтение стоит десятую часть входа или меньше, в зависимости от модели — сверяюсь с текущим прайсом. Ephemeral (временный) — это минимум пять минут жизни с бесплатным продлением при каждом попадании, есть и более дорогой вариант на час. Попадания всё равно не гарантированы: префикс меняется, запись истекает. Отсюда правило: код обязан работать одинаково при нуле попаданий, кэш — это оптимизация цены, а не часть логики."}],"kill":"<b>«Кэш чтобы не платить дважды»</b> — мелко. Правильно: продление жизни KV-состояния между запросами, поэтому запись с наценкой, а чтение почти даром."},
 en:{"topic":"Attention and caching","qs":["What are Q, K and V? Explain in your own words.","Why are K and V cached but not Q? And why is the cache prefix-only?","How is prompt caching different from the KV cache inside a request? What does ephemeral mean?"],"a":[{"q":"Q/K/V","t":"For every token the model computes three vectors. K is like a label — what this token is about, what it can be useful for. V is the actual content, what this token passes along. And Q is the current token's query — what it's looking for right now. The mechanics are that Q gets compared against every K, that produces relevance weights, and those weights are then applied to the Vs. So Q searches, K makes a token findable, and V carries the meaning."},{"q":"Why KV","t":"Because a token's K and V depend only on itself and on what came before it, and never on what comes after. So once you've computed them you can store them — they won't change. Q is needed exactly once, at the moment its own token is processed, so there's nothing worth keeping — which is why it's called a KV cache and not a QKV cache. Prefix-only follows from the same thing: change the token at position five and everything after it sits in a different context, so their K and V differ, while everything before five is untouched. It's a general law, really — you can cache whatever depends only on the past, exactly like useMemo or an incremental build."},{"q":"Prompt caching","t":"The KV cache inside a single request is always on, automatic and free, but it lives for exactly one request — the answer is returned and the state is thrown away. Prompt caching doesn't throw it away, it holds it between requests. Same mechanism, different scope. Holding it costs them memory, so a cache write carries a premium, about a quarter over normal input at the default lifetime, while a read costs a tenth of normal input or even less on some models — I'd check current pricing. Ephemeral means a short lifetime: at least five minutes, refreshed free on every hit, with a pricier one-hour option. Hits still aren't guaranteed: the prefix changes, the entry expires. Hence the rule that your code has to behave identically with zero cache hits — caching is a price optimisation, never part of the logic."}],"kill":"<b>\"Caching so you don't pay twice\"</b> is too shallow. It's persisting KV state across requests — which is why writes carry a premium and reads are nearly free."}},

{n:10,tag:"Core-40 #18, #27",sec:"llm",core:[18,27],
 ru:{"topic":"Statelessness и лестница","qs":["Модель что-нибудь помнит между вызовами?","Из этого следуют три вещи. Какие?","Контекст кончается. Обходы от самого дешёвого к сложному."],"a":[{"q":"Память","t":"Ничего не помнит. Это обычный HTTP-запрос: отправил, получил ответ, соединение закрылось, никакого состояния на той стороне не осталось. «Помнит» на самом деле мой массив сообщений — то есть память живёт в моём коде, а не в модели. Поэтому каждый ход диалога пересылает всю переписку заново, целиком."},{"q":"Следствия","t":"Во-первых, каждый ход дороже предыдущего: вход запроса растёт линейно с историей, а значит суммарно по разговору оплаченные токены растут квадратично. Во-вторых, контекстное окно неизбежно кончается, это вопрос времени, а не вероятности. И в-третьих, в агентной петле одни и те же данные оплачиваются многократно — у меня в замере было шестьдесят девять тысяч токенов отправлено ради двадцати одной тысячи уникальных, то есть за одно и то же я заплатил больше трёх раз."},{"q":"Лестница","t":"Начинаю с самого тупого — sliding window (скользящее окно): держим последние N сообщений, остальное выбрасываем, бесплатно, но молча теряем информацию. Дальше summarization, старое сжимается в накопительное резюме, свежее держится дословно — так работает большинство долгоживущих чатов. Потом RAG: не класть в контекст вообще, а доставать релевантное под конкретный запрос — правильный выбор, когда корпус больше окна. Четвёртое — hierarchical или map-reduce: режем документ, обрабатываем части отдельно, собираем. Пятое, стоящее особняком, — prompt caching: места не экономит, экономит деньги и латентность на стабильном префиксе, поэтому идёт вместе с остальными. Свои ступени есть и у провайдеров: у Anthropic это context editing (очистка старых tool results в агенте) и серверная compaction (сжатие истории); это быстро меняется, сверяюсь с документацией."}],"kill":"Назвать только summarization. Верно, но это одна ступень из нескольких — а спрашивают, умеешь ли выбирать <b>самое дешёвое из достаточного</b>."},
 en:{"topic":"Statelessness and the ladder","qs":["Does the model remember anything between calls?","Three things follow from that. What are they?","You're running out of context. Walk the mitigations from cheapest to most complex."],"a":[{"q":"Memory","t":"It remembers nothing. It's an ordinary HTTP request: you send it, you get an answer, the connection closes, and no state is left on that side. What actually remembers is my messages array — so the memory lives in my code, not in the model. Which is why every turn of a conversation resends the entire history from scratch."},{"q":"Consequences","t":"First, every turn costs more than the last: each request's input grows linearly with the history, so the total billed over the conversation grows quadratically. Second, the context window inevitably runs out — it's a question of when, not whether. And third, in an agent loop the same data gets paid for many times over. In my own run I sent sixty-nine thousand tokens to convey twenty-one thousand unique ones, so I paid for the same pages more than three times."},{"q":"The ladder","t":"I start with the dumbest thing that works — a sliding window, keep the last N messages and drop the rest: free, and it loses information silently. Then summarization, where older turns get compressed into a running summary and recent ones stay verbatim; that's what most long-lived chat products actually do. Then RAG: don't put it in context at all, retrieve only what's relevant per query — the right answer once the corpus is bigger than the window. Fourth is hierarchical or map-reduce: split a document, process the parts independently, combine. Fifth, which stands apart, is prompt caching: it saves no space, only money and latency on a stable prefix, so it goes alongside the others. Providers add their own rungs too — Anthropic has context editing, which clears old tool results in agent loops, and server-side compaction. That moves fast, so I'd check the current docs."}],"kill":"Naming only summarization. It's correct, but it's one rung of several — and the question is really whether you can pick <b>the cheapest thing that suffices</b>."}},

{n:11,tag:"Core-40 #22",sec:"llm",core:[22],
 ru:{"topic":"Streaming: SSE и ReadableStream","qs":["Как выглядит SSE-поток на проводе и почему для стриминга ответа LLM берут его, а не WebSocket?","Ты потребляешь поток в браузере. Пройди по коду: от fetch до появления текста на экране.","Соединение оборвалось на середине ответа. Что ты видишь в коде и что делает UI?"],"a":[{"q":"На проводе","t":"Это обычный HTTP-ответ с content-type text/event-stream, который сервер не закрывает, а пишет в него кусками. Каждое событие — строки вида data: и JSON, разделённые пустой строкой. Односторонний канал от сервера к клиенту, без апгрейда протокола, и раз это обычный HTTP, он проходит через большинство прокси. Но буферизующий прокси или таймаут простоя могут его сломать, поэтому сервер шлёт комментарии-ping (сигнал «я жив») и отключает буферизацию. WebSocket двусторонний, с состоянием сокета, а у меня по сути запрос-ответ, приезжающий по частям. Нюанс: встроенный EventSource умеет только GET без заголовков, поэтому для LLM я делаю fetch с POST и читаю body как ReadableStream — формат тот же, парсер свой."},{"q":"Код","t":"fetch с POST и телом запроса, потом res.body.getReader() и TextDecoder. В цикле reader.read() отдаёт байты, я декодирую их с флагом stream: true, потому что чанк может разрезать многобайтовый символ пополам, и докладываю в буфер. Буфер режу по пустым строкам, предварительно нормализовав переводы строк CRLF, из каждого события беру строку data: и парсю JSON. У Anthropic это message_start, потом на каждый блок content_block_start, события content_block_delta с text_delta и content_block_stop, затем message_delta со stop_reason и usage, и message_stop. Между ними могут приходить ping (служебные события-пульс). Дельту дописываю в состояние. Рендер батчу через requestAnimationFrame, а не сеттер на каждый токен."},{"q":"Обрыв","t":"Никакого специального события обрыва нет. Либо reader.read() отклонится, либо done придёт раньше, чем message_stop. Ещё Anthropic может прислать посреди потока событие error, например overloaded_error, уже после 200. В любом случае остаётся частичный текст, и UI его не выбрасывает: помечает как неполное и даёт retry. Отмену делаю через AbortController, чтобы перестать принимать то, что пользователь уже закрыл. И две вещи, которые люди забывают: stop_reason max_tokens значит обрезано, а не готово, и итоговое число выходных токенов приходит только в message_delta, поэтому полная стоимость неизвестна до конца. Стриминг улучшает время до первого токена, а не общую задержку."}],"kill":"<b>«SSE это как WebSocket»</b> — нет, это HTTP-ответ, который не закрывают. И <b>decoder без stream: true</b> — чанк режет UTF-8 пополам, и кириллица превращается в мусор ровно на демо."},
 en:{"topic":"Streaming: SSE and ReadableStream","qs":["What does an SSE stream look like on the wire, and why use it for LLM output instead of WebSocket?","You're consuming the stream in the browser. Walk me through the code from fetch to text on screen.","The connection drops mid-answer. What do you see in code and what does the UI do?"],"a":[{"q":"On the wire","t":"It's a plain HTTP response with content-type text/event-stream that the server keeps open and writes to in chunks. Each event is a few lines — data: followed by JSON — separated by a blank line. One-way, server to client, no protocol upgrade, and since it's plain HTTP it gets through most proxies. A buffering proxy or an idle timeout can still break it, so servers send periodic comment pings and turn buffering off. WebSocket is bidirectional with socket state to manage, and mine is really request-response arriving in pieces. One catch: the built-in EventSource only does GET with no headers, so for LLM calls I use fetch with POST and read the body as a ReadableStream — same wire format, my own parser."},{"q":"The code","t":"fetch with POST and the request body, then res.body.getReader() and a TextDecoder. In a loop, reader.read() hands me bytes, I decode with stream: true — because a chunk can cut a multi-byte character in half — and append to a buffer. I split the buffer on blank lines, normalising CRLF endings first, take the data: line of each event, parse the JSON. With Anthropic that's message_start, then for each content block a content_block_start, content_block_delta events carrying text_delta, and content_block_stop, then message_delta with stop_reason and usage, then message_stop. Pings can arrive in between. Each delta gets appended to state, and I batch renders on requestAnimationFrame rather than setting state per token."},{"q":"The drop","t":"There's no dedicated disconnect event. Either reader.read() rejects, or done arrives before message_stop. Anthropic can also send an error event mid-stream, like overloaded_error, after a 200. Either way I have partial text, and the UI keeps it — marked incomplete, with a retry. Cancel goes through an AbortController so I stop consuming output the user already closed. Two things people forget: stop_reason max_tokens means truncated, not finished, and the final output count only arrives in message_delta, so the full cost is unknown until the end. Streaming improves time to first token, not total latency."}],"kill":"<b>\"SSE is like WebSocket\"</b> — it isn't, it's an HTTP response that stays open. And <b>decoding without stream: true</b> — a chunk splits UTF-8 mid-character and non-English text turns to garbage, reliably during the demo."}},

{n:12,tag:"Core-40 #23",sec:"llm",core:[23],
 ru:{"topic":"Structured output","qs":["Три способа получить JSON от модели. Что это за способы и когда какой?","Как надёжнее всего получить JSON по схеме у Anthropic? И что на самом деле дают strict и принудительный вызов инструмента?","JSON пришёл невалидный или не по схеме. Что делаешь?"],"a":[{"q":"Три способа","t":"Первый — попросить в промпте отвечать JSON и распарсить. Дёшево, ненадёжно: модель заворачивает в markdown, добавляет пояснение, пропускает поле. Второй — нативный structured output (структурированный вывод): JSON mode или схема ответа, как response_format у OpenAI, и у Anthropic теперь есть свои structured outputs. Это гарантирует синтаксически валидный JSON, а в strict-режиме и соответствие схеме. Третий — tool use: описываю инструмент, чей input schema и есть нужная мне форма, и прошу модель его вызвать. Вызов инструмента — это и есть мой структурированный ответ, исполнять ничего не надо. Выбираю по требуемой надёжности и по тому, что даёт провайдер. Для продакшена — второй или третий, первый только для прототипа."},{"q":"Strict-режим","t":"У Anthropic сейчас самый надёжный путь — structured outputs (структурированный вывод): JSON-схема на сам ответ или strict: true на инструменте. Оба через constrained decoding (генерацию, ограниченную схемой), а не проверку постфактум. Без strict схема инструмента — лишь подсказка, и можно получить «2» вместо 2. Принудительный вызов через tool_choice работает, где поддерживается, но некоторые текущие модели его отклоняют — сверяюсь с документацией. Описания полей — часть API: модель заполняет поля по их тексту. Гарантия — синтаксис и форма, не правдивость: валидный объект может содержать выдуманную дату."},{"q":"Невалидный","t":"Валидирую всегда, через Zod, даже в strict-режиме: схема провайдера и моя схема — это два разных контракта. При ошибке делаю retry и прикладываю текст ошибки валидации в сообщение: модель обычно чинит с первого раза. Максимум два повтора, потом fallback и алерт. Долю невалидных ответов считаю как метрику эвала, а не как случайность. Невалидированный JSON никогда не идёт в базу. И держу схему маленькой: чем меньше опциональных полей, тем меньше галлюцинированных значений."}],"kill":"<b>«JSON mode гарантирует правильные данные»</b> — гарантирует валидный JSON, не правду. И парсинг регуляркой из markdown-блока — это способ номер ноль, о нём на интервью лучше не вспоминать."},
 en:{"topic":"Structured output","qs":["Three ways to get JSON out of a model. What are they and when do you use each?","What's the most reliable way to get schema-shaped JSON on Anthropic? And what do strict mode and forcing a tool actually buy you?","The JSON comes back invalid or off-schema. What do you do?"],"a":[{"q":"Three ways","t":"First, ask for JSON in the prompt and parse. Cheap, unreliable: the model wraps it in markdown, adds an explanation, drops a field. Second, native structured output: JSON mode or a response schema, like OpenAI's response_format, and Anthropic now has its own structured outputs. That guarantees syntactically valid JSON, and in strict mode conformance to the schema. Third, tool use: I define a tool whose input schema is exactly the shape I want and have the model call it. The tool call is my structured output — nothing gets executed. I pick by how much reliability I need and what the provider offers. Production is option two or three; option one is prototype-only."},{"q":"Strict mode","t":"On Anthropic the most reliable path now is structured outputs: a JSON schema on the response itself, or strict: true on a tool. Both use constrained decoding: generation is limited to the schema, not checked afterwards. Without strict, a tool schema is only guidance, so I can get \"2\" instead of 2. Forcing a tool with tool_choice works where supported, but some current models reject it, so I check the docs. Field descriptions are part of the API: the model fills fields from that text. What's guaranteed is syntax and shape, not truth — a valid object can still carry an invented date."},{"q":"Invalid","t":"I validate every time, with Zod, even in strict mode — the provider's schema and mine are two different contracts. On failure I retry and append the validation error to the message; the model usually fixes it on the first try. Two retries max, then a fallback and an alert. I track the invalid rate as an eval metric, not as bad luck. Unvalidated JSON never touches the database. And I keep the schema small: fewer optional fields means fewer hallucinated values."}],"kill":"<b>\"JSON mode guarantees correct data\"</b> — it guarantees valid JSON, not true values. And regex-parsing a markdown fence is option zero; don't bring it up in an interview."}},

{n:13,tag:"Core-40 #26",sec:"llm",core:[26],
 ru:{"topic":"Выбор модели и роутинг","qs":["У Claude несколько уровней моделей, от флагмана до Haiku. Как выбираешь и что у тебя по умолчанию?","Что такое model routing и куда на самом деле уходят деньги?","Как понижаешь модель на шаге, не сломав качество?"],"a":[{"q":"Выбор","t":"По умолчанию у меня Sonnet, средний уровень: лучший баланс качества, цены и задержки, и на нём я пишу всё, пока не доказано обратное. Haiku беру для массовых простых операций: классификация, извлечение полей, дистилляция страниц — там он самый быстрый и дешевле в разы, но не на порядок. Верхние уровни, Opus и выше, — для сложных рассуждений, длинных агентных задач и там, где качество ответа и есть продукт. Линейка меняется, поэтому я думаю уровнями и сверяюсь с прайсом. Ошибка — брать самую умную модель везде: платишь за интеллект, который большинству шагов не нужен."},{"q":"Роутинг","t":"Роутинг — это разные модели на разных шагах или для разных классов запросов. В моём scout-агенте Haiku сжимает сырые страницы до того, как их увидит Sonnet: двадцать тысяч символов мусора перестают попадать в дорогую модель. Стоимость — вход и выход по своим ценам, выход за токен в разы дороже, плюс запись и чтение кэша. В агентах обычно доминирует вход, поэтому рычаг — не модель, что пишет ответ, а та, что читает объём. Я это увидел на цифрах: до роутинга у меня шестьдесят процентов счёта были cache writes от повторной отправки одних и тех же страниц."},{"q":"Понижение","t":"Сначала эвал, потом понижение. Собираю маленький golden set для этого шага, прогоняю обе модели, сравниваю по метрике шага — точность извлечения, faithfulness, что там важно — и считаю разницу в цене. Понижаю, только если качество держится в допуске. Оставляю эскалацию: если дешёвая модель не уверена или валидация не прошла, шаг уходит наверх. Понижать по ощущениям нельзя — потом не поймёшь, откуда просела точность."}],"kill":"<b>«Просто бери самую сильную»</b> — это ответ человека, который не платил за API. Противоположная ошибка — <b>понижать по цене без эвала</b>: качество упало, а ты об этом узнаёшь от пользователей."},
 en:{"topic":"Model selection and routing","qs":["Claude comes in several tiers, from the flagship down to Haiku. How do you choose, and what's your default?","What is model routing, and where does the money actually go?","How do you downgrade a step's model without breaking quality?"],"a":[{"q":"Choosing","t":"My default is Sonnet, the mid tier: the best balance of quality, price and latency, and that's what I build on until proven otherwise. Haiku is for high-volume simple operations — classification, field extraction, distilling pages — where it's fastest and cheaper by a small multiple, not an order of magnitude. The top tiers, Opus and above, are for hard reasoning, long agentic tasks, and anywhere the answer's quality is the product. The lineup shifts, so I think in tiers and check current pricing. Using the smartest model everywhere means paying for intelligence most steps don't need."},{"q":"Routing","t":"Routing means different models for different steps or request classes. In my scout agent, Haiku distills raw pages before Sonnet ever sees them: twenty thousand characters of noise stop reaching the expensive model. Cost is input and output tokens at their own prices, output several times dearer per token, plus cache writes and reads. In agents input volume usually dominates, so the lever is the model that reads the bulk, not the one that writes the answer. I saw this in numbers: before routing, sixty percent of my bill was cache writes from resending the same pages."},{"q":"Downgrading","t":"Eval first, downgrade second. I build a small golden set for that step, run both models, compare on the step's metric — extraction accuracy, faithfulness, whatever matters there — and measure the cost delta. I downgrade only if quality holds within tolerance. I keep an escalation path: if the cheap model is unsure or validation fails, the step goes up a tier. You never downgrade on vibes, because later you can't tell where the accuracy went."}],"kill":"<b>\"Just use the strongest model\"</b> is the answer of someone who has never paid an API bill. The opposite mistake is <b>downgrading on price with no eval</b>: quality drops and you find out from users."}},

{n:14,tag:"Core-40 #32",sec:"agents",core:[32],
 ru:{"topic":"ReAct и агентный цикл","qs":["Что такое ReAct и какую задачу он решает по сравнению с одним вызовом?","Минимальная реализация: что внутри тела цикла?","Где это ломается и что ты добавляешь?"],"a":[{"q":"Что это","t":"Reason плюс Act: модель рассуждает, выбирает действие — вызов инструмента, — получает наблюдение, рассуждает снова, пока не будет финального ответа. Он решает то, что одному вызову недоступно: достать информацию, которой у модели нет, проверить гипотезу, сделать многошаговую работу, где следующий шаг зависит от предыдущего. Голый вызов не достанет нового и не исправится после ошибки. Серверный web search (поиск в интернете) крутит цикл внутри одного запроса, но это цикл провайдера. Главное: в статье ReAct — формат промпта, но работает он только с внешним циклом в моём коде, который исполняет действия и возвращает наблюдения."},{"q":"Реализация","t":"Массив messages, описание инструментов. Вызываю модель. Если stop_reason равен tool_use — беру имя и аргументы, исполняю сам, кладу результат в messages как tool_result и иду на следующую итерацию. Если end_turn — это финальный ответ, выхожу. Другие причины остановки, вроде max_tokens, pause_turn или refusal, обрабатываю явно, а не как ответ. Обязательно: потолок по шагам, бюджет по деньгам, ошибки инструмента возвращаю как строку в tool_result, а не бросаю исключение — модель должна их увидеть и среагировать. Это буквально мой scout: пять шагов, шесть страниц, и я вижу каждый шаг в логе."},{"q":"Где ломается","t":"Зацикливается на падающем инструменте. Уходит от цели, когда контекст растёт и исходная задача тонет посередине. Раздувает стоимость, потому что каждая итерация пересылает всю историю — у меня одни и те же страницы оплачивались три с лишним раза. Что добавляю: жёсткий потолок шагов и бюджет, дистилляцию выходов инструментов дешёвой моделью, prompt caching на статичном префиксе, при длинных задачах — явный план и сжатие наблюдений, чекпоинт для человека там, где действие необратимо, и лог причины остановки — это первое, куда смотришь при разборе."}],"kill":"<b>«ReAct — это think step by step»</b> — нет, это цикл, в котором инструменты исполняет твой код. И <b>«он сам остановится»</b> — не остановится, если инструмент продолжает падать."},
 en:{"topic":"ReAct and the agent loop","qs":["What is ReAct, and what problem does it solve compared to a single call?","Minimal implementation: what's inside the loop body?","Where does it break, and what do you add?"],"a":[{"q":"What it is","t":"Reason plus Act: the model reasons, picks an action — a tool call — gets an observation, reasons again, until there's a final answer. It solves what a single call can't: fetching information the model doesn't have, checking a hypothesis, multi-step work where the next step depends on the last result. A plain call can't fetch anything new or self-correct. Server-side tools like web search loop inside one request, but that's still a loop, run by the provider. Key point: the paper framed ReAct as a prompt format, but it only works with an outer loop in my code that executes actions and feeds back observations."},{"q":"Implementation","t":"A messages array and tool definitions. Call the model. If stop_reason is tool_use, take the name and arguments, execute them myself, append the result to messages as a tool_result, and go around again. If it's end_turn, that's the final answer, exit. Other stop reasons, like max_tokens, pause_turn or refusal, I handle explicitly, not as answers. Non-negotiable: a step cap, a spending budget, and tool errors returned as strings inside the tool_result rather than thrown — the model has to see them to react. That's literally my scout: five steps, six pages, and every step in the log."},{"q":"Where it breaks","t":"It loops on a failing tool. It drifts off-goal as the context grows and the original task sinks into the middle. It balloons in cost because every iteration resends the whole history — I had the same pages paid for three-plus times. What I add: a hard step cap and budget, distilling tool outputs with a cheap model, prompt caching on the static prefix, for long tasks an explicit plan and observation compression, a human checkpoint before anything irreversible, and a logged stop reason — it's the first thing you look at in a post-mortem."}],"kill":"<b>\"ReAct is think-step-by-step\"</b> — no, it's a loop where your code executes the tools. And <b>\"it'll stop on its own\"</b> — it won't, if the tool keeps failing."}},

{n:15,tag:"Core-40 #27",sec:"rag",core:[27],
 ru:{"topic":"RAG или всё в контекст","qs":["Когда RAG не нужен? Опиши случай, где ты его не стал бы делать.","Когда нужен: минимум четыре причины, не одна.","Окна уже по миллиону токенов. RAG умер?"],"a":[{"q":"Не нужен","t":"Если корпус помещается в контекст с запасом — скажем, десятки тысяч токенов, — меняется редко и цена за вызов приемлема, я просто кладу его целиком и включаю prompt caching. Никакого индекса, никаких промахов ретривера, никакой инфраструктуры. Половина проектов, которые называют себя RAG, — это хендбук на тридцать страниц, который влезает. Первый вопрос всегда: а сколько это в токенах? Если человек не измерил, он не выбирал архитектуру, он повторял модное слово."},{"q":"Нужен","t":"Первая — не помещается, самая очевидная. Вторая — цена: платить за двести тысяч токенов на каждый запрос, когда релевантных две тысячи, это в сто раз больше токенов и, даже с prompt caching (кэшированием промпта) по десятой части цены, примерно десятикратный перерасход плюс задержка. Третья — свежесть: документы обновляются, и переиндексировать проще, чем переписывать промпт. Четвёртая — точность: модель теряет середину длинного контекста, и релевантная выборка отвечает точнее полной свалки. И пятая, про которую забывают, — права доступа: разным пользователям видны разные документы, и фильтр на уровне ретривера это единственный честный способ."},{"q":"Умер?","t":"Нет, сдвинулся баланс. Длинный контекст убирает причину «не помещается», но не убирает цену, задержку, свежесть и права доступа. И качество внимания на длинных входах всё ещё проседает, когда нужная игла лежит среди похожих. Реалистичный паттерн сейчас — ретривер сужает до кандидатов, а большое окно позволяет отдавать куски крупнее и резать документы менее агрессивно. Правильный ответ на «RAG или контекст» — эвал на своих данных, а не вера."}],"kill":"<b>«RAG, потому что так делают»</b>. Первый вопрос интервьюера будет: сколько токенов в вашем корпусе? Если ответа нет — дальше можно не слушать."},
 en:{"topic":"RAG versus everything in context","qs":["When do you not need RAG? Describe a case where you'd skip it.","When you do need it: at least four reasons, not just one.","Context windows are a million tokens now. Is RAG dead?"],"a":[{"q":"Not needed","t":"If the corpus fits in context with room to spare — say tens of thousands of tokens — changes rarely, and the cost per call is acceptable, I put the whole thing in and turn on prompt caching. No index, no retriever misses, no infrastructure. Half the projects that call themselves RAG are a thirty-page handbook that fits. The first question is always: how many tokens is it? If someone hasn't measured, they didn't choose an architecture, they repeated a buzzword."},{"q":"Needed","t":"First reason — it doesn't fit, the obvious one. Second — cost: paying for two hundred thousand tokens per request when two thousand are relevant is a hundred times the tokens, and roughly ten times the cost even with prompt caching at a tenth of the price, plus latency. Third — freshness: documents update, and re-indexing is easier than rewriting a prompt. Fourth — precision: the model loses the middle of a long context, and a relevant selection answers more accurately than a full dump. And a fifth people forget — access control: different users can see different documents, and filtering at the retriever is the only honest way."},{"q":"Dead?","t":"No, the balance moved. Long context removes the doesn't-fit reason, but not cost, latency, freshness or permissions. And attention quality still degrades on long inputs when the needle sits among look-alikes. The realistic pattern now is retrieval narrowing to candidates, with the big window letting you pass larger chunks and split documents less aggressively. The right answer to RAG versus context is an eval on your own data, not a belief."}],"kill":"<b>\"RAG because that's what you do.\"</b> The interviewer's next question will be: how many tokens is your corpus? No answer, and the rest doesn't matter."}},

{n:16,tag:"Core-40 #28",sec:"rag",core:[28],
 ru:{"topic":"Chunking","qs":["Fixed size, semantic, sliding window: что это и в чём trade-off каждого?","Типичные цифры и зачем вообще существует overlap?","Как понять, что твой chunking неправильный?"],"a":[{"q":"Три подхода","t":"Fixed size — режу по N токенов. Просто, предсказуемо, режет мысль пополам. Semantic или структурный — режу по заголовкам, абзацам, блокам кода. Уважает смысл, но куски получаются разного размера, и большой абзац может не влезть. Sliding window — фиксированный размер с перекрытием, чтобы контекст на границе не терялся. На практике я делаю сначала структурный, поверх — потолок по размеру, и overlap как страховку. Один подход в чистом виде почти никогда не лучший."},{"q":"Цифры","t":"Обычный старт — двести пятьдесят шесть–пятьсот двенадцать токенов и перекрытие десять–двадцать пять процентов, но значения по умолчанию разнятся, поэтому подбираю по recall at k (полноте в top-k). Overlap нужен потому, что факт рядом с границей иначе окажется разрезан на два куска, и ни один не заэмбеддится так, чтобы его найти. Куски больше — больше контекста на попадание, но эмбеддинг усредняет смысл и становится мутнее. Меньше — точнее, но фрагментарно, и ответу не хватает окружения. И к каждому куску — метаданные: источник, раздел, позиция, иначе не процитируешь."},{"q":"Диагностика","t":"Два симптома. Кусок нашёлся релевантный, но ответ неполный — значит, кусок слишком мелкий или разрезан не там. Куски находятся как-то похожие, но не те — значит, слишком крупные, смысл размылся. Проверяю не чтением, а эвалом: на золотом наборе вопросов смотрю, попадает ли нужный пассаж в top-k. Это изолирует chunking и retrieval от генерации. Меняю размер, прогоняю снова, сравниваю. В моём RAG-проекте размер куска был ручкой, которую я крутил по метрике, а не по ощущению."}],"kill":"Назвать одно магическое число и остановиться. И <b>«chunking это деталь»</b> — это одна из самых частых причин плохого RAG, интервьюер это знает."},
 en:{"topic":"Chunking","qs":["Fixed size, semantic, sliding window: what are they and what's the trade-off of each?","Typical numbers, and why does overlap exist at all?","How do you know your chunking is wrong?"],"a":[{"q":"Three approaches","t":"Fixed size — cut every N tokens. Simple, predictable, splits a thought in half. Semantic or structural — cut on headings, paragraphs, code blocks. Respects meaning, but chunks come out uneven, and a big paragraph may not fit. Sliding window — fixed size with overlap so boundary context isn't lost. In practice I go structural first, a size cap on top, and overlap as insurance. One approach in pure form is almost never the best one."},{"q":"Numbers","t":"A common start is two fifty-six to five twelve tokens per chunk with ten to twenty-five percent overlap, but vendor defaults vary widely, so I tune against recall at k. Overlap exists because a fact near a boundary would otherwise be split across two chunks, and neither would embed in a way that finds it. Bigger chunks give more context per hit, but the embedding averages the meaning and gets muddier. Smaller is more precise but fragmentary, and the answer lacks surroundings. And every chunk carries metadata — source, section, position — or you can't cite it."},{"q":"Diagnosis","t":"Two symptoms. The retrieved chunk is relevant but the answer is incomplete — chunk too small, or cut in the wrong place. The retrieved chunks are vaguely similar but not the right ones — too big, meaning diluted. I check with an eval, not by reading: on a golden question set, does the gold passage land in the top-k? That isolates chunking and retrieval from generation. Change the size, run again, compare. In my RAG project chunk size was a knob I turned against a metric, not a feeling."}],"kill":"Quoting one magic number and stopping. And <b>\"chunking is a detail\"</b> — it's one of the most common causes of bad RAG, and the interviewer knows it."}},

{n:17,tag:"Core-40 #29",sec:"rag",core:[29],
 ru:{"topic":"Embeddings","qs":["Что такое эмбеддинг и что означает расстояние между двумя?","Cosine против dot product. Размерности. Где хранить.","Два случая, где семантический поиск промахивается, и что ты добавляешь."],"a":[{"q":"Что это","t":"Вектор из тысячи с лишним чисел, который энкодер строит так, чтобы тексты со схожим смыслом оказались рядом. Расстояние — это близость смысла, как её выучила модель на своих данных, а не абсолютная истина. Ключевое правило: запрос и документы — в одном пространстве эмбеддингов, обычно это одна модель. Некоторые семейства, вроде Voyage 4, делят пространство по дизайну, но смешал несвязанные модели — расстояния бессмысленны, тихая ошибка, которую находят через неделю."},{"q":"Метрики","t":"Cosine смотрит только на угол между векторами, игнорируя длину. Dot product учитывает и длину. Если векторы нормализованы до единичной длины — а большинство провайдеров возвращают именно такие, — это одно и то же, и dot product просто дешевле. Размерности: у OpenAI text-embedding-3-small — тысяча пятьсот тридцать шесть, у их же -large можно до трёх тысяч семидесяти двух; у моделей Voyage 4 по умолчанию тысяча двадцать четыре, а поддерживаются от двухсот пятидесяти шести до двух тысяч сорока восьми. Больше измерений — тоньше различия, но дороже хранить и медленнее искать; некоторые модели позволяют усекать вектор. Храню в Postgres с pgvector и индексом HNSW — на моём масштабе отдельная векторная база не нужна."},{"q":"Промахи","t":"Первый — точные идентификаторы: артикулы, имена, коды ошибок. Семантика их не различает, «ошибка 4017» и «ошибка 4071» рядом. Лечится гибридом с BM25, обычным лексическим поиском, и слиянием результатов. Второй — доменный сдвиг: модель училась на общем вебе, а у меня юридические или медицинские тексты, и расстояния теряют смысл. Лечится доменной моделью или реранкером, который читает пары внимательно. И ещё нюанс: запрос и документ — тексты разной природы, у некоторых моделей для них разные режимы."}],"kill":"<b>«Эмбеддинги понимают смысл»</b> без слов «относительно данных обучения». И путать cosine с dot product, когда векторы нормализованы — это одно и то же."},
 en:{"topic":"Embeddings","qs":["What is an embedding, and what does the distance between two mean?","Cosine versus dot product. Dimensions. Where do you store them?","Two cases where semantic search misses, and what you add."],"a":[{"q":"What it is","t":"A vector of a thousand-odd numbers that an encoder produces so that texts with similar meaning land close together. Distance is semantic closeness as the model learned it from its training data, not absolute truth. The key rule: query and documents must share one embedding space, normally the same model. Some families, like Voyage 4, share a space by design, but mix unrelated models and the distances mean nothing — a silent bug found a week later."},{"q":"Metrics","t":"Cosine looks only at the angle between vectors and ignores length. Dot product includes length. If the vectors are normalised to unit length — and most providers return them that way — the two are identical, and dot product is simply cheaper. Dimensions: OpenAI's text-embedding-3-small is fifteen thirty-six, their -large goes up to three thousand seventy-two; the Voyage 4 models default to ten twenty-four and support two fifty-six up to two thousand forty-eight. More dimensions, finer distinctions, but more storage and slower search; some models let you truncate the vector. I store in Postgres with pgvector and an HNSW index — at my scale a separate vector database isn't justified."},{"q":"Misses","t":"First — exact identifiers: part numbers, names, error codes. Semantics doesn't separate them; error 4017 and error 4071 sit side by side. The fix is hybrid search with BM25, plain lexical matching, and merging the two result lists. Second — domain shift: the model was trained on the general web and my documents are legal or medical, so distances lose meaning. The fix is a domain model or a reranker that reads the pairs carefully. One more nuance: a query and a document are different kinds of text, and some models have separate modes for each."}],"kill":"<b>\"Embeddings understand meaning\"</b> without adding \"relative to their training data\". And confusing cosine with dot product when the vectors are normalised — they're the same thing."}},

{n:18,tag:"Core-40 #30",sec:"rag",core:[30],
 ru:{"topic":"Top-k и reranking","qs":["Что такое k и как ты его выбираешь?","Что делает реранкер и почему он второй стадией, а не первой?","Цена и задержка реранкинга. Когда его пропускаешь?"],"a":[{"q":"k","t":"k — сколько кандидатов я вытаскиваю из векторного индекса, обычно от пяти до двадцати. Слишком мало — нужный пассаж не попадает вообще. Слишком много — в контекст идёт шум, растёт цена, и модель теряет нужное посередине. Выбираю не по интуиции, а по recall at k на золотом наборе: наименьшее k, при котором нужный пассаж почти всегда внутри. Это одна из самых дешёвых метрик во всём пайплайне, она детерминирована и не требует LLM-судьи."},{"q":"Реранкер","t":"Первая стадия — embedding search — быстрая и приближённая: запрос и документ кодируются по отдельности и никак не взаимодействуют. Реранкер — это cross-encoder: он читает запрос и каждого кандидата вместе и оценивает релевантность точно. Прогнать его по всему корпусу нельзя, слишком дорого. Поэтому схема: достать пул пошире, примерно до ста пятидесяти, переранжировать и оставить верхние, от трёх до двадцати по бюджету контекста; у Anthropic из ста пятидесяти оставляли двадцать. Cohere или Voyage по API, либо локальный cross-encoder. У меня в пайплайне он стоит после retrieval, и это была одна из ручек, которые я крутил по эвалу."},{"q":"Цена","t":"Это ещё один сетевой вызов, обычно сто–триста миллисекунд, и оплата за поиск или за токены, смотря по вендору; длинные документы дороже в любом случае. Пропускаю, когда корпус крошечный, когда k и так маленькое, или когда бюджет задержки жёсткий. Добавляю, когда точность важнее — ответы цитируют не тот документ — или когда корпус большой и грязный. Решение измеряю: precision в top-3 с реранкером и без. Если разницы нет, лишний вызов не нужен."}],"kill":"<b>«Реранкинг — просто ещё раз отсортировать по score»</b> — нет, это другая модель, которая читает пары. И <b>k равно одному</b> — тогда любой промах ретривера фатален."},
 en:{"topic":"Top-k and reranking","qs":["What is k, and how do you choose it?","What does a reranker do, and why is it a second stage rather than the first?","Cost and latency of reranking. When do you skip it?"],"a":[{"q":"k","t":"k is how many candidates I pull from the vector index, usually five to twenty. Too few and the right passage doesn't show up at all. Too many and the context fills with noise, cost rises, and the model loses the relevant bit in the middle. I choose it by recall at k on a golden set, not intuition: the smallest k where the gold passage is almost always inside. It's one of the cheapest metrics in the whole pipeline — deterministic, no LLM judge needed."},{"q":"Reranker","t":"The first stage — embedding search — is fast and approximate: query and document are encoded separately and never interact. A reranker is a cross-encoder: it reads the query and each candidate together and scores relevance precisely. You can't run it over the whole corpus, far too expensive. So the pattern is: retrieve a wider pool, up to a hundred fifty or so, rerank, keep the top three to twenty by context budget; Anthropic went from a hundred fifty to twenty. Cohere or Voyage over an API, or a local cross-encoder. In my pipeline it sits after retrieval, and it was one of the knobs I tuned against the eval."},{"q":"Cost","t":"It's another network call, typically a hundred to three hundred milliseconds, billed per search or per token depending on the vendor, and long documents cost more either way. I skip it when the corpus is tiny, when k is small anyway, or when the latency budget is tight. I add it when precision matters more — answers citing the wrong document — or when the corpus is large and noisy. I measure the decision: precision at three with and without the reranker. No difference, no extra call."}],"kill":"<b>\"Reranking is just sorting by score again\"</b> — no, it's a different model that reads the pairs. And <b>k equals one</b> — then any retriever miss is fatal."}},

{n:19,tag:"Core-40 #31",sec:"rag",core:[31],
 ru:{"topic":"RAG: где ломается и как мерить","qs":["Четыре места, где RAG ломается. По стадиям.","Метрики: faithfulness, relevance, recall. Определи и скажи, как мерить каждую.","Как ты построил эвал для своего RAG? Что именно в наборе?"],"a":[{"q":"Четыре места","t":"Ингестия: плохой парсинг PDF или неверный chunking, и знание вообще не попало в индекс как надо. Retrieval miss: нужный пассаж не в top-k, потому что запрос сформулирован иначе или эмбеддинг не различает. Ранжирование: пассаж есть, но закопан на пятнадцатом месте и в контекст не попал. Генерация: модель игнорирует контекст, отвечает из головы или добавляет то, чего в контексте нет. Главный принцип — диагностировать по стадиям, а не смотреть на итоговый ответ: иначе непонятно, что чинить."},{"q":"Метрики","t":"Recall, или hit rate: попал ли нужный пассаж в выборку. Нужен размеченный набор, зато считается детерминированно и мгновенно. Context relevance, или precision: простой precision at k — доля вытащенных кусков по делу, а context precision в RAGAS учитывает ранжирование: релевантные должны стоять выше. Faithfulness, или groundedness: каждое утверждение в ответе подтверждается вытащенным контекстом — мерю LLM-судьёй со строгой рубрикой или проверкой цитат. Answer relevance: ответ отвечает на вопрос, а не на соседний. Ключевое — разделять метрики retrieval и метрики генерации: первые дешёвые и точные, вторые дорогие и шумные."},{"q":"Мой эвал","t":"Золотой набор: вопросы, к каждому — ожидаемый исходный пассаж и факты, которые должны быть в ответе. Прогоняю пайплайн, recall at k считаю автоматически. Для faithfulness — LLM-судья с рубрикой, и выборочно проверяю судью руками, потому что судья тоже ошибается. Гоняю на каждый коммит, чтобы смена размера куска отражалась числом, а не впечатлением. Набор небольшой, и это нормально: тридцать–пятьдесят хороших вопросов лучше, чем ноль. Именно поэтому я могу сказать, что пайплайн работает, а не утверждать это."}],"kill":"<b>«Работает, я потыкал пару вопросов»</b>. И мерить только end-to-end: ответ плохой, а какая из четырёх стадий виновата — неизвестно."},
 en:{"topic":"RAG: where it breaks and how to measure","qs":["Four places RAG breaks. By stage.","Metrics: faithfulness, relevance, recall. Define each and say how you measure it.","How did you build the eval for your RAG? What exactly is in the set?"],"a":[{"q":"Four places","t":"Ingestion: bad PDF parsing or wrong chunking, so the knowledge never made it into the index properly. Retrieval miss: the right passage isn't in the top-k, because the query is phrased differently or the embedding doesn't separate them. Ranking: the passage is there but buried at position fifteen and never reaches the context. Generation: the model ignores the context, answers from memory, or adds things the context doesn't say. The principle is to diagnose by stage, not by looking at the final answer — otherwise you don't know what to fix."},{"q":"Metrics","t":"Recall, or hit rate: did the gold passage make it into the retrieved set. Needs a labelled set, but it's deterministic and instant. Context relevance, or precision: plain precision at k is the fraction of retrieved chunks that are on-topic, while RAGAS's context precision is ranking-aware and rewards relevant chunks sitting higher. Faithfulness, or groundedness: every claim in the answer is supported by retrieved context — measured with an LLM judge on a strict rubric, or citation checks. Answer relevance: it answers the question asked, not a neighbouring one. The key is separating retrieval metrics from generation metrics — the first are cheap and exact, the second expensive and noisy."},{"q":"My eval","t":"A golden set: questions, and for each one the expected source passage and the facts the answer must contain. I run the pipeline and compute recall at k automatically. For faithfulness, an LLM judge with a rubric, and I spot-check the judge by hand because judges are wrong too. It runs on every commit, so a chunk-size change shows up as a number rather than an impression. The set is small, and that's fine: thirty to fifty good questions beat zero. It's the reason I can say the pipeline works instead of claiming it."}],"kill":"<b>\"It works, I tried a few questions.\"</b> And measuring only end-to-end: the answer is bad and which of the four stages is at fault stays unknown."}},

{n:20,tag:"Core-40 #35 · system design",sec:"sysd",core:[35],
 ru:{"topic":"Дизайн: streaming chat UI","qs":["Спроектируй стриминговый чат. Компоненты от браузера до модели, по порядку.","Состояние на клиенте: что хранишь, как рендеришь частичный ответ, где живёт история.","UX отказов: retry, cancel, ошибка посреди потока. И что ты логируешь."],"a":[{"q":"Компоненты","t":"Браузер никогда не ходит в модель напрямую — ключ утечёт, и контроля нет. Браузер ходит в мой API route. Сервер принимает новое сообщение пользователя и id разговора, сам восстанавливает историю из базы, добавляет system prompt, вызывает провайдера со stream: true и проксирует SSE клиенту. По завершении сохраняет ответ ассистента вместе с usage. Клиент делает fetch с POST, читает ReadableStream, дописывает дельты. Историю клиент не присылает: доверять клиентской истории нельзя ни по цене, ни по безопасности — её подменят."},{"q":"Состояние","t":"Массив сообщений, у каждого статус: pending, streaming, done, error. Частичный текст дописываю в контент стримящегося сообщения, рендер батчу через requestAnimationFrame, а не на каждый токен. Markdown рендерю инкрементально, с оговоркой: незакрытый блок кода посреди потока ломает разметку, это надо обрабатывать. Сообщение пользователя показываю оптимистично сразу. Автоскролл вниз — только если пользователь сам не проскроллил вверх. Стоимость и токены на сообщение — из usage в конце. Обрезка длинной истории — на сервере: скользящее окно или саммари, клиент об этом не знает."},{"q":"Отказы","t":"Стоп — через AbortController, и сервер тоже прерывает вызов к провайдеру, чтобы не платить за то, что уже никто не читает. Обрыв — частичный текст остаётся на экране с пометкой, retry шлёт тот же id, чтобы сервер не задублировал сообщение. Ошибки различаю: 429 — backoff и повтор, перегрузка провайдера — повтор, слишком длинный запрос — честно сказать пользователю. Логирую request id, время до первого токена, общее время, stop_reason, usage и модель. Именно по этим полям потом разбираешь «почему тормозит»."}],"kill":"<b>Ключ API в браузере</b> — дисквалификация. И <b>перерендер всего markdown на каждый токен</b> — чат начнёт лагать на длинных ответах, и это увидят на демо."},
 en:{"topic":"Design: streaming chat UI","qs":["Design a streaming chat. Components from the browser to the model, in order.","Client state: what you store, how you render partial output, where history lives.","Failure UX: retry, cancel, an error mid-stream. And what you log."],"a":[{"q":"Components","t":"The browser never talks to the model directly — the key leaks and you have no control. The browser calls my API route. The server takes the new user message and a conversation id, rebuilds the history from the database itself, adds the system prompt, calls the provider with stream: true, and proxies the SSE to the client. On completion it persists the assistant message along with usage. The client does a POST fetch, reads the ReadableStream, appends deltas. The client never sends history: you can't trust client-supplied history for cost or for safety — it'll get tampered with."},{"q":"State","t":"An array of messages, each with a status: pending, streaming, done, error. Partial text appends to the streaming message's content, and I batch renders on requestAnimationFrame rather than per token. Markdown renders incrementally, with one caveat: an unclosed code fence mid-stream breaks the layout, so that needs handling. The user's message shows optimistically right away. Auto-scroll to the bottom only if the user hasn't scrolled up. Cost and tokens per message come from usage at the end. Trimming a long history happens on the server — sliding window or summary — and the client doesn't know about it."},{"q":"Failures","t":"Stop goes through an AbortController, and the server also aborts the provider call so nobody pays for output no one is reading. On a drop, the partial text stays on screen with a marker, and retry sends the same id so the server doesn't duplicate the message. I distinguish errors: 429 means back off and retry, provider overload means retry, request too long means tell the user honestly. I log request id, time to first token, total time, stop_reason, usage and model. Those are the fields you use later to answer why it feels slow."}],"kill":"<b>API key in the browser</b> — disqualifying. And <b>re-rendering all the markdown on every token</b> — the chat starts to lag on long answers, and it shows during the demo."}},

{n:21,tag:"Core-40 #36 · system design",sec:"sysd",core:[36],
 ru:{"topic":"Дизайн: RAG end-to-end","qs":["Пройди пайплайн от загрузки документа до ответа. Каждая стадия и выбор на ней.","Хранение и индекс: pgvector или отдельная база? Метаданные, обновления, удаления.","Обслуживание запросов: бюджет задержки, кэш, цитаты, права доступа, мониторинг."],"a":[{"q":"Пайплайн","t":"Загрузка, потом парсинг — PDF и HTML в текст, и это недооценённая стадия: таблицы и вёрстка ломаются чаще всего. Chunking с учётом структуры, двести–пятьсот токенов, с перекрытием. Эмбеддинг одной моделью, батчами. Хранение: текст куска, метаданные и вектор. На запросе: эмбеддю вопрос, достаю top-20, опционально гибрид с BM25, реранкер до пяти, собираю промпт с пронумерованными кусками и инструкцией отвечать только из контекста и ставить ссылки на номера. Генерирую, проверяю цитаты постобработкой, отдаю ответ вместе с источниками."},{"q":"Хранение","t":"pgvector с индексом HNSW (приближённый поиск соседей) — когда Postgres уже есть и корпус умеренный: одна база, транзакции, и права доступа через обычный join. В документации есть только лимит Postgres в 32 ТБ на непартиционированную таблицу, а порога производительности нет, поэтому меряю на своих данных. Отдельная векторная база — на масштабе или когда нужна продвинутая фильтрация и скорость. Метаданные обязательны: id документа, тенант или пользователь, раздел, версия, время. Обновление документа — перечанкить его и удалить старые куски по id документа; поле версии спасает от устаревших кусков, которые иначе живут вечно. Ингестия должна быть идемпотентной: повторная загрузка не плодит дубли."},{"q":"Обслуживание","t":"Бюджет примерный: эмбеддинг запроса и поиск по индексу — малая часть, реранкер сто–триста миллисекунд, генерация одна–три секунды, со стримингом. Кэширую эмбеддинги запросов, а ответы на повторы — семантическим кэшем. Фильтр по тенанту — внутри запроса, через WHERE или namespace, а не в коде после выдачи, где одна забытая проверка сливает чужие данные. С HNSW pgvector применяет WHERE после сканирования индекса, и селективный фильтр может недобрать строк; лечится итеративным сканированием, частичным индексом или партицией на тенанта. Цитаты принудительные: утверждения без куска-источника выбрасываются. Мониторю recall на золотом наборе, faithfulness, перцентили задержки, стоимость ответа и долю «контекст не найден»."}],"kill":"Забыть парсинг и права доступа. И описать только счастливый путь — интервьюер спросит «как узнаете, что стало хуже?», и без эвала ответа нет."},
 en:{"topic":"Design: RAG end-to-end","qs":["Walk the pipeline from document upload to answer. Every stage and the choice at it.","Storage and indexing: pgvector or a dedicated store? Metadata, updates, deletes.","Serving: latency budget, caching, citations, permissions, monitoring."],"a":[{"q":"Pipeline","t":"Upload, then parsing — PDF and HTML to text, and it's the underrated stage: tables and layout break most often. Structure-aware chunking, two to five hundred tokens, with overlap. Embedding with one model, in batches. Storage: chunk text, metadata and the vector. At query time: embed the question, pull the top twenty, optionally hybrid with BM25, rerank down to five, build the prompt with numbered chunks and an instruction to answer only from context and cite by number. Generate, verify the citations in post-processing, return the answer with its sources."},{"q":"Storage","t":"pgvector with an HNSW index when Postgres already exists and the corpus is moderate: one database, transactions, and permissions through an ordinary join. The only documented ceiling is Postgres's 32 TB per non-partitioned table, not a performance threshold, so I benchmark on my own data. A dedicated vector store at scale, or when you need advanced filtering and speed. Metadata is mandatory: document id, tenant or user, section, version, timestamp. Updating a document means re-chunking it and deleting the old chunks by document id; a version field saves you from stale chunks that otherwise live forever. Ingestion has to be idempotent: uploading twice doesn't create duplicates."},{"q":"Serving","t":"Rough budget: query embedding and index search are the small part, the reranker a hundred to three hundred milliseconds, generation one to three seconds, streamed. I cache query embeddings, and answers to recurring questions — a semantic cache. The tenant filter lives inside the query, a WHERE clause or a namespace, never in app code after retrieval, where one missed check leaks data. With HNSW, pgvector applies WHERE after the index scan, so a selective filter can return too few rows; iterative scans, partial indexes or per-tenant partitions fix it. Citations are enforced: unsupported claims get dropped. I monitor golden-set recall, faithfulness, latency percentiles, cost per answer and the no-context rate."}],"kill":"Forgetting parsing and permissions. And describing only the happy path — the interviewer will ask how you'd know it got worse, and without an eval there's no answer."}},

{n:22,tag:"Core-40 #37 · system design",sec:"sysd",core:[37],
 ru:{"topic":"Дизайн: экономика LLM-продукта","qs":["Счёт вырос в три раза за месяц. Как находишь, где?","Лестница рычагов, по соотношению эффекта и усилий.","Что кэширование не чинит? Пример из своего кода."],"a":[{"q":"Поиск","t":"Сначала измеряю, потом трогаю. Инструментирую каждый вызов: модель, input, output и cache-токены, фича, пользователь. Группирую по фиче и модели — почти всегда доминирует один шаг. Смотрю структуру: output в несколько раз дороже input за токен, по текущим прайсам Claude и OpenAI примерно в пять раз, но в агентах обычно доминирует input из-за пересылки истории. Ищу типовые причины: цикл без потолка, растущая история, многословные ответы, дорогая модель на массовом шаге. Пока нет разбивки по шагам, любое «давайте оптимизируем» — это гадание."},{"q":"Лестница","t":"Роутинг моделей — самый большой рычаг: у Claude Opus дороже Haiku за токен примерно в четыре раза, а топовый уровень — примерно в десять; у OpenAI разрыв между флагманом и самой маленькой моделью — на порядок и больше. Цены двигаются, поэтому сверяюсь с текущим прайсом, но массовым шагам флагман редко нужен. Prompt caching на статичном префиксе: запись дороже, чтение — около десятой части цены. Короче выходы: max_tokens, сжатый формат, структура вместо прозы. Сжатие входов: дешёвая модель пересказывает страницы до того, как их прочитает дорогая. Обрезка истории — окно или саммари. Batch API — половина цены, если результат не нужен сразу. Семантический кэш для повторных вопросов. Prompt compression — в последнюю очередь, это уже мелкая доводка. Порядок — по соотношению усилия к эффекту."},{"q":"Не чинит","t":"Кэширование чинит пересылку, а не объём. Если в модель летит двадцать тысяч символов сырого HTML, кэш делает дешёвой вторую отправку, но первая и каждая новая страница стоят полную цену. У меня так и вышло: после включения кэша он дал полтора раза, и при этом cache writes стали шестьюдесятью процентами счёта. Следующий шаг был не кэш, а роутинг: дешёвая модель ужимает страницы до того, как их видит дорогая. И ещё: кэшу нужен стабильный префикс — timestamp в начале system prompt ломает его полностью, и это видно только по цифрам."}],"kill":"<b>«Возьмите модель подешевле»</b> как весь ответ, без измерений. И утверждать, что <b>кэш решает всё</b> — интервьюер спросит про первую отправку."},
 en:{"topic":"Design: LLM product economics","qs":["The bill tripled this month. How do you find where?","The ladder of levers, in order of impact per effort.","What can't caching fix? An example from your own code."],"a":[{"q":"Finding it","t":"Measure first, touch second. I instrument every call: model, input, output and cache tokens, feature, user. Group by feature and model — one step almost always dominates. Look at the structure: output costs several times more per token than input, about five times on current Claude and OpenAI price lists, but in agents input usually dominates because of history resends. Then the usual suspects: a loop with no cap, a growing history, verbose outputs, an expensive model on a bulk step. Without a per-step breakdown, any let's-optimise is guessing."},{"q":"The ladder","t":"Model routing is the biggest lever: on Claude, Opus costs about four times Haiku per token and the top tier about ten times; at OpenAI the gap between the flagship and the smallest model is an order of magnitude or more. Prices move, so I check the current list, but bulk steps rarely need a flagship. Prompt caching on the static prefix: writes cost more, reads are about a tenth of the price. Shorter outputs: max_tokens, a terse format, structure instead of prose. Input distillation: a cheap model summarises pages before the expensive one reads them. History trimming — window or summary. The batch API — half price when the result isn't needed immediately. A semantic cache for repeated questions. Prompt compression last; that's marginal tuning. The order is effort against impact."},{"q":"Can't fix","t":"Caching fixes resending, not volume. If twenty thousand characters of raw HTML go into the model, the cache makes the second send cheap, but the first send and every new page still cost full price. That's exactly what happened to me: turning on caching gave one and a half times, and cache writes became sixty percent of the bill. The next step wasn't more caching, it was routing — a cheap model shrinks the pages before the expensive one sees them. One more: caching needs a stable prefix. A timestamp at the top of the system prompt breaks it entirely, and you only see it in the numbers."}],"kill":"<b>\"Use a cheaper model\"</b> as the whole answer, with no measurement. And claiming <b>caching solves everything</b> — the interviewer will ask about the first send."}},

{n:23,tag:"Core-40 #38 · behavioral",sec:"behav",core:[38],
 ru:{"topic":"Tell me about yourself","qs":["Версия на 60–90 секунд. Скажи её целиком.","Версия на 30 секунд для рекрутера.","Чего ты никогда не говоришь и чем заканчиваешь?"],"a":[{"q":"90 секунд","t":"Я senior frontend-инженер, около десяти лет, строил продуктовые интерфейсы. Сейчас в Dats.Team вёл миграцию на Next.js App Router и интернационализацию больше чем на пятьдесят стран. Примерно год назад начал публично строить AI-продукты. Собрал полный RAG-пайплайн — chunking, эмбеддинги, retrieval, reranking — с эвал-сьютом, он живёт на сайте. Сейчас строю research-агента на TypeScript и Anthropic SDK: по имени компании собирает структурированное досье со ссылками на источники. Ищу роль product engineer в небольшом AI-стартапе — там, где моя фронтовая глубина и AI-работа нужны с первого дня одновременно."},{"q":"30 секунд","t":"Senior frontend, десять лет продуктовых интерфейсов. Последний год строю AI-продукты публично: RAG с эвалами на сайте, сейчас research-агент на Anthropic SDK. Ищу product engineer в AI-стартапе. Всё. Рекрутер услышал уровень, доказательство и куда тебя ставить — больше ему на этом этапе не нужно."},{"q":"Запреты","t":"Никогда: «career switcher», «learning AI», «transitioning», «trying to get into». Это язык человека, который просит поверить на слово. Ты senior-инженер, который строит AI-продукты — это факт, у него есть ссылки. И заканчиваешь не хронологией, а запросом: какую роль ищешь и почему именно такую. Тогда интервьюер знает, что с тобой делать. Ответ без посадки — «…ну вот, как-то так» — стирает всё, что было до него."}],"kill":"Хронология с 2016 года. И любое слово из списка «switcher / learning / transitioning» — после него весь остальной ответ слушают как оправдание."},
 en:{"topic":"Tell me about yourself","qs":["The 60–90 second version. Say the whole thing.","The 30-second version, for a recruiter.","What do you never say, and how do you land it?"],"a":[{"q":"90 seconds","t":"I'm a senior frontend engineer with about ten years of experience — I've spent my career shipping product UIs. Right now I'm at Dats.Team, where I led a migration to the Next.js App Router and built internationalization for more than fifty countries. About a year ago I started building AI products in public. I shipped a full RAG pipeline — chunking, embeddings, retrieval, reranking — with an eval suite, and it's live on my site. Now I'm building a research agent in TypeScript on the Anthropic SDK: it takes a company name and produces a structured, fully-cited dossier. I'm looking for a product engineer role at a small AI startup — a place where my frontend depth and my AI engineering work are both useful from day one."},{"q":"30 seconds","t":"Senior frontend engineer, ten years of shipping product UIs. For the last year I've been building AI products in public — a RAG pipeline with evals that's live on my site, and now a research agent on the Anthropic SDK. I'm looking for a product engineer role at an AI startup. That's it. The recruiter heard the level, the proof, and where to place you — nothing else is needed at this stage."},{"q":"Never","t":"Never: career switcher, learning AI, transitioning, trying to get into. That's the language of someone asking to be taken on faith. You're a senior engineer who builds AI products — it's a fact, and it has links. And you land on the ask, not on chronology: which role you want and why that one. Then the interviewer knows what to do with you. An answer with no landing — so, yeah, that's me — erases everything before it."}],"kill":"A chronology starting in 2016. And any word from the switcher / learning / transitioning list — after it, the rest of the answer is heard as an apology."}},

{n:24,tag:"Core-40 #39 · behavioral",sec:"behav",core:[39],
 ru:{"topic":"История пивота","qs":["Почему из фронта в AI? Факты, не страсть.","Это не шаг вниз по сеньорности?","Что ты реально зашипил? Конкретно, с цифрами."],"a":[{"q":"Почему","t":"Если честно — я помню, каким был фронт десять лет назад: каждая задача новая, готовых паттернов нет. Сегодня большая часть фронта — это сборка известного, и именно эту часть автоматизируют AI-инструменты. А работа с LLM сейчас ощущается как фронт в 2016: молодая экосистема, настоящие инженерные проблемы, никакого учебника. Поэтому я не ждал, а начал шипить. RAG-проект живёт на сайте с девятью из девяти на эвале, research-агент в процессе, всё в открытом доступе. Я не убегаю от фронта — я приношу десять лет продуктовой инженерии в ту часть стека, где они сейчас нужнее всего."},{"q":"Не вниз?","t":"Нет, и вот почему. Title, который я ищу, — product engineer, а не junior AI кто-то. В маленьких AI-компаниях фронтовая глубина — это senior-навык: у них продукт для разработчиков, и интерфейс — половина продукта. Я не бросаю десять лет, я приношу их в ту часть стека, которая сейчас в них нуждается больше всего. И год позади — это не курсы, а рабочие системы с измерениями. Это горизонтальный шаг с расширением, а не спуск."},{"q":"Зашипил","t":"Конкретика: RAG-пайплайн целиком — chunking, embeddings, retrieval, reranking — с эвал-набором, девять из девяти, живёт на сайте. Research-агент на TypeScript и Anthropic SDK: цикл с инструментами, каждое утверждение — со ссылкой на источник, инструментирована стоимость каждого шага. На нём я измерил prompt caching: полтора раза на одном прогоне, корректным A/B внутри запуска. Дальше роутинг: дешёвая модель ужимает страницы до дорогой. Всё в открытом доступе. Цифры — потому что интервьюер запомнит одно число, а не три прилагательных."}],"kill":"<b>«Passion»</b>, <b>«всегда интересовался»</b>, туман вместо цифр. И извиняющаяся интонация — ты объясняешь решение, а не оправдываешься."},
 en:{"topic":"The pivot story","qs":["Why move from frontend to AI? Facts, not passion.","Isn't this a step down in seniority?","What have you actually shipped? Be specific, with numbers."],"a":[{"q":"Why","t":"Honestly? I remember how frontend felt ten years ago — every problem was new, and I was building things that hadn't existed before. Today most frontend work is assembling known patterns, and AI tools are automating exactly that part. Meanwhile, building with LLMs feels like frontend felt in 2016: young ecosystem, real engineering problems, no established playbook. So I didn't wait — I started shipping. My RAG project is live with a nine-out-of-nine eval score, my research agent is in progress, everything is public. I'm not running away from frontend — I'm bringing ten years of product engineering into the part of the stack where it matters most right now."},{"q":"Not a step down","t":"No, and here's why. The title I'm going for is product engineer, not junior AI anything. At small AI companies frontend depth is a senior skill — the product is for developers, and the interface is half the product. I'm not throwing away ten years, I'm bringing them into the part of the stack that needs them most right now. And the last year wasn't courses, it was working systems with measurements. That's a lateral move with a wider scope, not a descent."},{"q":"Shipped","t":"Specifics: a full RAG pipeline — chunking, embeddings, retrieval, reranking — with an eval set, nine out of nine, live on my site. A research agent in TypeScript on the Anthropic SDK: a tool-use loop, every claim carries a source URL, and the cost of every step is instrumented. On it I measured prompt caching — one and a half times on a single run, with a proper within-run A/B. Then routing: a cheap model shrinks pages before the expensive one reads them. All of it is public. Numbers, because the interviewer will remember one number and not three adjectives."}],"kill":"<b>Passion</b>, <b>always been interested</b>, fog instead of figures. And an apologetic tone — you're explaining a decision, not defending one."}},

{n:25,tag:"Core-40 #40 · behavioral",sec:"behav",core:[40],
 ru:{"topic":"Три STAR-истории","qs":["Сложная техническая задача, которую ты решил. STAR, 90 секунд.","Провал и что ты изменил навсегда. STAR, 90 секунд.","Правила формы: как удержать любую историю в 90 секундах и чем она обязана заканчиваться?"],"a":[{"q":"Техническая","t":"В Dats.Team у нас было большое Next.js-приложение на старом Pages Router, и нужно было отдавать локализованный контент больше чем в пятьдесят стран. Я владел миграцией на App Router и всем слоем интернационализации. Я спланировал инкрементальную миграцию, чтобы продукт продолжал шипиться (выходить в релизы): маршрут за маршрутом, next-intl для переводов, SWR для клиентского кэша и оптимизации сборки, чтобы пятьдесят локалей не взорвали build. Мы мигрировали без заморозки фич, и i18n сейчас обслуживает пятьдесят с лишним стран из одной кодовой базы. Инкрементальная миграция под живым трафиком — тот же навык, которым я сейчас строю AI-системы: шипить маленькими шагами, мерить, двигаться дальше."},{"q":"Провал","t":"Рабочий черновик, кандидат — перформанс-история на Formind, но с двумя цифрами в скобках, которые нужно сверить по своим записям, прежде чем произносить это вслух на интервью: «Я задеплоил оптимизацию бандла, не измерив её на реальном трафике заранее — после релиза заметил регрессию по загрузке у пользователей на медленных сетях, и прошло [X дней], прежде чем я поймал её через мониторинг. Дело было в том, что я оптимизировал под свою локальную сеть и синтетический бенчмарк, а не под p95 реальных юзеров. Сразу откатил и добавил алерт на [метрика] в проде. Навсегда изменил: с тех пор ни один perf-релиз не уходит без A/B на реальном трафике и без порогового алерта на p95, а не на average — именно это поймало бы регрессию до жалоб юзеров, а не после». Три бита обязательны: что пошло не так и почему — «я допустил», не «случилось»; что сделал немедленно; что изменил навсегда — процесс, проверка, метрика. Без третьего это история про везение, а не про провал. Что сделать до собеса: вписать [X дней] и [метрика] реальными цифрами из своих записей — до этого это скелет, а не история."},{"q":"Форма","t":"Ситуации и задаче — по одному-два предложения, а больше всего времени уходит на действие: что именно сделал я. Ситуация без предыстории компании — интервьюер не знает вашей оргструктуры и не хочет. «Я», а не «мы»: интервьюер оценивает тебя, а «мы» прячет твой вклад. В результате обязана быть цифра или наблюдаемый факт — иначе результат не отличить от намерения. Заканчиваешь предложением-посадкой: что это значит для роли, на которую ты претендуешь. Репетировать вслух, с таймером, пока не станет скучно. Скучно — значит готово."}],"kill":"История без цифры в результате. И «мы сделали» вместо «я сделал» — интервьюер записывает: вклад неясен."},
 en:{"topic":"Three STAR stories","qs":["A hard technical problem you solved. STAR, 90 seconds.","A failure and what you changed permanently. STAR, 90 seconds.","Rules of form: how do you keep any story to 90 seconds, and what must it end with?"],"a":[{"q":"Technical","t":"At Dats.Team we had a large Next.js app on the old Pages Router, and we needed to serve localized content for over fifty countries. I owned the migration to the App Router and the whole internationalization layer. I planned an incremental migration so the product kept shipping — route by route, with next-intl for translations, SWR for client caching, and build-time optimizations so fifty locales didn't explode our build. We migrated without freezing feature work, and the i18n system now serves fifty-plus countries from one codebase. The pattern I used — incremental migration under live traffic — is the same muscle I now use for AI systems: ship small, measure, keep moving."},{"q":"Failure","t":"Working draft, candidate is the Formind performance work, with two numbers in brackets to verify against my own notes before saying this out loud in an interview: \"I shipped a bundle optimization without measuring it against real traffic first — after release I noticed a load-time regression for users on slow networks, it took [X days] before I caught it through monitoring. The root cause: I'd optimized against my own local network and a synthetic benchmark, not against real users' p95. I rolled it back immediately and added an alert on [metric] in production. What changed permanently: no perf release ships without an A/B against real traffic and a p95 threshold alert, not an average one — that's what would've caught the regression before user complaints, not after.\" Three beats are mandatory: what went wrong and why — I let it happen, not it happened; what I did immediately; what I changed permanently — a process, a check, a metric. Without the third part it's a story about luck, not a failure story. Action item before the interview: fill [X days] and [metric] with the real numbers from my notes — until then this is a skeleton, not a story."},{"q":"Form","t":"Situation and task get a sentence or two each, and most of the time goes to the action — what I specifically did. Situation without company backstory — the interviewer doesn't know your org chart and doesn't want to. I, not we: they're evaluating you, and we hides your contribution. The result must contain a number or an observable fact — otherwise a result is indistinguishable from an intention. End on a landing sentence: what this means for the role you're interviewing for. Rehearse out loud with a timer until it's boring. Boring means ready."}],"kill":"A story with no number in the result. And we did instead of I did — the interviewer writes down: contribution unclear."}},

{n:26,tag:"Core-40 #1–8 · parked check",sec:"parked",core:[1,2,3,4,5,6,7,8,42],
 ru:{"topic":"JS/TS: проверка запаркованного","qs":["setTimeout(0) и Promise.resolve().then() — что раньше и почему? И почему forEach с await не ждёт?","Классический баг closure с циклом и setTimeout до ES6. И четыре правила this плюс исключение для стрелок.","Реализуй Pick<T, K> руками. Зачем discriminated union вместо optional-полей?"],"a":[{"q":"Event loop","t":"Микрозадачи всегда раньше макрозадач: после текущего синхронного кода движок опустошает очередь микрозадач целиком — промисы, queueMicrotask — и только потом берёт одну макрозадачу вроде setTimeout. Поэтому then выполнится первым даже при нуле. Между этим движок может (не обязан) отрендерить кадр — в браузере это происходит после опустошения микрозадач и перед следующей макрозадачей, поэтому длинная цепочка промисов без единой макрозадачи между ними может держать UI без перерисовки дольше, чем кажется. forEach с await не ждёт, потому что forEach не смотрит на возвращаемое значение колбэка: он по очереди вызывает каждый async-колбэк, тот выполняется до первого await и возвращает промис, который forEach просто выбрасывает. Итерации идут конкурентно (вперемешку), а не параллельно, и никто их не ждёт. for...of работает внутри одной async-функции, и await там реально останавливает цикл."},{"q":"Closure и this","t":"var в цикле — одна переменная на всю функцию, и к моменту срабатывания таймеров цикл уже закончился, все колбэки видят финальное значение. let создаёт привязку на итерацию, и каждая функция замыкает свою. this: по умолчанию — глобальный объект или undefined в strict; implicit — объект перед точкой; explicit — call, apply, bind; new — свежий объект. Стрелка не имеет своего this и берёт его лексически из окружения, поэтому её нельзя переопределить через call и нельзя использовать как метод, которому нужен this."},{"q":"Типы","t":"type Pick<T, K extends keyof T> = { [P in K]: T[P] }: mapped type по ключам K, значение — индексный доступ. Discriminated union — Result равен либо { ok: true, data }, либо { ok: false, error }. Проверка ok сужает тип: в ветке true компилятор знает про data, в ветке false — про error, и невозможное состояние «и data, и error» не выражается вообще. С optional-полями каждый потребитель проверяет оба поля вручную и рано или поздно забывает. Из той же серии: Promise.all падает на первом реджекте, allSettled ждёт всех и отдаёт статусы."}],"kill":"Ответить «then первый» без слова <b>микрозадача</b> — это угадывание. И описать стрелку как «короткий синтаксис» — интервьюер ждёт про this."},
 en:{"topic":"JS/TS: parked check","qs":["setTimeout(0) versus Promise.resolve().then() — which runs first and why? And why doesn't forEach with await wait?","The classic closure bug with a loop and setTimeout before ES6. And the four rules of this plus the arrow-function exception.","Implement Pick<T, K> by hand. Why a discriminated union instead of optional fields?"],"a":[{"q":"Event loop","t":"Microtasks always run before macrotasks: after the current synchronous code, the engine drains the whole microtask queue — promises, queueMicrotask — and only then picks one macrotask like setTimeout. So then fires first even at zero. In between, the browser may (not must) paint a frame — that happens after the microtask queue drains and before the next macrotask, so a long promise chain with no macrotask in between can hold the UI without a repaint longer than you'd expect. forEach with await doesn't wait because forEach ignores the callback's return value: it calls each async callback in turn, each runs until its first await and hands back a promise that forEach just drops. So the iterations run concurrently, interleaved, not in parallel, and nothing waits for them. for...of runs inside a single async function, and await there genuinely pauses the loop."},{"q":"Closure and this","t":"var in a loop is one variable for the whole function, and by the time the timers fire the loop is finished, so every callback sees the final value. let creates a binding per iteration, and each function closes over its own. this: default — the global object, or undefined in strict mode; implicit — the object before the dot; explicit — call, apply, bind; new — a fresh object. An arrow has no this of its own and takes it lexically from the surrounding scope, so you can't override it with call and can't use it as a method that needs this."},{"q":"Types","t":"type Pick<T, K extends keyof T> = { [P in K]: T[P] } — a mapped type over the keys in K, with an indexed access for the value. A discriminated union: Result is either { ok: true, data } or { ok: false, error }. Checking ok narrows the type — in the true branch the compiler knows about data, in the false branch about error, and the impossible state of both data and error can't be expressed at all. With optional fields every consumer checks both by hand and eventually forgets. Same family: Promise.all rejects on the first rejection, allSettled waits for all and returns statuses."}],"kill":"Saying then goes first without the word <b>microtask</b> — that's guessing. And describing an arrow function as short syntax — the interviewer is waiting for this."}},

{n:27,tag:"Core-40 #9–16 · parked check",sec:"parked",core:[9,10,11,12,13,14,15,16],
 ru:{"topic":"React: проверка запаркованного","qs":["Почему хуки нельзя вызывать в условиях? Когда вызывается cleanup в useEffect? Что не так с объектом в массиве зависимостей?","useMemo против useCallback — и когда они реально нужны. Почему key равный index ломается при reorder?","RSC против SSR. Что делает Suspense при стриминге. Три вещи из React 19."],"a":[{"q":"Хуки","t":"React не знает имён хуков — он хранит их состояние в списке и сопоставляет по порядку вызова. Условие меняет порядок, и второй рендер читает чужое состояние. Cleanup вызывается перед следующим запуском того же эффекта и при размонтировании; не отписался — подписка живёт после смерти компонента, утечка и setState на размонтированном. Объект или массив в deps — на каждом рендере новая ссылка, эффект бежит каждый раз, и это выглядит как «бесконечный цикл»; либо стабилизировать через useMemo, либо класть в deps примитивы."},{"q":"Мемоизация","t":"useMemo кэширует значение, useCallback — функцию; второе — это useMemo, возвращающий функцию. Реально нужны в двух случаях: дорогое вычисление, которое измерили, и стабильная ссылка, которую ждёт memo-дочерний компонент или массив deps. Мемоизация по умолчанию не бесплатна: код читается хуже, а один всегда-новый проп молча её ломает; цена по памяти мала. React Compiler, стабильный с версии 1.0, мемоизирует сам, и ручной useMemo — в основном запасной выход. key равный index: при перестановке React видит те же ключи на тех же позициях, считает, что изменилось содержимое, и переиспользует состояние и DOM не тех элементов — поле ввода остаётся в старой строке. Ключ должен идентифицировать сущность."},{"q":"RSC и 19","t":"SSR рендерит компонент на сервере в HTML, а потом всё равно отправляет его JS клиенту для гидрации. Server Component выполняется только на сервере, его код не попадает в бандл вообще, он может напрямую читать базу, но не может держать состояние, использовать интерактивные хуки вроде useState и useEffect или обработчики событий. Клиентский — там, где интерактивность. Suspense при стриминге позволяет отдать оболочку сразу, а медленные части досылать по мере готовности в том же потоке HTML. React 19: Actions — асинхронные функции для форм и переходов, useActionState для их состояния и ошибок, use — чтение промиса или контекста прямо в рендере."}],"kill":"<b>«Хуки нельзя в условиях, потому что так написано в доке»</b> — нужно слово «порядок вызова». И «useMemo для производительности» без «измерил» — интервьюер спросит, что именно ты измерил."},
 en:{"topic":"React: parked check","qs":["Why can't hooks be called conditionally? When does a useEffect cleanup run? What's wrong with an object in the dependency array?","useMemo versus useCallback — and when are they actually needed. Why does key equal to index break on reorder?","RSC versus SSR. What Suspense does with streaming. Three things from React 19."],"a":[{"q":"Hooks","t":"React doesn't know hook names — it stores their state in a list and matches by call order. A condition changes the order, and the next render reads someone else's state. Cleanup runs before the next run of the same effect and on unmount; skip it and the subscription outlives the component — a leak, and setState on an unmounted component. An object or array in deps is a new reference every render, so the effect runs every time and looks like an infinite loop; either stabilise it with useMemo or put primitives in deps."},{"q":"Memoisation","t":"useMemo caches a value, useCallback caches a function — the second is just useMemo returning a function. They're genuinely needed in two cases: an expensive computation you've measured, and a stable reference that a memoised child or a deps array is waiting for. Memoising by default isn't free: code gets harder to read, and one always-new prop silently breaks it; the memory cost is small. React Compiler, stable since 1.0, memoises automatically, so manual useMemo is mostly an escape hatch. key equal to index: on reorder React sees the same keys at the same positions, assumes the content changed, and reuses the state and DOM of the wrong elements — the input stays in the old row. A key has to identify the entity."},{"q":"RSC and 19","t":"SSR renders a component to HTML on the server and then still ships its JavaScript to the client for hydration. A Server Component runs only on the server, its code never enters the bundle, it can read the database directly, but it can't use state or interactive hooks like useState and useEffect, or event handlers. Client components are where the interactivity is. Suspense with streaming lets you send the shell immediately and stream the slow parts as they're ready in the same HTML response. React 19: Actions — async functions for forms and transitions; useActionState for their state and errors; use — reading a promise or a context directly during render."}],"kill":"<b>\"Hooks can't be conditional because the docs say so\"</b> — the phrase is call order. And useMemo for performance without I measured — the interviewer will ask what exactly you measured."}},

{n:28,tag:"New · coverage gap",sec:"llm",core:[43],
 ru:{"topic":"Fine-tuning vs RAG vs prompt engineering","qs":["Три инструмента — prompt engineering, RAG, fine-tuning. По какому принципу выбираешь?","Посчитай вслух: что дороже — зафайнтюнить модель или построить RAG? На каких осях сравниваешь?","Реальный продакшн использует один инструмент или комбинацию? Приведи пример пути от прототипа до продакшна."],"a":[{"q":"Порядок выбора","t":"Я всегда иду от дешёвого и быстрого к дорогому и медленному: сначала prompt engineering, потом RAG, и только в последнюю очередь fine-tuning. Причина не в моде, а в цикле итерации: промпт я меняю за секунды и вижу результат сразу, RAG требует пересборки индекса, но всё ещё без переобучения весов, а fine-tuning — это датасет, тренировочный прогон, eval на регрессии, и весь цикл повторяется при каждом обновлении базовой модели. Ключевой вопрос для выбора — это knowledge gap или behavior gap. Модель не знает конкретных фактов (внутренняя база знаний, свежие данные, приватные документы) — это RAG. Модель знает факты, но ведёт себя не так, как нужно (тон, формат, стабильность на грани edge case) — сначала пробую промпт и structured output, и только если это не держится на объёме — fine-tuning или дистилляция."},{"q":"Стоимость","t":"Считаю по трём осям: деньги на старте, деньги на поддержку, скорость итерации. RAG — это pipeline (конвейер) поиска: обычно эмбеддинги и vector store, часто плюс BM25 по ключевым словам. Крутить его дёшево, а обновление источника — это re-index, а не re-train: правки видны сразу. Fine-tuning требует курированного датасета, где качество важнее объёма: OpenAI видит улучшения уже на пятидесяти–ста хороших примерах, хотя сложным задачам нужно больше. Дальше тренировочный прогон и то, что забывают, — eval harness, ведь дообученная модель может стать хуже на задачах, которые раньше решала. Главный расход — каждое обновление базовой модели вендором требует решения: переобучать или остаться на старой версии. RAG избавляет от переобучения, но не от всей миграции: новую модель надо прогнать через eval, а снятие embedding-модели заставляет переэмбеддить корпус."},{"q":"Комбинация","t":"Почти всегда комбинация, не «или-или». Типичный путь: прототип на prompt engineering плюс RAG, validate на eval-сьюте — если работает и объём растёт, следующий шаг не «добавить fine-tuning», а «можно ли этот же результат получить дешевле» — например, дистиллировать поведение дорогой модели в дешёвую, если паттерн стабилен и его можно закрепить датасетом. Fine-tuning в проде почти никогда не заменяет RAG — он ложится поверх, когда нужно снизить cost/latency на уже проверенном поведении, а не когда нужно новое знание."}],"kill":"Тянуться к fine-tuning первым, потому что «это настоящий ML» — почти всегда самый дорогой и медленный вариант, и к тому же плохой, ненадёжный способ добавить знания: тут RAG стабильно выигрывает. Fine-tuning в первую очередь инструмент для поведения. Плюс забыть, что дообучение без eval-сьюта — это дообучение вслепую: можно улучшить одну метрику и незаметно сломать три другие."},
 en:{"topic":"Fine-tuning vs RAG vs prompt engineering","qs":["Three tools — prompt engineering, RAG, fine-tuning. What's your actual decision rule?","Walk me through cost: which is more expensive, fine-tuning or building RAG? What axes are you comparing on?","Does real production use one tool or a combination? Walk me through a path from prototype to production."],"a":[{"q":"Order of choice","t":"I go from cheap-and-fast to expensive-and-slow every time: prompt engineering first, then RAG, and fine-tuning only as a last resort. It's not fashion, it's the iteration loop — I change a prompt in seconds and see the result immediately, RAG needs a re-indexed pipeline but still no retraining, and fine-tuning means a dataset, a training run, a regression eval, and the whole cycle repeats every time the base model updates. The real decision question is knowledge gap versus behavior gap. The model doesn't know specific facts (an internal knowledge base, fresh data, private documents) — that's RAG. The model knows the facts but behaves wrong (tone, format, consistency at the edges) — I try prompting and structured output first, and only reach for fine-tuning or distillation if that doesn't hold up at volume."},{"q":"Cost","t":"I compare on three axes: upfront cost, ongoing cost, iteration speed. RAG is a retrieval pipeline, usually embeddings and a vector store, often plus BM25 keyword search. It's cheap to run, and a source update is a re-index, not a re-train, so edits show up immediately. Fine-tuning needs a curated dataset where quality beats volume. OpenAI reports gains from as few as fifty to a hundred good examples, though harder tasks need more. Then the training run and, the part people forget, an eval harness, because a fine-tuned model can get worse at tasks it used to handle fine. The real expense is that every base-model update forces a decision: retrain or stay on the old version. RAG skips the retraining, but not all the churn. A new generation model still needs an eval run, and a deprecated embedding model means re-embedding the corpus."},{"q":"Combination","t":"Almost always a combination, not either/or. The typical path: prototype with prompt engineering plus RAG, validate against an eval suite — if it works and volume grows, the next step isn't 'add fine-tuning', it's 'can I get the same result cheaper' — for example, distilling the expensive model's behavior into a cheap one once the pattern is stable enough to lock down with a dataset. Fine-tuning in production almost never replaces RAG — it sits on top, to cut cost/latency on behavior you've already validated, not to add new knowledge."}],"kill":"Reaching for fine-tuning first because 'it feels like real ML' — it's almost always the most expensive, slowest option, and a poor, unreliable way to add knowledge, where RAG consistently beats it. It's mainly a behavior tool. Also forgetting that fine-tuning without an eval suite is fine-tuning blind: you can improve one metric and silently break three others."}},

{n:29,tag:"New · coverage gap",sec:"behav",core:[44],
 ru:{"topic":"Конфликт, обратная связь, слабость","qs":["Расскажи о конфликте или несогласии с коллегой/тимлидом. STAR, 90 секунд.","Расскажи о жёсткой обратной связи, которую тебе давали. Что ты изменил?","Какая твоя главная слабость — без клише?"],"a":[{"q":"Конфликт","t":"Это единственная история в банке, для которой у меня ещё нет закреплённого реального случая — надо заполнить до первого скрина. Структура жёсткая: Situation — конкретный технический или процессный вопрос, где ты и коллега/тимлид разошлись (не личный конфликт, а разница в подходе: выбор библиотеки, архитектурное решение, приоритизация). Task — что было на кону и почему твоя позиция не была очевидной победой по умолчанию. Action — как ты аргументировал: данные, а не эмоции; ты слушал контраргумент по-настоящему, а не ждал своей очереди говорить. Result — чем кончилось: возможно, ты был прав и это доказано метрикой; возможно, тебя переубедили, и это тоже сильный ответ, если ты объяснишь, что именно изменило твоё мнение. Кандидат из реального опыта: разногласие по стеку или архитектуре на текущем месте или на одном из сайд-проектов. [Заполнить: конкретный вопрос, чья была правда, и на чём именно сошлись]."},{"q":"Обратная связь","t":"Тоже без закреплённого факта — заполнить перед собесом. Структура: что тебе сказали конкретно (не «нужно расти», а дословно или близко к тому); что было первой реакцией внутри (честно, не «сразу согласился» — это подозрительно гладко); что ты реально изменил в поведении, с наблюдаемым результатом, который можно проверить у той же стороны, что дала фидбэк. Плохой ответ — фидбэк без изменения поведения; ещё хуже — фидбэк, который на самом деле комплимент в маскировке («мне сказали, что я слишком дотошный»). [Заполнить: кто дал, что сказал, что изменилось]."},{"q":"Слабость","t":"Без клише («перфекционист», «слишком много работаю») — это читается как отказ отвечать на вопрос. Настоящая слабость — конкретная и с механизмом компенсации, который ты реально используешь, не «работаю над этим» без деталей. Формула: назвать реальное ограничение → объяснить, откуда оно (не оправдание, а причина) → конкретный механизм, которым ты его обходишь на практике, с примером ситуации, где механизм сработал. [Заполнить: что реально ограничение — например, склонность закапываться в детали до проверки общей гипотезы, или наоборот — двигаться быстро и потом чинить края]."}],"kill":"Конфликт без реального несогласия («мы разошлись, но потом договорились» без сути разногласия) — интервьюер не может оценить, был ли ты прав или просто уступчив. И слабость-комплимент — интервьюер слышит это на первом же собесе в карьере, минус доверие сразу."},
 en:{"topic":"Conflict, feedback, weakness","qs":["Tell me about a conflict or disagreement with a coworker or tech lead. STAR, 90 seconds.","Tell me about hard feedback you received. What did you change?","What's your biggest weakness — no clichés?"],"a":[{"q":"Conflict","t":"This is the one story in the bank without a locked real case yet — needs filling before the first screen. Strict structure: Situation — a specific technical or process disagreement with a coworker or tech lead (not a personal conflict, a difference in approach: library choice, architecture decision, prioritization). Task — what was at stake, and why your position wasn't an obvious default win. Action — how you argued: data, not emotion; you actually listened to the counter-argument instead of waiting for your turn to talk. Result — how it resolved: maybe you were right and a metric proved it; maybe you got convinced, which is also a strong answer if you explain what specifically changed your mind. Real candidate: a stack or architecture disagreement at your current job or on a side project. [Fill in: the specific question, who turned out right, and what you actually landed on]."},{"q":"Feedback","t":"Also no locked fact yet — fill before the interview. Structure: what was actually said (not 'I need to grow', close to verbatim); what your first reaction was internally (honestly — not 'I immediately agreed', that's suspiciously smooth); what you actually changed in behavior, with an observable result the same person who gave the feedback could confirm. A weak answer is feedback with no behavior change; worse is feedback that's secretly a compliment in disguise ('I was told I'm too thorough'). [Fill in: who gave it, what they said, what changed]."},{"q":"Weakness","t":"No clichés ('perfectionist', 'work too hard') — that reads as refusing to answer the question. A real weakness is specific and comes with a compensating mechanism you actually use, not 'working on it' with no detail. Formula: name the real limitation → explain where it comes from (a reason, not an excuse) → the concrete mechanism you use to work around it, with an example where it worked. [Fill in: the real limitation — e.g. a tendency to dig into details before validating the overall hypothesis, or the opposite, moving fast and fixing edges after]."}],"kill":"A conflict with no real disagreement in it ('we disagreed but then agreed' with no substance) — the interviewer can't tell if you were right or just agreeable. And a weakness that's secretly a compliment — interviewers hear that in their first year on the job, instant credibility loss."}},

{n:30,tag:"New · coverage gap",sec:"behav",core:[45],
 ru:{"topic":"Лидерство без власти, быстрое обучение, почему сейчас","qs":["Как ты продвигал техническое решение без формальной власти над командой?","Расскажи, как ты быстро выучил что-то новое и применил это. Годится пивот в AI.","Почему уходишь с текущего места именно сейчас?"],"a":[{"q":"Влияние без власти","t":"Структура: назвать техническое решение, которое ты продвигал не будучи тимлидом; как убеждал — через прототип/proof of concept, а не через мнение; как реагировал на сопротивление — слушал возражение по существу, а не продавливал. Result — приняли ли решение, и если да, что стало доказательством, что оно было правильным (метрика, инцидент, который оно предотвратило). [Заполнить: конкретное решение с текущего места или сайд-проекта, где ты не был formal owner, но продавил через демонстрацию, а не позицию]."},{"q":"Быстрое обучение","t":"Тут есть готовый материал — сам пивот. За несколько месяцев с нуля до RAG-пайплайна с эвалом и tool-use агента на новом для тебя SDK. Механизм, а не просто факт: как ты реально учился — не курсы пассивно, а строил и ломал; что было первым, что реально сломалось, и как ты это диагностировал; что из старого опыта (senior frontend intuition про debugging, про чтение чужого кода, про декомпозицию большой задачи) перенеслось напрямую, а что пришлось учить с нуля. Это единственная behavioral-история, где честный ответ и питч пивота — одно и то же, не разводи их на два разных рассказа."},{"q":"Почему сейчас","t":"Ответ не про недовольство текущим местом, а про то, что ты нашёл направление, которое хочешь строить дальше, и текущая роль не даёт расти в него в нужном темпе. Не говоришь плохо о работодателе — это красный флаг для любого интервьюера, независимо от того, насколько ты прав. Формула: что ты ценишь в текущем месте (искренне, не для галочки) → что именно там не растёт в направлении, которое тебе теперь важно → почему именно сейчас, а не раньше или позже (пивот уже на стадии, где нужна реальная работа, не сайд-проект). [Заполнить: что конкретно не даёт расти на текущем месте в сторону AI]."}],"kill":"Плохие слова о текущем работодателе — сигнал, что через год ты так же будешь говорить об этом месте. И «влияние без власти» без реального доказательства (метрика/инцидент) — тогда это просто «я предложил», а не «меня послушали»."},
 en:{"topic":"Leading without authority, learning fast, why now","qs":["How have you driven a technical decision without formal authority over the team?","Tell me about learning something new fast and applying it. The AI pivot counts.","Why are you leaving your current role now, specifically?"],"a":[{"q":"Influence without authority","t":"Structure: name a technical decision you pushed without being the tech lead — how you convinced people: through a prototype/proof of concept, not an opinion; how you handled pushback — actually listened to the substance of the objection instead of just pushing harder. Result — did it get adopted, and if so, what proved it was right (a metric, an incident it prevented). [Fill in: a specific decision at your current job or a side project where you weren't the formal owner but won through demonstration, not position]."},{"q":"Learning fast","t":"You already have the material — the pivot itself. In a few months, zero to a RAG pipeline with evals and a tool-use agent on an SDK that was new to you. The mechanism matters, not just the fact: how you actually learned — not passive courses, building and breaking things; what was the first thing that genuinely broke and how you diagnosed it; what carried over directly from your old experience (senior-frontend instincts for debugging, reading unfamiliar code, breaking a big problem into steps) versus what you had to learn from zero. This is the one behavioral story where the honest answer and the pivot pitch are the same thing — don't split them into two different stories."},{"q":"Why now","t":"The answer isn't about dissatisfaction with your current place, it's about having found a direction you want to build toward, and the current role not letting you grow into it fast enough. Don't speak badly of the employer — that's a red flag for any interviewer regardless of how justified it is. Formula: what you genuinely value about the current place (sincerely, not a token line) → what specifically doesn't let you grow in the direction that matters to you now → why now specifically, not earlier or later (the pivot is at a stage that needs real work, not a side project anymore). [Fill in: what specifically caps your growth toward AI at the current place]."}],"kill":"Speaking badly of your current employer — signals you'll talk about this place the same way in a year. And 'influence without authority' with no real proof (a metric/incident) is just 'I suggested it', not 'they listened'."}},

{n:31,tag:"Frontend core · JS",sec:"js",core:[46],
 ru:{"topic":"Event loop в деталях","qs":["Что выведет этот код и почему: console.log('A'); setTimeout(() => console.log('B'), 0); Promise.resolve().then(() => console.log('C')); queueMicrotask(() => console.log('D')); console.log('E')?","Пока стримится ответ LLM, перерисовка markdown делает ввод в поле тормозным. Что происходит и как это чинить?","Почему цикл на промисах может заморозить страницу, хотя он вроде бы асинхронный?"],"a":[{"q":"Порядок вывода","t":"Выведется A, E, C, D, B. Весь скрипт это одна задача, поэтому A и E печатаются синхронно, пока работает стек вызовов. setTimeout ставит в очередь макрозадачу, а then и queueMicrotask ставят микрозадачи. Когда стек опустел, браузер выполняет всю очередь микрозадач до конца, в порядке постановки. Поэтому сначала C, потом D. Потом браузер может отрисовать кадр, и только после этого берёт следующую задачу, то есть таймер. Поэтому B последний. Модель у меня в голове такая: одна задача, потом все микрозадачи, потом, возможно, отрисовка, потом следующая задача. Отрисовка не гарантирована на каждом круге. Браузер рисует примерно с частотой обновления экрана и пропускает этот шаг, если ничего не изменилось или вкладка скрыта. Функции из requestAnimationFrame выполняются внутри этого шага, прямо перед пересчётом стилей, layout (расчётом геометрии) и paint (отрисовкой пикселей). Ловушка — думать, что setTimeout с нулём означает «сейчас». Это после текущей задачи, всех микрозадач и хотя бы одного оборота цикла, а для глубоко вложенных таймеров браузер ставит минимум около четырёх миллисекунд."},{"q":"Лаг при стриминге","t":"Каждый чанк (кусок ответа) из потокового ответа приходит отдельной задачей, и на каждый мы заново разбираем всю растущую markdown-строку и перерисовываем всё сообщение. К концу длинного ответа это легко больше 50 миллисекунд на чанк, то есть long task (длинная задача). Нажатие клавиши, пришедшее во время long task, ждёт её окончания, а потом ещё и следующего кадра. Это задержка ввода, и она прямо бьёт по INP (Interaction to Next Paint, время от взаимодействия до следующей отрисовки). INP заменил FID в Core Web Vitals (ключевых метриках Google) в марте 2024 года, хороший порог — 200 миллисекунд. Чиню слоями. Во-первых, перестаю перерисовывать на каждый токен. Складываю чанки в буфер и сбрасываю не чаще раза за кадр, через requestAnimationFrame. Во-вторых, делаю разбор инкрементальным. Готовые блоки кэширую, заново разбираю только последний незакрытый блок. В-третьих, помечаю обновление сообщения как несрочное через startTransition или useDeferredValue, чтобы React мог прервать его ради нажатия клавиши. Если разбор и подсветка всё равно тяжёлые, выношу их в Web Worker (фоновый поток), а главный поток только применяет результат."},{"q":"Зависание на промисах","t":"Потому что async не значит «отдать управление браузеру». Обработчик уже выполненного промиса (Promise) это микрозадача, а цикл событий выполняет очередь микрозадач полностью, прежде чем рисовать или брать следующую задачу. Если каждая микрозадача ставит следующую, например рекурсивная цепочка then или цикл, который ждёт через await уже готовые значения, очередь никогда не пустеет. Нет отрисовки, нет обработки ввода, нет таймеров. Страница висит так же, как от while (true). У setTimeout такой проблемы нет: каждый вызов это отдельная задача, и между ними браузер успевает отрисовать кадр. Поэтому, когда я режу тяжёлую работу на куски, я отдаю управление через настоящую границу задачи. Классический способ — await new Promise(r => setTimeout(r, 0)). scheduler.yield лучше, потому что продолжение встаёт в начало очереди, а не в конец. Но, насколько я знаю, он есть в Chromium и Firefox, а в Safari пока нет, так что я проверяю его наличие и откатываюсь на setTimeout. А по-настоящему вычислительную работу, вроде разбора большого файла или токенизации, я лучше вынесу в Web Worker (фоновый поток), чем буду резать."}],"kill":"<b>«setTimeout(fn, 0) выполнится сразу после текущей строки»</b> — нет, он выполнится после текущей задачи, всех микрозадач и, возможно, отрисовки. И <b>«асинхронный код не может заблокировать страницу»</b> неверно: бесконечная цепочка микрозадач вешает её так же, как while (true)."},
 en:{"topic":"Event loop in depth","qs":["What does this log and why: console.log('A'); setTimeout(() => console.log('B'), 0); Promise.resolve().then(() => console.log('C')); queueMicrotask(() => console.log('D')); console.log('E')?","While an LLM response streams in, our markdown re-render makes typing in the input lag. What's happening and how do you fix it?","Why can a promise loop freeze the page even though it's supposedly async?"],"a":[{"q":"Ordering puzzle","t":"It logs A, E, C, D, B. The whole script is one task, so A and E print synchronously while the call stack runs. setTimeout queues a macrotask, while then and queueMicrotask queue microtasks. When the stack empties, the browser drains the entire microtask queue in order before doing anything else. So C, then D. Then the browser may render a frame, and only after that does it pick the next task, which is the timer. So B comes last. The model I keep in my head is one task, then all microtasks, then maybe rendering, then the next task. Rendering isn't guaranteed every loop. The browser renders roughly at the display refresh rate and skips it if nothing changed or the tab is hidden. requestAnimationFrame callbacks run inside that rendering step, right before style, layout and paint. The trap is thinking setTimeout zero means now. It means after the current task, all microtasks and at least one turn of the loop, and for deeply nested timers browsers enforce a minimum of about four milliseconds."},{"q":"Streaming lag","t":"Every chunk from the stream arrives as its own task, and on each one we re-parse the whole growing markdown string and re-render the whole message. Near the end of a long answer that's easily over 50 milliseconds per chunk, which makes it a long task. A keypress that arrives during a long task waits until it ends, and then waits for the next frame too. That's input delay, and it hits INP directly. INP replaced FID as a Core Web Vital in March 2024, and 200 milliseconds is the good threshold. I fix it in layers. First, I stop rendering per token. I buffer chunks and flush at most once per frame with requestAnimationFrame. Second, I make parsing incremental. Finished blocks are cached, and only the last open block gets re-parsed. Third, I mark the message update as non-urgent with startTransition or useDeferredValue, so React can interrupt it for the keystroke. If parsing and highlighting are still heavy, they move to a Web Worker and the main thread only applies the result."},{"q":"Microtask starvation","t":"Because async doesn't mean yielding to the browser. The callback of a resolved promise is a microtask, and the event loop drains the microtask queue completely before it renders or takes the next task. If each microtask queues another one, like a recursive then chain or a loop that awaits already-resolved values, the queue never empties. No paint, no input handling, no timers. The page is frozen exactly as if I'd written while (true). setTimeout doesn't have this problem, because each callback is a separate task and the browser gets a chance to render between them. So when I chunk heavy work, I yield across a real task boundary. The classic way is await new Promise(r => setTimeout(r, 0)). scheduler.yield is better, because the continuation goes to the front of the line instead of the back. But as far as I know it's in Chromium and Firefox and not in Safari yet, so I feature-detect it and fall back to setTimeout. For truly CPU-bound work, like parsing a big file or tokenizing, I'd rather move it to a Web Worker than slice it."}],"kill":"<b>\"setTimeout(fn, 0) runs right after the current line\"</b> — no, it runs after the current task, every queued microtask and possibly a render. And <b>\"async code can't block the page\"</b> is wrong: an endless microtask chain freezes it as hard as while (true)."}},

{n:32,tag:"Frontend core · JS",sec:"js",core:[47],
 ru:{"topic":"Замыкания, область видимости и память","qs":["Что именно захватывает замыкание? Объясните, почему setInterval в React-компоненте всё время выводит старый count.","Память в нашем чат-приложении растёт весь час, пока вкладка открыта. Какие обычные причины?","Как вы на практике найдёте эту утечку, и где помогают WeakMap и WeakRef?"],"a":[{"q":"Что захватывается","t":"Замыкание захватывает привязку переменной, а не снимок её значения. Функция при создании хранит ссылку на лексическое окружение, в котором её создали, и поиск переменной идёт по цепочке областей видимости в момент вызова. Поэтому в цикле for с let у каждой итерации своя i, а с var привязка одна на всех, и все колбэки (функции обратного вызова) видят последнее значение. В React нюанс в том, что каждый рендер (вызов функции компонента) это новый вызов функции с новыми привязками. Колбэк setInterval, созданный в эффекте с пустым массивом зависимостей, замыкает count из первого рендера, и эта привязка никогда не меняется. Поэтому он вечно выводит ноль, хотя компонент перерисовался. Исправления такие: функциональное обновление вроде setCount(c => c + 1), добавить зависимость и переподписаться, или держать актуальное значение в ref. С React 19.2 для этого есть стабильный useEffectEvent: эффект вызывает функцию-событие, которая всегда читает свежие props и state, не перезапуская эффект. Ловушка — заглушить правило exhaustive-deps в линтере (статическом анализаторе) вместо исправления."},{"q":"Источники утечек","t":"Сборщик мусора освобождает то, что недостижимо от корней: глобальных объектов, текущего стека и живого DOM. Так что утечка в JavaScript почти всегда — это что-то достижимое, о чём я забыл. В долгоживущем SPA (одностраничном приложении) обычные подозреваемые такие. Слушатели на window или document, добавленные в эффекте без очистки. setInterval, который никто не очищает. Подписки на WebSocket, store (хранилище состояния) или источник событий, которые переживают компонент. Дальше идёт detached DOM (узлы, удалённые со страницы). Элемент убран, но на него всё ещё ссылается какой-то массив, кэш или замыкание, и всё поддерево остаётся в памяти. Замыкания делают это коварным. Маленький обработчик может держать живым большой объект, например всю историю чата, потому что ссылается на него сам или на него ссылается соседнее замыкание из той же области. Движки обычно делят один объект контекста на всю область. И последнее — неограниченные кэши. Map по id сообщения, который только растёт, это утечка с красивым названием. В чате с длинными ответами я бы первым делом проверил кэши сообщений и слушатели на каждом сообщении, и дал бы каждому кэшу лимит размера или вытеснение LRU (удаление давно не использованных)."},{"q":"Поиск утечки","t":"Сначала я её воспроизвожу. Беру одно действие, например открыть и закрыть ветку чата. В Chrome DevTools, на панели Memory, делаю базовый heap snapshot (снимок кучи), повторяю действие десять раз, принудительно запускаю сборку мусора, делаю второй снимок и смотрю режим сравнения. Всё, чьё количество выросло примерно на десять, это кандидат. Фильтр Detached показывает DOM-узлы, удалённые со страницы, но всё ещё достижимые. Главное — панель Retainers (удерживающие ссылки): она показывает точную цепочку ссылок, которая держит объект, вплоть до замыкания или слушателя. Для постепенного роста есть allocation timeline (запись выделений памяти во времени), там видно, какие выделения выживают. WeakMap помогает, когда нужно привязать данные к чужому объекту, например метаданные к DOM-узлу, не продлевая ему жизнь. Запись исчезает, когда ключ собран. WeakRef это крайняя мера для кэшей. Момент сборки не гарантирован, а колбэки (обработчики) FinalizationRegistry могут вообще не вызваться, поэтому корректность на них я не строю. Большинство утечек чинится недостающей функцией очистки, а не слабыми ссылками."}],"kill":"<b>«Замыкание скопировало значение в момент создания»</b> — нет, оно держит привязку, а устаревшее значение в React берётся из привязки старого рендера. И <b>«в JavaScript есть сборщик мусора, значит утечек не бывает»</b> топит людей: всё, что достижимо, живёт вечно."},
 en:{"topic":"Closures, scope and memory","qs":["What exactly does a closure capture? Walk me through why a setInterval in a React component keeps logging a stale count.","Memory in our long-lived chat app keeps climbing over an hour of use. What are the usual culprits?","How would you actually find that leak, and where do WeakMap and WeakRef help?"],"a":[{"q":"What's captured","t":"A closure captures the variable binding, not a snapshot of its value. When a function is created, it keeps a reference to the lexical environment it was created in, and variable lookups walk that scope chain at call time. That's why a for loop with let gives each iteration its own i, while var shares one binding and every callback sees the final value. In React the twist is that each render is a new function call with new bindings. A setInterval callback created in an effect with an empty dependency array closes over count from the first render, and that binding never changes. So it logs zero forever, even though the component re-rendered. The fixes are a functional update like setCount(c => c + 1), adding the dependency and re-subscribing, or keeping the latest value in a ref. Since React 19.2, useEffectEvent is stable for exactly this. The effect calls an event function that always reads the latest props and state without re-running the effect. The trap is silencing the exhaustive-deps lint rule instead of fixing it."},{"q":"Leak culprits","t":"The garbage collector frees whatever is unreachable from the roots, like globals, the current stack and the live DOM. So a leak in JavaScript is almost always something still reachable that I forgot about. In a long-lived SPA the usual suspects are listeners on window or document added in an effect without cleanup, a setInterval that's never cleared, and subscriptions to a WebSocket, a store or an event emitter that outlive the component. Next come detached DOM nodes. The element is removed from the page, but some array, cache or closure still points to it, so the whole subtree stays in memory. Closures make this sneaky. A small handler can keep a large object alive, like the full chat history, because it references it or because a sibling closure from the same scope does. Engines usually share one context object per scope. Last, unbounded caches. A Map keyed by message id that only ever grows is a leak with a nice name. In a chat app with long answers I'd check message caches and per-message listeners first, and give every cache a size limit or LRU eviction."},{"q":"Finding it","t":"First I reproduce it. I pick one action, like opening and closing a chat thread. In the Chrome DevTools Memory panel I take a baseline heap snapshot, repeat the action ten times, force garbage collection, take a second snapshot and use the comparison view. Anything whose count grew by roughly ten is a candidate. Filtering by Detached shows DOM nodes that were removed from the page but are still reachable. The retainers panel is the key part, because it shows the exact chain of references keeping the object alive, down to the closure or listener. For gradual growth, the allocation timeline shows which allocations survive over time. WeakMap helps when I want to attach data to an object I don't own, like metadata per DOM node, without extending its life. The entry goes away when the key is collected. WeakRef is a last resort for caches. Collection timing isn't guaranteed and FinalizationRegistry callbacks may never run, so I never build correctness on them. Most leaks are fixed by a missing cleanup function, not by weak references."}],"kill":"<b>\"The closure copied the value when it was created\"</b> — no, it holds the binding, and in React the stale value comes from an old render's binding. And <b>\"JavaScript has a garbage collector, so it can't leak\"</b> sinks people: anything still reachable is kept forever."}},

{n:33,tag:"Frontend core · JS",sec:"js",core:[48],
 ru:{"topic":"Асинхронность, ошибки и отмена","qs":["Promise.all, allSettled, race, any: когда что использовать и что происходит, если один из промисов падает?","Пользователь жмёт Stop, пока приходит потоковый ответ LLM. Как вы отменяете это по-настоящему, от начала до конца?","Вы отправляете сто запросов в API с лимитом частоты. Как сделать, чтобы всё не развалилось?"],"a":[{"q":"Комбинаторы","t":"Promise.all отдаёт все результаты в порядке входа и отклоняется, как только отклонился первый промис (Promise). Беру его, когда нужно всё, и одна ошибка делает результат бесполезным. allSettled никогда не отклоняется. Он ждёт все промисы и отдаёт для каждого статус и значение или причину. Это то, что нужно для частичных результатов, например когда я параллельно опрашиваю несколько источников для поиска. race завершается тем, что завершилось первым, успехом или ошибкой, поэтому это классический приём для таймаута (ограничения по времени). any отдаёт первый успех и отклоняется, с AggregateError, только если упали все. Это удобно для запросов к дублирующим зеркалам. Что упускают: ни один из них ничего не отменяет. Когда all отклонился или race выбрал победителя, остальные операции продолжают работать, занимают сеть и могут ещё упасть позже. race с таймаутом просто перестаёт ждать, а запрос всё ещё в полёте. Если я хочу остановить проигравших, я передаю им AbortSignal и сам вызываю abort."},{"q":"Кнопка Stop","t":"На каждую генерацию я создаю AbortController и передаю его signal в fetch или в вызов SDK. Anthropic TypeScript SDK принимает signal в опциях запроса, а у его стрима (потокового ответа) есть метод abort. Кнопка Stop вызывает abort. Тогда fetch отклоняется с AbortError, а если я уже читаю тело ответа, ожидающее чтение тоже отклоняется, и цикл чтения выходит. Отмену я считаю нормальным исходом, а не поводом показать ошибку, и оставляю частичный текст, который пользователь уже видел. Про что забывают — сервер. Отмена в браузере закрывает соединение, но мой обработчик маршрута всё ещё получает поток от модели и платит за токены, если он не слушает сигнал отмены запроса и не отменяет свой вызов к модели. Я бы проверил, что фреймворк (Next.js или другой) действительно поднимает этот сигнал при разрыве. Для таймаутов (ограничений по времени) беру AbortSignal.timeout: он отменяет с TimeoutError, и его можно отличить от остановки пользователем. AbortSignal.any объединяет оба сигнала в один. Оба в Baseline (поддержке всеми основными браузерами) с 2024 года. В React я ещё отменяю в функции очистки эффекта, так что переключение чата тоже отменяет стрим."},{"q":"Лимиты и повторы","t":"Во-первых, я не отправляю сто сразу. Promise.all над сотней fetch запускает их все немедленно, ведь запрос стартует в момент вызова fetch, а промис (Promise) это не отложенная задача. Я ставлю ограничитель параллельности: пул (набор) из, скажем, пяти воркеров (обработчиков), которые берут задачи из общей очереди, или библиотеку вроде p-limit. Во-вторых, повторы с экспоненциальной задержкой и jitter (случайным разбросом). Задержка удваивается с каждой попыткой, с потолком, и я добавляю к ней случайность, чтобы сто клиентов, упавших одновременно, не повторяли синхронно. В-третьих, повторяю только то, что может пройти при повторе. Это сетевые ошибки, 408, 429 и 5xx, особенно 502, 503 и 504, а SDK Anthropic по умолчанию повторяет ещё и 409 Conflict. На 429 учитываю Retry-After, если сервер его прислал. Остальные 4xx, вроде 400, 401 или 422, значат, что неправ мой запрос, и повтор только сжигает квоту. Я ограничиваю число попыток и общее время, а неидемпотентные вызовы (те, что нельзя безопасно повторить) повторяю только с ключом идемпотентности. И наконец, у каждого промиса должен быть обработчик. Необработанное отклонение это ошибка в консоли и событие unhandledrejection в браузере, а в Node начиная с 15-й версии по умолчанию падает весь процесс."}],"kill":"<b>«Promise.race отменяет более медленные запросы»</b> — он только перестаёт их ждать, они продолжают работать. Для отмены нужен AbortSignal, который надо передать в операцию и самому вызвать abort."},
 en:{"topic":"Async, failure and cancellation","qs":["Promise.all, allSettled, race, any: when do you use each, and what happens when one of the promises fails?","The user hits Stop while an LLM response is streaming. How do you actually cancel it, end to end?","You fire a hundred requests at a rate-limited API. How do you keep that from falling over?"],"a":[{"q":"Combinators","t":"Promise.all resolves with all results in input order, and rejects as soon as the first one rejects. I use it when I need everything and one failure makes the result useless. allSettled never rejects. It waits for all of them and gives me a status plus a value or reason for each, which is what I want for partial results, like fanning out to several retrieval sources. race settles with whichever settles first, success or failure, so it's the classic timeout pattern. any resolves with the first success and only rejects, with an AggregateError, if every promise fails. That's good for redundant mirrors. The part people miss is that none of these cancel anything. When all rejects or race picks a winner, the other operations keep running, keep using the network and may still fail later. A race against a timeout just stops me waiting, while the request is still in flight. If I want the losers stopped, I pass them an AbortSignal and call abort myself."},{"q":"Stop button","t":"I create an AbortController per generation and pass its signal to fetch or to the SDK call. The Anthropic TypeScript SDK accepts a signal in request options, and its stream has an abort method. Stop calls abort. Fetch then rejects with an AbortError, and if I'm already reading the body, the pending read rejects too, so my read loop exits. I treat cancellation as a normal outcome, not an error toast, and keep the partial text the user already saw. The part people forget is the server. Aborting in the browser closes the connection, but my route handler is still streaming from the model and paying for tokens unless it listens to the request's abort signal and cancels its upstream call. I'd verify my framework actually fires that signal on disconnect. For timeouts I use AbortSignal.timeout, which aborts with a TimeoutError, so I can tell it apart from a user stop. AbortSignal.any combines both into one signal. Both have been Baseline since 2024. In React I also abort in the effect cleanup, so switching chats cancels the stream too."},{"q":"Limits and retries","t":"First, I don't fire a hundred at once. Promise.all over a hundred fetches starts all of them immediately, because the request starts when fetch is called and a promise isn't a lazy task. I use a concurrency limiter, a pool of say five workers pulling from a shared queue, or a library like p-limit. Second, retries with exponential backoff and jitter. The delay doubles each attempt up to a cap, and I randomize it so a hundred clients that failed together don't retry in lockstep. Third, I only retry what can succeed on retry. That's network errors, 408, 429 and 5xx, especially 502, 503 and 504, and Anthropic's SDK retries 409 Conflict by default too. On 429 I honor Retry-After if the server sends it. Other 4xx like 400, 401 or 422 mean my request is wrong, so retrying just burns quota. I cap attempts and total time, and I only retry non-idempotent calls when there's an idempotency key. Finally, every promise needs a handler. An unhandled rejection is a console error and an unhandledrejection event in the browser, and in Node since version 15 it crashes the process by default."}],"kill":"<b>\"Promise.race cancels the slower requests\"</b> — it only stops you waiting, they keep running. Cancelling takes an AbortSignal you pass in and abort yourself."}},

{n:34,tag:"Frontend core · JS",sec:"js",core:[49],
 ru:{"topic":"this, прототипы, равенство, копирование","qs":["Метод работает при вызове obj.method(), но ломается, если передать его как колбэк. Что определяет this и чем здесь отличаются стрелочные функции?","Говорят, что class в JavaScript — просто синтаксический сахар. Что происходит под капотом и чем вам обходится стрелочная функция в поле класса?","Когда вы вообще пишете == вместо === и как безопасно скопировать вложенный объект состояния?"],"a":[{"q":"Правила this","t":"this определяется в момент вызова, а не там, где функция написана, и я проверяю правила по порядку. Если это стрелочная функция, правила не применяются — она берёт this лексически, из окружающей области. Иначе, если функцию вызвали через new, this — это только что созданный объект. Если через call, apply или bind, то this — это то, что я передал. Если как obj.method(), то this — это obj. А при обычном вызове работает правило по умолчанию: undefined в strict mode (строгом режиме), а модули и классы всегда строгие, или globalThis в нестрогом коде. Поэтому obj.method, переданный как колбэк (функция, которую вызовет кто-то другой), ломается: его вызывают как обычную функцию, и неявная привязка теряется. У стрелочных функций нет своего arguments, поэтому я беру rest-параметры (...args). И у них нет prototype, так что new на стрелке бросает TypeError. Ловушка, за которой я слежу, — стрелка как метод в литерале объекта: она видит не объект, а внешний this."},{"q":"Class и прототипы","t":"Объявление class создаёт функцию-конструктор, а методы попадают в ClassName.prototype, так что все экземпляры делят одну копию. Когда я вызываю user.greet(), движок ищет greet на самом экземпляре, не находит и идёт вверх по цепочке прототипов (сначала User.prototype, потом Object.prototype), пока не найдёт метод или не упрётся в null. extends связывает две цепочки: Child.prototype с Parent.prototype для методов экземпляра и сам Child с Parent для статических членов. Но class добавляет и настоящие вещи: тело всегда в строгом режиме, методы неперечисляемые, а вызов класса без new бросает ошибку. Поля класса работают иначе: они присваиваются каждому экземпляру в конструкторе. Значит, handleClick = () => {...} создаёт новую функцию на каждый экземпляр. Взамен я получаю стабильный this для колбэков (функций, которые вызовет кто-то другой). Но это память на каждый объект, метода нет на прототипе, поэтому подкласс не может вызвать super.handleClick(), и в тестах его не замокать (не подменить заглушкой) через прототип. Для пары компонентов это неважно, а для тысяч объектов я оставлю метод на прототипе и сделаю bind там, где его передаю."},{"q":"Равенство и копии","t":"По умолчанию я пишу ===, потому что == запускает нестрогое сравнение с приведением типов, и результаты трудно держать в голове: пустая строка == 0 даёт true, [] == false тоже true, а null == 0 даёт false. Намеренно я использую == в одном месте: x == null. Это true для null и undefined и на практике больше ни для чего, то есть заменяет двойную проверку. Для NaN не работает ни то, ни другое, там Number.isNaN или Object.is. С копированием так: spread (оператор ...) и Object.assign делают поверхностную копию, только один уровень собственных перечисляемых свойств. Вложенные объекты остаются общими, мутация вложенного массива в копии меняет оригинал, а мемоизированный (закешированный) дочерний компонент, который сравнивает эту вложенную ссылку, не перерисуется. structuredClone делает настоящую глубокую копию и понимает Map, Set, Date и даже циклические ссылки. Но он бросает ошибку на функциях и DOM-узлах, а экземпляры классов возвращает простыми объектами без прототипа. Круг через JSON ещё хуже: Date превращаются в строки, undefined пропадает. А в React я обычно вообще не делаю глубоких копий: копирую только тот путь, который меняю."}],"kill":"<b>«Стрелочная функция привязывает this к объекту, в котором объявлена»</b> — нет, стрелка в литерале объекта берёт this из внешней области, а в модуле это часто undefined."},
 en:{"topic":"this, prototypes, equality, copying","qs":["A method works when called as obj.method() but breaks when you pass it as a callback. What decides this, and how do arrow functions change the picture?","People say class in JavaScript is just sugar. What's actually happening underneath, and what does a class-field arrow function cost you?","When would you ever use == instead of ===, and how do you copy a nested state object safely?"],"a":[{"q":"Rules of this","t":"this is decided at call time, not where the function is written, and I check the rules in order. If it's an arrow function, none of the rules apply — it takes this lexically from the enclosing scope. Otherwise, if it's called with new, this is the freshly created object. If it's called through call, apply or bind, this is whatever I passed. If it's called as obj.method(), this is obj. And a plain call gets the default: undefined in strict mode, which covers modules and classes, or globalThis in sloppy code. That's why passing obj.method as a callback breaks it. The callback is invoked as a plain function, so the implicit binding is gone. Arrows also have no own arguments object, so I use rest parameters. And they have no prototype, so calling new on an arrow throws a TypeError. The trap I watch for is an arrow used as a method in an object literal: it doesn't see the object, it sees the outer this."},{"q":"Class as sugar","t":"A class declaration creates a constructor function, and the methods go onto ClassName.prototype, so every instance shares one copy. When I call user.greet(), the engine looks for greet on the instance, doesn't find it, and walks up the prototype chain (User.prototype, then Object.prototype) until it finds it or hits null. extends links two chains: Child.prototype to Parent.prototype for instance methods, and Child to Parent itself for static members. Class does add real things on top: the body is always strict, methods are non-enumerable, and calling a class without new throws. Class fields are different. They're assigned on each instance in the constructor, so handleClick = () => {...} allocates a new function per instance. That buys a stable this for callbacks. But it costs memory per object, it's not on the prototype so a subclass can't call super.handleClick(), and you can't spy on it through the prototype in tests. For a handful of components it doesn't matter. For thousands of objects I'd keep a prototype method and bind it where I pass it."},{"q":"Equality and copies","t":"I default to === because == runs loose equality with type coercion, and the results are hard to hold in your head: an empty string == 0 is true, [] == false is true, but null == 0 is false. The one place I use == on purpose is x == null. It's true for null and undefined and in practice nothing else, so it replaces a two-part check. For NaN neither works, so I use Number.isNaN or Object.is. For copying, spread and Object.assign are shallow: one level of own enumerable properties. Nested objects stay shared, so mutating the copy's nested array mutates the original, and a memoized child that compares that nested reference won't re-render. structuredClone makes a real deep copy and handles Map, Set, Date and even cycles. But it throws on functions and DOM nodes, and class instances come back as plain objects without their prototype. A JSON round trip is worse: Dates become strings and undefined disappears. In React I usually don't deep copy at all. I copy only the path I change."}],"kill":"<b>\"An arrow function binds this to the object it's defined in\"</b> — no, an arrow in an object literal takes this from the outer scope, which in a module is often undefined."}},

{n:35,tag:"Frontend core · JS",sec:"js",core:[50],
 ru:{"topic":"ESM, CommonJS и бандлер","qs":["Почему ESM важен для размера бандла и как сейчас обстоят дела со смешиванием ESM и CommonJS в Node?","Что на самом деле делает бандлер и чем Vite отличается в dev и в продакшен-сборке?","После спринта основной бандл вырос вдвое. Как вы найдёте причину и где тут code splitting?"],"a":[{"q":"ESM против CJS","t":"Статические импорты и экспорты в ESM стоят на верхнем уровне со строковыми путями, так что граф модулей известен ещё до выполнения кода. Именно это делает возможным tree shaking (удаление неиспользуемого кода): бандлер (сборщик) может доказать, что экспорт никто не импортирует, и выкинуть его. Кроме того, импорты — это живые привязки: если модуль переприсвоит экспортированный let, импортирующий увидит новое значение. require — просто вызов функции в рантайме (во время выполнения): путь можно вычислить, выполняется он синхронно, и я получаю то, что лежит в module.exports в этот момент. Поэтому бандлеры в основном не могут его вычистить. Смешивание раньше болело: require пакета, который есть только в ESM, бросал ERR_REQUIRE_ESM. Сейчас Node поддерживает require(esm) без флага начиная с 22.12 и 20.19, а стабильным его пометили в Node 25.4 в январе 2026 года. Одна оговорка: модуль с top-level await (await на верхнем уровне модуля) через require всё равно не загрузить. У dual-пакетов (которые публикуют обе сборки) своя беда: приложение может загрузить обе копии, синглтоны (объекты в единственном экземпляре) дублируются, а instanceof между копиями ломается. Детали я бы сверил с актуальной документацией Node."},{"q":"Что делает бандлер","t":"Бандлер (сборщик) стартует с точек входа и разрешает каждый импорт в граф модулей. Он трансформирует файлы (TypeScript, JSX, CSS), потом делает tree shaking (удаление неиспользуемого кода), режет граф на чанки (отдельные файлы сборки), минифицирует и пишет файлы с хешем содержимого в имени, чтобы их можно было кешировать навсегда. Vite разделяет это по режимам. В dev он мой код не бандлит: отдаёт нативный ESM и трансформирует каждый файл по запросу. Поэтому старт не растёт с размером приложения, а HMR (горячая замена модулей) трогает только изменённый модуль. Зависимости один раз пребандлятся (заранее собираются), потому что в node_modules есть CommonJS, который надо сконвертировать, а пакеты вроде lodash-es иначе дали бы сотни запросов. Для продакшена делается полная сборка. Начиная с Vite 8, который вышел в марте 2026 года, и пребандлинг, и продакшен-сборка работают на Rolldown — бандлере на Rust. Он заменил старую схему «esbuild в dev, Rollup в проде», и это закрывает целый класс багов «в dev работает, в проде ломается». Режим с бандлингом в dev тоже есть, но пока экспериментальный."},{"q":"Поиск раздувания","t":"Сначала я измеряю, а не гадаю. Собираю с source maps (картами исходников), открываю treemap (карту размеров модулей) и сравниваю с последней хорошей сборкой. Для Vite это rollup-plugin-visualizer. В свежем Next на Turbopack (он по умолчанию с 16-й версии) это next experimental-analyze, потому что @next/bundle-analyzer работает только для сборок на webpack. Обычные подозреваемые: тяжёлая библиотека ради одной функции, barrel-файл (index, который реэкспортирует весь пакет), библиотека дат или иконок, импортированная целиком, или две версии одной зависимости. Исправления скучные: импортировать конкретный путь, заменить на лёгкую библиотеку или нативный API вроде Intl, убрать дубли версий. Дальше code splitting (разбиение кода на части). Динамический import() — это точка разреза: бандлер (сборщик) выносит модуль и его собственные зависимости в отдельный чанк (файл сборки), который грузится по требованию. Самый большой выигрыш даёт разбиение по роутам (маршрутам): App Router в Next уже режет по маршрутам, а в SPA (одностраничном приложении) на Vite я лениво грузлю роуты через React.lazy. В чат-интерфейсе я бы лениво грузил markdown и подсветку синтаксиса: это тяжело и не нужно для первой отрисовки. Ловушка — дробить слишком мелко. Крошечные чанки дают водопад запросов, поэтому я делаю prefetch (предзагрузку) при наведении. И добавляю бюджет размера в CI (автоматические проверки), чтобы это не повторилось."}],"kill":"<b>«Tree shaking выкинет всё неиспользуемое из любого импорта»</b> — он работает только со статическим ESM, а модуль, который бандлер не может признать свободным от побочных эффектов (нет sideEffects: false), остаётся в бандле целиком."},
 en:{"topic":"ESM, CommonJS and the bundler","qs":["Why does ESM matter for bundle size, and what's the current state of mixing ESM and CommonJS in Node?","What does a bundler actually do, and how is Vite different in dev versus the production build?","Your main bundle doubled after a sprint. How do you find out why, and where does code splitting come in?"],"a":[{"q":"ESM vs CJS","t":"Static ESM imports and exports sit at the top level with string literal paths, so the module graph is known before any code runs. That's what makes tree shaking possible — the bundler can prove an export is never imported and drop it. Imports are also live bindings: if the exporting module reassigns an exported let, the importer sees the new value. require is just a function call at runtime. The path can be computed, it runs synchronously, and you get whatever module.exports is at that moment, so bundlers mostly can't prune it. Mixing them used to hurt: requiring an ESM-only package threw ERR_REQUIRE_ESM. Node now supports require(esm) without a flag since 22.12 and 20.19, and it was marked stable in Node 25.4 in January 2026. One catch: a module with top-level await still can't be required. Dual packages that ship both builds have their own hazard. The app can load both copies, so singletons get duplicated and instanceof fails across them. I'd check the current Node docs before promising details."},{"q":"Bundler's job","t":"A bundler starts from entry points and resolves every import into a module graph. It transforms each file (TypeScript, JSX, CSS), then tree-shakes, splits the graph into chunks, minifies, and writes files with content hashes in their names so they can be cached forever. Vite splits this by mode. In dev it doesn't bundle my code: it serves native ESM and transforms each file on request. So startup doesn't grow with app size, and HMR only touches the edited module. Dependencies are pre-bundled once, because node_modules has CommonJS to convert and packages like lodash-es would otherwise fire hundreds of requests. For production it does a full bundle. Since Vite 8, released in March 2026, both pre-bundling and the production build run on Rolldown, a Rust bundler. It replaced the old esbuild-in-dev, Rollup-in-prod split, which closes a whole class of works-in-dev, breaks-in-prod bugs. A bundled dev mode exists too, but it's still experimental."},{"q":"Finding bloat","t":"First I measure instead of guessing. I build with source maps, open a treemap and diff it against the last good build. For Vite that's rollup-plugin-visualizer. On recent Next with Turbopack, the default since 16, it's next experimental-analyze, because @next/bundle-analyzer only covers webpack builds. The usual suspects are a heavy library imported for one function, a barrel file that pulls in a whole package, a date or icon library imported whole, or two versions of the same dependency. The fixes are boring: import the specific path, swap in a lighter library or a native API like Intl, dedupe versions. Then code splitting. A dynamic import() is a split point: the bundler emits that module and its exclusive dependencies as a separate chunk loaded on demand. Route-level splitting is the biggest win — Next's App Router already splits per route, and in a Vite SPA I lazy-load routes with React.lazy. In a chat UI I'd lazy-load the markdown and syntax-highlighting stack, since it's heavy and not needed for first paint. The trap is over-splitting. Tiny chunks create request waterfalls, so I prefetch on hover. And I add a size budget in CI so it doesn't happen again."}],"kill":"<b>\"Tree shaking removes whatever I don't use from any import\"</b> — it only works on static ESM, and a module the bundler can't prove side-effect free (no sideEffects: false) stays in whole."}},

{n:36,tag:"Frontend core · TypeScript",sec:"ts",core:[51],
 ru:{"topic":"Система типов: сужение и размеченные union","qs":["Коллега передаёт в функцию объект с лишним полем-опечаткой, и TypeScript молчит. В другой раз та же опечатка даёт ошибку. Почему?","Когда ты берёшь any, когда unknown, когда never? И как из unknown получить тип, с которым можно работать?","Ты моделируешь состояние запроса или сообщения в чате. Почему размеченное объединение, а не один тип с кучей опциональных полей?"],"a":[{"q":"Структурная типизация","t":"TypeScript использует structural typing (структурную типизацию). Значение подходит под тип, если у него есть как минимум нужные свойства совместимых типов. Имя типа не важно, лишние свойства допустимы. Поэтому если я сначала кладу объект в переменную, а потом передаю её, поле с опечаткой — просто лишнее свойство, и всё компилируется. Исключение — excess property checking (проверка лишних свойств). Когда я передаю свежий объектный литерал прямо в вызов, компилятор считает лишние ключи ошибкой, потому что больше ни у кого нет ссылки на этот литерал. Отсюда и разница: одна и та же опечатка ловится в одном месте и не ловится в другом. Ловушка, за которой я слежу, это опциональные поля: опечатка в опциональном ключе, переданном через переменную, обычно молча проходит. Исключение — когда у объекта нет ни одного общего свойства с типом из одних опциональных полей: это ловит weak type check (проверка «слабых» типов). Когда мне нужна номинальная семантика, например чтобы не путать UserId и OrderId, которые оба строки, я использую branded type (помеченный тип): строку, пересечённую с уникальным свойством-меткой."},{"q":"any, unknown, never","t":"any выключает проверку, и он заразен. Всё, что я читаю из any, тоже any, так что один JSON.parse может незаметно расползтись по кодовой базе. unknown — честная версия. Он принимает любое значение, но пока я его не сузил, сделать с ним ничего нельзя. Это правильный тип для всего, что приходит снаружи: распарсенный JSON, ошибка в catch, данные из postMessage. never — пустой тип, у него нет значений. Это тип возврата функции, которая всегда бросает исключение, и то, что остаётся, когда все варианты исключены. Чтобы из unknown получить полезный тип, я делаю narrowing (сужение типа): typeof для примитивов, помня, что typeof null это 'object'; instanceof для классов, который ломается между realm-ами (отдельными JS-окружениями, например iframe); in для проверки ключа; сравнение с литералами. Для переиспользуемых проверок пишу type guard (функцию-проверку типа), которая возвращает x is T, или assertion function (функцию-утверждение) с asserts x is T, которая вместо false бросает ошибку. Подвох в том, что компилятор слепо верит телу такой функции. Если проверка неверная, я просто соврал, только в несколько шагов."},{"q":"Размеченные объединения","t":"В мешке опциональных полей, скажем status плюс необязательные data и error, тип разрешает состояния, которых не бывает: загрузка с данными и ошибкой одновременно или успех без данных. И каждый потребитель проверяет всё на null. Discriminated union (размеченное объединение) делает каждое состояние отдельным вариантом с общим литеральным тегом: status 'loading' без полей, 'success' с data, 'error' с error. Когда я делаю switch по status, TypeScript сужает тип в каждой ветке, и data существует только там, где она реально есть. Для исчерпывающей проверки я добавляю ветку default, где присваиваю значение переменной типа never. Если кто-то позже добавит состояние 'cancelled', эта строка перестанет компилироваться и укажет на каждый switch, который надо обновить. Ровно так я описываю состояние сообщения в чате со стримингом (потоковой выдачей ответа): streaming, done, error и aborted несут разные поля. Одна оговорка про runtime (время выполнения): если данные приходят снаружи, ветка never должна залогировать и пропустить неизвестное значение, а не уронить приложение."}],"kill":"<b>«unknown — это почти any»</b> — any выключает проверку, а unknown заставляет сначала сузить тип. Следом идёт <b>«TypeScript всегда запрещает лишние свойства»</b>, хотя он делает это только для свежих объектных литералов."},
 en:{"topic":"Type system core: narrowing and unions","qs":["A teammate passes an object with a typo'd extra field into a function and TypeScript says nothing. Another time the same typo is an error. Why?","When do you reach for any, unknown or never? And how do you get from unknown to something you can actually use?","You're modelling a request state or a chat message. Why a discriminated union instead of one type with a bunch of optional fields?"],"a":[{"q":"Structural typing","t":"TypeScript is structurally typed. A value is assignable to a type if it has at least the required properties with compatible types. The type's name doesn't matter, and extra properties are fine. So if I build the object in a variable first and then pass the variable, the typo'd field is just an extra property and it compiles. The exception is excess property checking. When I pass a fresh object literal directly, the compiler treats unknown keys as mistakes, because nothing else can hold a reference to that literal. That's why the same typo is caught in one place and not the other. The trap I watch for is optional fields: a misspelled optional key passed through a variable usually slips through silently. The exception is when the object shares no property at all with an all-optional type, where the weak type check catches it. When I actually need nominal behaviour, like not mixing up a UserId and an OrderId that are both strings, I use a branded type, which is a string intersected with a unique tag property."},{"q":"any / unknown / never","t":"any switches the checker off, and it's contagious. Anything I read off an any is also any, so one JSON.parse can quietly spread through a codebase. unknown is the honest version. It accepts any value, but I can't do anything with it until I narrow it. That's the right type for anything from outside: parsed JSON, errors in a catch clause, postMessage data. never is the empty type, no value has it. It's the return type of a function that always throws, and it's what's left after every case is eliminated. To get from unknown to something usable, I narrow: typeof for primitives, remembering typeof null is 'object'; instanceof for classes, which breaks across realms like iframes; in for checking a key; equality against literals. For reusable checks I write a type guard that returns x is T, or an assertion function with asserts x is T that throws instead of returning false. The catch is that the compiler trusts the guard's body blindly. If the check is wrong, I've just lied with extra steps."},{"q":"Discriminated unions","t":"With a bag of optional fields, say status plus optional data and optional error, the type allows states that can't exist: loading with data and an error at the same time, or success with no data. And every consumer has to null-check everything. A discriminated union makes each state its own member with a shared literal tag: status 'loading' with no fields, 'success' with data, 'error' with error. When I switch on status, TypeScript narrows each branch, so data only exists where it's actually there. For exhaustiveness I add a default branch that assigns the value to a variable typed never. If someone adds a 'cancelled' state later, that line stops compiling and points at every switch that needs updating. I model chat message state in a streaming UI exactly like this: streaming, done, error and aborted each carry different fields. One caveat at runtime: if the data comes from outside, the never branch should log and skip the unknown value, not crash the app."}],"kill":"<b>\"unknown is basically any\"</b> — any switches checking off, unknown forces you to narrow first. Close second: <b>\"TypeScript always rejects extra properties\"</b>, when it only does that for fresh object literals."}},

{n:37,tag:"Frontend core · TypeScript",sec:"ts",core:[52],
 ru:{"topic":"Generics и программирование на уровне типов","qs":["Как бы ты типизировал хелпер getProperty(obj, key)? И что происходит, когда в условный тип передают объединение?","Какими utility types ты реально пользуешься, как они устроены, и Extract — это просто пересечение?","Для объекта конфига: аннотация типа, satisfies или as? И где ты останавливаешься с хитрыми типами?"],"a":[{"q":"Generics и условия","t":"Я бы написал getProperty<T, K extends keyof T>(obj: T, key: K): T[K]. Ограничение на K значит, что компилируются только реальные ключи, а indexed access (доступ к типу по индексу) T[K] возвращает точный тип свойства. Так что getProperty(user, 'id') вернёт number, а не объединение всех значений. Ограничения держат generics (обобщённые типы) честными: T extends { id: string } говорит, что мне нужно, и ничего сверх. Conditional types (условные типы) — это if системы типов: T extends U ? X : Y. Сюрприз тут в дистрибутивности (распределении по членам объединения). Когда T это голый параметр типа и я передаю объединение, условие применяется к каждому члену отдельно, а результаты объединяются. Поэтому ToArray<string | number> даёт string[] | number[], а не (string | number)[]. Если мне это не нужно, я оборачиваю обе стороны в квадратные скобки: [T] extends [U]. infer позволяет вытащить тип из шаблона, например T extends Promise<infer V> ? V : T. Примерно так устроены ReturnType и Awaited, только Awaited ещё рекурсивно разворачивает вложенные промисы."},{"q":"Mapped и utility","t":"Mapped type (отображённый тип) перебирает ключи: { [K in keyof T]: ... }. Добавляя ? или readonly, или снимая их минусом, получаем Partial, Required и Readonly. С TS 4.1 ключи можно переназначать через as, например превратить каждый ключ в метод вида getName через template literal type (шаблонный строковый тип) или выкинуть ключ, отобразив его в never. В повседневной работе я чаще всего беру Pick и Omit, чтобы вывести props компонента из модели, Partial для тела запроса на частичное обновление, Record для словарей, а ReturnType и Awaited, чтобы описать результат асинхронной функции, не повторяя тип руками. Extract и Exclude — это фильтры по объединению. Exclude убирает члены, совместимые с U, Extract оставляет их. Это не пересечение. Extract<string | number, 'a'> даёт never, потому что ни string, ни number не присваиваются в 'a', а (string | number) & 'a' даёт 'a'. Ловушка с Omit: он не дистрибутивный, поэтому Omit над размеченным объединением оставляет только общие ключи, и сужение пропадает. Тогда я пишу дистрибутивную версию: T extends unknown ? Omit<T, K> : never."},{"q":"satisfies против as","t":"Аннотация типа, const config: Config = ..., проверяет значение, но дальше переменная просто Config: литеральная информация потеряна, и каждый опциональный ключ выглядит как возможно undefined. as Config — это type assertion (утверждение типа). Оно не проверяет, что объект полный, а отказывает только когда типы почти не пересекаются, так что прячет недостающие поля. satisfies Config, появившийся в TS 4.9, проверяет значение против типа, но сохраняет выведенный тип: я получаю и ошибку на опечатке, и точные литеральные ключи потом. as const делает всё readonly и литеральным. Так я превращаю массив имён маршрутов или вариантов модели в объединение через typeof arr[number]. Комбинация as const satisfies Config — мой выбор по умолчанию для конфигов. Про type gymnastics (акробатику на типах) моё правило — читаемость для следующего человека. Если типу нужны три вложенных условия с infer и комментарий, который его объясняет, и это код приложения, а не библиотеки, я пишу тип явно или генерирую его из схемы. Хитрые типы дают сообщения об ошибках, которые никто не может прочесть, и замедляют компилятор."}],"kill":"<b>«Extract — это просто пересечение»</b> — он фильтрует члены объединения по совместимости. И попытка заглушить ошибку в конфиге через <b>as Config</b>: это непроверяемое утверждение, а проверяемая версия — satisfies."},
 en:{"topic":"Generics and type-level programming","qs":["Walk me through typing a getProperty(obj, key) helper. Then tell me what happens when you pass a union into a conditional type.","Which utility types do you actually use, how are they built, and is Extract just an intersection?","For a config object: type annotation, satisfies, or as? And where do you draw the line on type-level cleverness?"],"a":[{"q":"Generics, conditionals","t":"I'd write getProperty<T, K extends keyof T>(obj: T, key: K): T[K]. The constraint on K means only real keys compile, and the indexed access type T[K] gives back the exact property type. So getProperty(user, 'id') returns number, not a union of every value type. Constraints are how generics stay honest: T extends { id: string } says what I need and nothing more. Conditional types are the if statement of the type system: T extends U ? X : Y. The surprise is distributivity. When T is a naked type parameter and I pass a union, the condition runs per member and the results are unioned. So ToArray<string | number> gives string[] | number[], not (string | number)[]. If I don't want that, I wrap both sides in brackets: [T] extends [U]. infer lets me pull a type out of a pattern, for example T extends Promise<infer V> ? V : T. That's roughly how ReturnType and Awaited are built, except Awaited also unwraps nested promises recursively."},{"q":"Mapped, utility types","t":"A mapped type iterates keys: { [K in keyof T]: ... }. Adding ? or readonly, or removing them with a minus, gives you Partial, Required and Readonly. Since TS 4.1 I can remap keys with as, for example turn every key into a getName-style method with a template literal type, or drop a key by mapping it to never. Day to day I mostly use Pick and Omit to derive component props from a model, Partial for patch payloads, Record for lookup maps, and ReturnType and Awaited to type what an async function resolves to without restating it. Extract and Exclude are filters over a union. Exclude removes the members assignable to U, Extract keeps them. That's not intersection. Extract<string | number, 'a'> is never, because neither string nor number is assignable to 'a', while (string | number) & 'a' is 'a'. The Omit trap I watch for: it isn't distributive, so Omit on a discriminated union keeps only the common keys and I lose narrowing. Then I write a distributive version: T extends unknown ? Omit<T, K> : never."},{"q":"satisfies vs as","t":"A type annotation, const config: Config = ..., checks the value, but afterwards the variable is just Config. Literal information is gone and every optional key looks possibly undefined. as Config is a type assertion. It doesn't check that the object is complete, it only refuses when the types barely overlap, so it hides missing fields. satisfies Config, added in TS 4.9, checks the value against the type but keeps the inferred type, so I get the error on a typo and the precise literal keys afterwards. as const makes everything readonly and literal. That's how I turn an array of route names or model options into a union with typeof arr[number]. as const satisfies Config is my default for config objects. On type gymnastics, my rule is readability for the next person. If a type needs three nested conditionals with infer and a comment explaining it, and it's application code rather than a library, I write the type out or generate it from a schema. Clever types produce error messages nobody can read, and they slow the compiler down."}],"kill":"<b>\"Extract is just an intersection\"</b> — it filters union members by assignability. Also reaching for <b>as Config</b> to silence a config error: that's an unchecked assertion, and satisfies is the checked version."}},

{n:38,tag:"Frontend core · TypeScript",sec:"ts",core:[53],
 ru:{"topic":"Граница runtime: валидация и стримы","qs":["Ответ API, значение из localStorage и аргументы tool call от LLM в итоге имеют тот тип, к которому ты их привёл через as. Что с этим не так и что ты делаешь вместо этого?","Расскажи, как ты обрабатываешь стриминговый ответ LLM в TypeScript. Как ты типизируешь события?","Включил бы ты noUncheckedIndexedAccess и exactOptionalPropertyTypes в большой существующей кодовой базе? Что они ловят и чего это стоит?"],"a":[{"q":"Валидация границ","t":"Типы стираются при компиляции. В runtime (во время выполнения) ничто не проверяет, что JSON соответствует моему интерфейсу, поэтому response.json() с типом any или мой as User — это обещание, которое никто не исполняет. Всё, что пересекает границу, остаётся unknown, пока не проверено: ответы API, localStorage, переменные окружения и особенно вывод модели. Аргументы tool call (вызова инструмента) — это сгенерированный текст. В них может не быть поля или тип может быть не тот. Strict-режимы (строгие режимы) для инструментов помогают со структурой, но ограничения вроде min, max или регулярных выражений не все применяются при генерации, а обрыв по max_tokens оставляет битый JSON. Поэтому я пишу одну zod-схему и вывожу тип через z.infer, и схема становится единственным источником правды. На границе я использую safeParse: он возвращает success с data или error с issues, а не бросает исключение. Для tool call я отправляю эти issues обратно модели, чтобы она исправилась. parse, который бросает, я оставляю для fail-fast (падения сразу), например для конфига окружения при старте. В zod 4 форматы строк вынесены на верхний уровень, как z.email(), а старая форма через метод устарела. Вместо .strict() рекомендуют z.strictObject, хотя .strict() считается legacy (устаревшим API) и по-прежнему работает."},{"q":"Типизированный стрим","t":"Стрим (поток ответа) Anthropic — это последовательность server-sent events (событий, которые сервер шлёт по одному HTTP-соединению): message_start, затем для каждого content block (блока контента) content_block_start, несколько content_block_delta и content_block_stop, потом message_delta и message_stop, а между ними могут приходить ping. Я типизирую это как размеченное объединение по type, и delta внутри content_block_delta — отдельное объединение: text_delta несёт text, input_json_delta несёт partial_json для аргументов инструмента. В reducer-е (функции, которая сворачивает события в состояние) я делаю switch по event.type, TypeScript сужает каждую ветку, и delta.text доступен только там, где он есть. В runtime (время выполнения) важны две вещи. Аргументы инструмента приходят кусками JSON, поэтому я накапливаю строку по index блока и делаю JSON.parse и валидацию только когда пришёл content_block_stop этого блока. И документация API прямо говорит, что могут появиться новые типы событий. Поэтому в default я оставляю присваивание в never для проверки полноты при компиляции, но в runtime логирую и игнорирую неизвестные события, а не бросаю ошибку. Иначе безобидное расширение API роняет чат-интерфейс."},{"q":"Флаги строгости","t":"strict — это база, и с TypeScript 6.0 он включён по умолчанию. В него входят strictNullChecks, noImplicitAny, unknown для переменных в catch и другое. Два флага, которые я бы добавил, в strict не входят. noUncheckedIndexedAccess добавляет undefined к arr[i] и record[key], и это правда, потому что index signature (индексная сигнатура) не обещает, что ключ существует. Он ловит классическое падение на пустом массиве или отсутствующем ключе в словаре. exactOptionalPropertyTypes различает «ключа нет» и «ключ есть со значением undefined», так что timeout?: number больше не принимает явный undefined. Это ловит реальный баг: spread (разворот объекта) overrides с timeout: undefined поверх defaults молча затирает значение по умолчанию. Цена в большой кодовой базе — волна ошибок, многие из которых шум, вроде arr[0] сразу после проверки длины, плюс типы библиотек, не рассчитанные на exactOptionalPropertyTypes. Я бы включал по одному флагу, чинил по директориям и фиксировал baseline (снимок текущих ошибок) в CI (конвейере проверок), чтобы новые не появлялись. Расставлять non-null assertion (оператор !, утверждение «не null») только ради снижения счётчика значит убить весь смысл."}],"kill":"<b>«TypeScript проверит ответ по моему интерфейсу»</b> — типы стираются, и as User это непроверяемое обещание. То же с <b>доверием к аргументам tool call, раз у инструмента есть схема</b>: их надо валидировать как любой другой вход."},
 en:{"topic":"The runtime boundary: validation and streams","qs":["An API response, a localStorage value and an LLM's tool-call arguments all end up typed as whatever you cast them to. What's wrong with that, and what do you do instead?","Walk me through consuming a streaming LLM response in TypeScript. How do you type the events?","Would you turn on noUncheckedIndexedAccess and exactOptionalPropertyTypes in a large existing codebase? What do they catch, and what does it cost?"],"a":[{"q":"Validating boundaries","t":"Types are erased at compile time. Nothing at runtime checks that JSON matches my interface, so response.json() typed as any, or me writing as User, is a promise nobody enforces. Anything crossing a boundary is unknown until validated: API responses, localStorage, env vars, and especially model output. Tool-call arguments are generated text. A field can be missing or have the wrong type. Strict tool modes help with structure, but constraints like min, max or regex patterns aren't all enforced during generation, and a max_tokens cutoff leaves broken JSON. So I write one zod schema and derive the type with z.infer, which makes the schema the single source of truth. At the boundary I use safeParse, which returns success with data, or an error with issues, instead of throwing. For a tool call I send those issues back to the model so it can correct itself. parse, which throws, I keep for fail-fast cases like env config at startup. In zod 4, string formats moved to top level, like z.email(), and the old method form is deprecated. z.strictObject is preferred over .strict(), which is legacy but still works."},{"q":"Typed streams","t":"Anthropic's stream is a sequence of server-sent events: message_start, then for each content block a content_block_start, some content_block_delta events and a content_block_stop, then message_delta and message_stop, with ping events possibly in between. I type it as a discriminated union on type, and the delta inside content_block_delta is its own union: text_delta carries text, input_json_delta carries partial_json for tool arguments. In my reducer I switch on event.type and TypeScript narrows each branch, so I can only touch delta.text where it exists. Two things matter at runtime. Tool arguments arrive as JSON fragments, so I accumulate the string per block index and only JSON.parse and validate it when that block's content_block_stop arrives. And the API docs say new event types may be added. So my default branch keeps the never assignment for compile-time exhaustiveness, but at runtime it logs and ignores unknown events instead of throwing. Otherwise a harmless API addition takes down the chat UI."},{"q":"Strictness flags","t":"strict is the baseline, and since TypeScript 6.0 it's on by default. It bundles strictNullChecks, noImplicitAny and unknown catch variables, among others. The two flags I'd add are not part of strict. noUncheckedIndexedAccess makes arr[i] and record[key] include undefined, which is the truth, because an index signature doesn't promise the key exists. It catches the classic crash on an empty array or a missing map entry. exactOptionalPropertyTypes separates 'key absent' from 'key present with undefined', so timeout?: number no longer accepts an explicit undefined. That catches a real bug: spreading overrides with timeout: undefined over defaults silently wipes the default. The cost in a big codebase is a wave of errors, many of them noise, like arr[0] right after a length check, plus library types not written for exactOptionalPropertyTypes. I'd turn on one flag at a time, fix by directory, and baseline the existing errors in CI so no new ones land. Sprinkling non-null assertions just to make the count go down defeats the purpose."}],"kill":"<b>\"TypeScript checks the response against my interface\"</b> — types are erased, so as User is an unchecked promise. Same with <b>trusting tool-call arguments because the tool has a schema</b>: validate them like any other input."}},

{n:39,tag:"Frontend core · React",sec:"react",core:[54],
 ru:{"topic":"Модель рендера","qs":["Что на самом деле заставляет компонент перерендериться и что происходит между рендером и обновлением DOM?","В списке key — это индекс. Пользователь удаляет первую строку, и текст в поле ввода оказывается у другого элемента. Что произошло и как это связано с правилами хуков?","Я трижды вызываю setCount(count + 1) в обработчике клика, а счётчик растёт на один. Почему и как это исправить?"],"a":[{"q":"Триггеры и фазы","t":"Компонент рендерится (React заново вызывает его функцию), когда его собственный state (состояние) меняется на новое значение, когда рендерится родитель или когда меняется context, который он читает. Props (входные параметры) отдельным триггером по сути не являются: они меняются только потому, что отрендерился родитель. Если записать в state то же значение по Object.is, React выходит без рендера, а мутация ref вообще ничего не запускает. В этом и смысл ref: значение живёт между рендерами, но ничего не перерисовывает. Дальше две фазы. В render phase (фаза вычисления) React вызывает мою функцию, получает новое дерево элементов и делает reconciliation (сверку) с предыдущим. Эта фаза должна быть чистой, потому что React может вызвать её дважды или выбросить результат. В commit phase (фаза применения) React вносит минимальные изменения в DOM и привязывает refs, затем запускает layout effects до того, как браузер отрисует кадр, а обычные эффекты обычно после. Но если обновление вызвано взаимодействием вроде клика, React может выполнить и их до отрисовки. Так что повторный рендер не значит, что DOM трогали. Ловушка, за которой я слежу, — считать каждый рендер дорогим. Обычно рендер дешёвый, а цена в том, что он вычисляет, или в каскадах."},{"q":"Key и хуки","t":"React сопоставляет новое дерево со старым по позиции и типу, а внутри списка по key. Key — это идентичность элемента, и state привязан к идентичности, а не к данным. Если key это индекс и я удаляю нулевую строку, бывшая первая строка получает key ноль. React видит, что key ноль на месте и тип тот же, поэтому оставляет этот экземпляр со всем его state, например текст в неконтролируемом поле ввода или раскрытый блок, и просто передаёт новые props. Данные сдвинулись, а state остался на прежней позиции. Вставка в начало или перестановка ломаются так же. Решение — стабильный id из данных. Только не Math.random: тогда каждая строка ремаунтится (создаётся заново) на каждом рендере. Индекс годится только для статичного списка без state в строках. Хуки (функции вида useState) работают на той же идее. React хранит state хуков списком на компонент и узнаёт каждый хук по порядку вызова. В этом весь смысл правил хуков. Если вызвать хук внутри условия, на следующем рендере порядок вызовов сдвинется, и каждый хук после него прочитал бы ячейку соседа. Поэтому React обычно бросает ошибку: «Rendered more hooks than during the previous render» или «Rendered fewer hooks than expected»."},{"q":"Очередь и batching","t":"setState не меняет переменную. Он ставит обновление в очередь и планирует рендер. count — константа, захваченная замыканием этого рендера, поэтому если там ноль, все три вызова считают ноль плюс один, и я получаю один. Решение — функциональная форма, setCount(c => c + 1). React применяет функции обновления по порядку к ожидающему значению, и я получаю три. Кроме того, с React 18 и createRoot batching (объединение нескольких обновлений в один рендер) работает автоматически везде: в Promise, setTimeout и нативных обработчиках событий, а не только в обработчиках React. Несколько вызовов set-функций подряд дают один рендер. Когда мне правда нужно синхронно обновить DOM, например прокрутить к только что добавленному сообщению и прочитать его позицию, я оборачиваю это обновление в flushSync из react-dom. Это escape hatch (аварийный выход): он форсирует синхронный рендер и бьёт по производительности, так что я использую его редко. В чате с потоковым ответом модели это важно постоянно. Я добавляю куски ответа функциональными обновлениями, потому что callback (функция обратного вызова) стрима замкнул state из старого рендера."}],"kill":"<b>«setState сразу меняет state»</b> — он ставит обновление в очередь, и переменная сразу после вызова по-прежнему хранит старое значение этого рендера."},
 en:{"topic":"The render model","qs":["What actually makes a component re-render, and what happens between the render and the DOM changing?","A list uses the index as key. The user deletes the first row and the text in an input shows up under the wrong item. What happened, and how does it relate to the rules of hooks?","I call setCount(count + 1) three times in a click handler and the counter only goes up by one. Why, and how do you fix it?"],"a":[{"q":"Triggers and phases","t":"A component renders when its own state is set to a new value, when its parent renders, or when a context it reads changes. Props aren't really a separate trigger, because props only change when the parent renders. Setting state to the same value by Object.is bails out, and mutating a ref does nothing at all. That's the point of refs: values that live across renders but shouldn't repaint anything. Then come two phases. In the render phase React calls my function, gets a new element tree and reconciles it against the previous one. That phase must be pure, because React may call it twice or throw the result away. In the commit phase React applies the minimal DOM changes and attaches refs, then runs layout effects before the browser paints, and regular effects usually after. If the update came from an interaction like a click, React may run those before paint too. So a re-render doesn't mean the DOM was touched. The trap I watch for is treating every render as expensive. Usually renders are cheap, and the cost is in what they compute or in cascades."},{"q":"Keys and hooks","t":"React matches the new tree to the old one by position and type, and inside a list by key. The key is the element's identity, and state belongs to the identity, not to the data. With index as key, when I delete row zero, the old row one now gets key zero. React sees key zero still there with the same type, so it keeps that instance with its state, like an uncontrolled input's text or an expanded toggle, and only passes new props. The data shifts, the state stays in the slot. Inserting at the top or reordering breaks the same way. The fix is a stable id from the data. Never Math.random, which remounts every row on every render. Index is fine only for a static list with no state in the rows. Hooks work on the same idea. React stores hook state in a list per component and identifies each hook by its call order. That's the whole reason behind the rules of hooks. If I call a hook inside a condition, the call order shifts next render and later hooks would read their neighbour's slot, so React usually throws, either 'Rendered more hooks than during the previous render' or 'Rendered fewer hooks than expected'."},{"q":"Queue and batching","t":"setState doesn't change the variable. It queues an update and schedules a render. count is a constant captured by this render's closure, so if it's zero, all three calls compute zero plus one and I get one. The fix is the functional form, setCount(c => c + 1). React applies the updaters in order against the pending value, so I get three. Updates are also batched. Since React 18 with createRoot, batching is automatic everywhere: inside promises, setTimeout and native event handlers too, not just React's own handlers. Several setters in a row produce one render. When I really need the DOM updated synchronously, say to scroll to a message I just appended and read its position, I wrap that update in flushSync from react-dom. It's an escape hatch. It forces a synchronous render and hurts performance, so I use it rarely. In a streaming chat UI this matters constantly. I append chunks with functional updates, because the stream callback closed over state from an older render."}],"kill":"<b>\"setState updates the state immediately\"</b> — it queues an update, so reading the variable right after still gives this render's old value."}},

{n:40,tag:"Frontend core · React",sec:"react",core:[55],
 ru:{"topic":"Эффекты","qs":["Когда useEffect — правильный инструмент, когда нет и когда ты возьмёшь useLayoutEffect?","Ты загружаешь профиль в эффекте при смене userId, и иногда на странице оказываются данные предыдущего пользователя. Почему и при чём тут Strict Mode?","Линтер требует добавить в массив зависимость, из-за которой эффект будет перезапускаться, а ты этого не хочешь. Что делаешь?"],"a":[{"q":"Для чего эффект","t":"useEffect нужен, чтобы синхронизировать компонент с чем-то вне React: WebSocket, браузерным API, сторонним виджетом, подпиской. Если внешней системы нет, эффект мне, скорее всего, не нужен. Две ошибки я вижу постоянно. Первая — производное состояние: хранить fullName в state и обновлять его в эффекте при смене firstName. Это два рендера и промежуточный кадр со старым значением. Я просто вычисляю его во время рендера, а если это правда дорого, через useMemo. Вторая — реакция на действия пользователя: выставить флаг submitted, а потом отправить запрос в эффекте. Этой логике место в обработчике события, потому что только там я знаю, почему это произошло. Теперь про тайминг. useEffect обычно выполняется после отрисовки кадра и не блокирует его. useLayoutEffect выполняется синхронно после обновления DOM, но до отрисовки. Я беру его, только когда нужно измерить layout (геометрию элементов) и поправить что-то до того, как пользователь это увидит, например позицию тултипа (всплывающей подсказки), иначе будет мигание. Он блокирует отрисовку, поэтому это исключение."},{"q":"Гонка и cleanup","t":"Это race condition (гонка запросов). userId меняется с 1 на 2, оба запроса в полёте, и если первый ответит последним, он перезапишет state данными первого пользователя. Решение — cleanup (функция очистки). Каждый раз при перезапуске эффекта React сначала вызывает cleanup предыдущего, и именно там я отменяю старое. Простой вариант — флаг ignore: let ignore = false, проверяю его перед setState, а в cleanup ставлю true. Лучше AbortController: передаю его signal в fetch и вызываю abort в cleanup, и тогда отменяется сам сетевой запрос, а не только его результат. Ровно это и подсвечивает Strict Mode. В разработке React 18 и новее один раз монтирует, размонтирует и снова монтирует компонент, так что каждый эффект проходит setup, cleanup, setup. Если от двойного запуска что-то ломается, например появляются две подписки или два соединения, значит cleanup отсутствует или неправильный. В продакшене этого нет. Тот же паттерн отмены нужен для вызовов LLM: когда пользователь переключает чат или жмёт стоп, я прерываю стрим, чтобы чужие токены не попали не в тот диалог."},{"q":"Зависимости","t":"Для начала я воспринимаю массив зависимостей как описание, а не как расписание. В нём перечислены все реактивные значения, которые читает эффект, чтобы React мог пересинхронизироваться, когда одно из них меняется. Если одно пропустить, эффект держит stale closure (устаревшее замыкание): setInterval, созданный при монтировании, навсегда видит count первого рендера. Заглушить линтер — почти всегда и есть баг. Поэтому я пробую по порядку: вынести логику из эффекта, использовать функциональное обновление, чтобы вообще не читать state, или перенести объекты и функции внутрь эффекта, чтобы они не создавались заново на каждом рендере. Действительно сложный случай — когда эффекту нужно последнее значение, но перезапускаться из-за него он не должен. Например, подключение к комнате чата, которое пишет analytics-событие с текущей темой. Для этого и есть useEffectEvent. Он стабилен с React 19.2 и даёт функцию, которая всегда видит свежие props и state. Я вызываю её только внутри эффекта и никогда не кладу в зависимости. До 19.2 обходным путём был ref с последним значением."}],"kill":"<b>«Пустой массив зависимостей значит “запустить один раз при монтировании”»</b> — он значит, что эффект не читает реактивных значений; если читает, это stale closure, а в dev Strict Mode всё равно запустит его дважды."},
 en:{"topic":"Effects","qs":["When is useEffect the right tool, when is it the wrong one, and when would you use useLayoutEffect instead?","You fetch a profile in an effect when userId changes, and sometimes the page shows the previous user's data. Why, and what does Strict Mode have to do with it?","The linter wants a dependency in the array that would make the effect re-run, and you don't want that. What do you do?"],"a":[{"q":"What effects are for","t":"useEffect is for synchronizing a component with something outside React: a WebSocket, a browser API, a third-party widget, a subscription. If there's no external system, I probably don't need an effect. Two misuses I see constantly. First, derived state: storing fullName in state and updating it in an effect when firstName changes. That's two renders with a stale frame in between. I just compute it during render, with useMemo if it's genuinely expensive. Second, reacting to user events: setting a submitted flag and then posting in an effect. That logic belongs in the event handler, because that's the only place I know why it happened. On timing, useEffect usually runs after the browser paints, so it doesn't block the frame. useLayoutEffect runs synchronously after the DOM is updated but before paint. I use it only when I have to measure layout and adjust before the user sees it, like positioning a tooltip, otherwise it flickers. It blocks painting, so it's the exception."},{"q":"Races and cleanup","t":"It's a race. userId goes from 1 to 2, both requests are in flight, and if the first one resolves last, it overwrites state with user 1's data. The fix is cleanup. Every time the effect re-runs, React first runs the previous effect's cleanup, so that's where I cancel. The simple version is an ignore flag: let ignore = false, check it before setState, set it to true in cleanup. Better is an AbortController. I pass its signal to fetch and call abort in cleanup, which cancels the network request itself, not just the result. This is exactly what Strict Mode is surfacing. In development, React 18 and later mounts, unmounts and remounts each component once, so every effect runs setup, cleanup, setup. If that double run breaks something, like two subscriptions or two connections, my cleanup is missing or wrong. It doesn't happen in production. The same abort pattern matters for LLM calls. When the user switches chats or hits stop, I abort the stream so stale tokens never land in the wrong conversation."},{"q":"Dependencies","t":"First, I treat the dependency array as a description, not a schedule. It lists every reactive value the effect reads, so React can re-sync when one changes. If I leave one out, the effect keeps a stale closure. A setInterval created on mount will see the first render's count forever. Silencing the linter is almost always the bug. So I try, in order: move the logic out of the effect, use a functional update so I don't read the state at all, or move objects and functions inside the effect so they aren't new on every render. The genuinely hard case is when the effect needs the latest value but shouldn't re-run when it changes. Say a chat room connection that logs an analytics event with the current theme. That's what useEffectEvent is for. It's been stable since React 19.2, and it gives me a function that always sees the latest props and state. I call it only from inside the effect and never list it in deps. Before 19.2 the workaround was a ref holding the latest value."}],"kill":"<b>\"An empty dependency array means run once on mount\"</b> — it means the effect reads no reactive values; if it does, you have a stale closure, and in dev Strict Mode runs it twice anyway."}},

{n:41,tag:"Frontend core · React",sec:"react",core:[56],
 ru:{"topic":"Производительность","qs":["Экран в React тормозит. С чего начнёшь и что на самом деле дают memo, useMemo и useCallback?","Мы положили user, theme и cart в один Context, и всё приложение перерендеривается при каждом изменении корзины. Почему и как это чинить?","Спроектируй рендеринг длинной переписки в AI-чате, где последнее сообщение приходит потоком, токен за токеном."],"a":[{"q":"Сначала замер","t":"Я сначала измеряю, а потом что-то трогаю. React DevTools Profiler записывает каждый commit (применение изменений к DOM) как flame graph (диаграмму времени по компонентам), показывает, сколько занял каждый компонент, а с включённой опцией записи причин рендера говорит, что это было: изменение state, props или рендер родителя. Часто оказывается, что виноват большой компонент, который рендерится на каждое нажатие клавиши, или одно дорогое вычисление, а не сам React. memo позволяет компоненту пропустить рендер, если props поверхностно равны прошлым. useMemo кэширует вычисленное значение, useCallback кэширует функцию, оба по зависимостям. Они стоят сравнения и памяти на каждом рендере и работают только вместе: memo на дочернем компоненте бесполезен, если я каждый рендер передаю ему новый объект или inline-стрелку (функцию, созданную прямо в JSX), потому что поверхностное сравнение проваливается. На этом требовании стабильных props ручная мемоизация чаще всего и ломается. Сегодня я бы опирался на React Compiler, который вышел в версии 1.0 в октябре 2025. Это Babel-плагин, который на этапе сборки мемоизирует компоненты и значения автоматически. Лучше всего он работает с React 19, поддерживает 17 и 18 через react-compiler-runtime, но только если код соблюдает правила React."},{"q":"Ловушка Context","t":"Каждый потребитель context перерендеривается, когда value провайдера меняется по Object.is, и memo на потребителе этого не останавливает. Обычно ломаются две вещи. Провайдер создаёт value как новый объектный литерал на каждом рендере, так что даже посторонний рендер родителя расходится по всем потребителям. И один context несёт несвязанные данные, поэтому изменение корзины перерендеривает всё, что читает только тему. Исправления, от самого дешёвого. Мемоизировать value через useMemo по реальным полям. Разделить контексты по частоте изменений: тему и пользователя отдельно от корзины, и часто ещё отделить state от dispatch, потому что сеттеры стабильны. Когда много компонентов читают маленькие кусочки быстро меняющегося состояния, я переношу его в store (внешнее хранилище) с селекторами. Zustand построен на useSyncExternalStore: каждый компонент подписывается через селектор и рендерится, только если изменился выбранный кусок. Context — это внедрение зависимостей для редко меняющихся значений, а не state-менеджер (библиотека управления состоянием)."},{"q":"Стриминговый чат","t":"Ключевое наблюдение: переписка только дописывается, и меняется только последнее сообщение. Поэтому я храню сообщения как массив объектов со стабильными id, а во время стриминга (потоковой выдачи ответа) заменяю только объект последнего сообщения, сохраняя ссылки на все остальные. Каждая строка — memo-компонент с key по id сообщения, который получает объект сообщения как prop. Старые строки видят ту же ссылку и пропускают рендер, перерендеривается только стримящаяся строка на каждый кусок ответа. Дорогое в строке — обычно парсинг markdown и подсветка синтаксиса, поэтому это остаётся внутри мемоизированной строки. Токены могут приходить чаще, чем кадры, поэтому я копирую куски в ref и сбрасываю в state раз за кадр анимации, а не на каждый токен. Если диалоги дорастают до сотен длинных сообщений, я делаю virtualization (виртуализацию), например через TanStack Virtual, и рендерю только то, что в видимой области, плюс небольшой запас. Цена в том, что строки разной высоты нужно измерять, а ещё надо отдельно решать прилипание скролла к низу и поиск по странице, который ломается, когда строк нет в DOM."}],"kill":"<b>«Оберну всё в useMemo и useCallback на всякий случай»</b> — каждый стоит сравнения и памяти и ничего не даёт, если вычисление не дорогое и результат не идёт в memo-компонент или в зависимости хука."},
 en:{"topic":"Performance","qs":["A React screen feels slow. Where do you start, and what do memo, useMemo and useCallback actually buy you?","We put user, theme and cart in one Context, and the whole app re-renders on every cart change. Why, and how do you fix it?","Design the rendering for a long AI chat transcript where the last message streams in token by token."],"a":[{"q":"Measure first","t":"I measure before I touch anything. The React DevTools Profiler records each commit as a flame graph, shows how long every component took, and with the option to record why each component rendered, it tells me whether it was a state change, a props change or the parent. Often the culprit is a big component re-rendering on every keystroke, or one expensive computation, not React itself. memo lets a component skip rendering when its props are shallow-equal to last time. useMemo caches a computed value and useCallback caches a function, both keyed on deps. They cost a comparison and memory on every render, and they only work together. memo on a child is useless if I pass it a new object or an inline arrow every render, because the shallow compare fails. That stable-props requirement is where hand-written memoization quietly breaks. Today I'd lean on React Compiler, which hit 1.0 in October 2025. It's a Babel plugin that memoizes components and values automatically at build time. It works best with React 19 and supports 17 and 18 through react-compiler-runtime, but only if the code follows the rules of React."},{"q":"Context pitfall","t":"Every consumer of a context re-renders when the provider's value changes by Object.is, and memo on the consumer doesn't stop it. Two things usually go wrong. The provider builds value as a new object literal on every render, so even an unrelated parent render ripples to all consumers. And one context carries unrelated data, so a cart change re-renders everything that only reads the theme. The fixes, cheapest first. Memoize the value with useMemo, keyed on the actual fields. Split contexts by how often they change, theme and user separately from cart, and often split state from dispatch too, since setters are stable. When many components read small slices of fast-changing state, I move it to a store with selectors. Zustand is built on useSyncExternalStore: each component subscribes with a selector and re-renders only if its selected slice changes. Context is dependency injection for rarely-changing values. It isn't a state manager."},{"q":"Streaming transcript","t":"The key observation is that the transcript is append-only and only the last message changes. So I keep messages as an array of objects with stable ids, and while streaming I replace only the last message object and keep all the others by reference. Each row is a memo component keyed by message id, receiving the message object as a prop. Old rows see the same reference and skip rendering, so only the streaming row re-renders per chunk. The expensive part of a row is usually markdown parsing and syntax highlighting, so that stays inside the memoized row. Tokens can arrive faster than frames, so I buffer chunks in a ref and flush to state once per animation frame, not once per token. If conversations grow to hundreds of long messages, I add virtualization with something like TanStack Virtual, rendering only what's in the viewport plus some overscan. The trade-off is that variable-height rows need measuring, and I have to handle stick-to-bottom scrolling and find-in-page, which breaks when rows aren't in the DOM."}],"kill":"<b>\"I wrap everything in useMemo and useCallback to be safe\"</b> — each one costs a comparison and memory, and buys nothing unless the calculation is genuinely expensive or the result feeds a memo child or a hook dependency."}},

{n:42,tag:"Frontend core · React",sec:"react",core:[57],
 ru:{"topic":"Конкурентный рендеринг, Suspense и Server Components","qs":["Поле поиска фильтрует список из 10 000 строк, и ввод лагает. useTransition или useDeferredValue — и почему?","Страница с вложенными Suspense грузится лесенкой. Что происходит и как это исправить?","Во время миграции на App Router как вы объясняли команде разницу между SSR и Server Components, и где ставить 'use client'?"],"a":[{"q":"Transition или deferred","t":"Оба механизма делают под капотом одно и то же: помечают часть рендера как несрочную, чтобы React рендерил её в фоне и выбрасывал эту работу, если пришло более срочное обновление. Нажатие клавиши остаётся срочным — поле ввода должно управляться обычным state, и в документации React прямо сказано, что text input через transition (несрочное обновление) контролировать нельзя. Разница в том, кому принадлежит обновление. Если setState для тяжёлой части мой, я оборачиваю его в startTransition: setQuery остаётся срочным, setFilter уходит внутрь transition, и я получаю isPending, чтобы приглушить список. Если я получаю только значение, например через props, или сеттер (функция обновления) живёт в библиотеке, беру useDeferredValue(query) и отдаю отложенное значение списку. В обоих случаях медленный список должен быть обёрнут в memo, иначе он перерисовывается на каждое нажатие и выигрыша нет. В отличие от debounce (отложенного вызова) тут нет фиксированной задержки, всё подстраивается под устройство, но работы меньше не становится. Если один рендер сам по себе занимает 200 мс, я сначала делаю виртуализацию списка."},{"q":"Водопад Suspense","t":"Suspense boundary (граница ожидания) ловит любой компонент внутри, который приостановился, то есть ждёт данные через use() или библиотеку с поддержкой Suspense, либо ждёт lazy-код, и показывает ближайший fallback (заглушку), пока всё внутри не будет готово. Лесенка возникает из fetch-on-render (загрузки во время рендера): родитель рендерится, начинает свой запрос и приостанавливается; только когда запрос разрешился, дети рендерятся и начинают свои. Это и есть водопад. Три уровня — три последовательных round trip (сетевых круга). Лечится это render-as-you-fetch (рендером параллельно с загрузкой), или предзагрузкой: все запросы стартуют до или в начале рендера, в loader маршрута (функции загрузки данных роутера), в обработчике навигации или в Server Component. Вниз передаются промисы, дети читают их через use(), и всё грузится параллельно. Где ставить границы — это дизайнерское решение: одна граница на смысловую область, а не на каждый компонент, иначе страница выскакивает кусками. И Suspense не видит данные, загруженные в useEffect, это просто локальное состояние загрузки. Промис тоже должен кешироваться: новый промис на каждый рендер даёт бесконечный fallback."},{"q":"RSC и SSR","t":"Они решают разные задачи и работают вместе. SSR (серверный рендеринг) выполняет компоненты на сервере, чтобы получить HTML для первой отрисовки, но потом код этих компонентов всё равно едет в браузер и проходит hydration (оживление готового HTML обработчиками), так что каждый компонент стоит JavaScript. Server Components выполняются только на сервере и никогда не гидрируются. Их результат — сериализованный RSC payload (поток описания дерева), который React на клиенте вливает в дерево. Их код и зависимости не попадают в бандл (итоговый JS для браузера), и они могут читать базу напрямую. 'use client' помечает модуль как вход в клиентский граф: этот компонент и всё, что он импортирует, становится клиентским кодом. Пропсы через эту границу должны быть сериализуемыми: примитивы, обычные объекты, Date, Map, JSX, даже промисы, но не обычные функции и не экземпляры классов. Единственные разрешённые функции — Server Functions с 'use server', на этом и работают Server Actions. При миграции на App Router в Dats.Team правило, которое я продвигал, — держать 'use client' в листьях дерева. А при streaming (потоковой отдаче) loading.js это просто Suspense boundary: оболочка уходит сразу, медленные части догружаются потоком."}],"kill":"<b>«Server Components — это просто SSR»</b>: SSR всё равно гидрирует и отправляет JS компонента, а Server Components не гидрируются и присылают сериализованный payload. И <b>передать onClick из Server Component</b> нельзя: обычные функции не сериализуются."},
 en:{"topic":"Concurrent rendering, Suspense and Server Components","qs":["A search box filters a 10,000-row list and typing feels laggy. Would you reach for useTransition or useDeferredValue, and why?","A page with nested Suspense boundaries loads in a staircase. What's going on and how do you fix it?","During your App Router migration, how did you explain the difference between SSR and Server Components to the team, and where does 'use client' go?"],"a":[{"q":"Transition vs deferred","t":"Under the hood they do the same thing: they mark some rendering as non-urgent, so React can render it in the background and throw that work away if a more urgent update arrives. The keystroke stays urgent — the input has to be driven by normal state, and the React docs say explicitly you can't control a text input through a transition. The difference is who owns the update. If I own the setState for the expensive part, I wrap it in startTransition: setQuery stays urgent, setFilter goes inside the transition, and I get isPending to dim the list. If I only receive the value, say as a prop, or the setter lives in a library, I use useDeferredValue(query) and pass the deferred value to the list. Either way the slow list has to be wrapped in memo, otherwise it re-renders on every keystroke anyway and nothing is gained. Compared to debouncing there's no fixed delay, it adapts to the device, but it doesn't reduce the work. If a single render takes 200 milliseconds, I virtualize the list first."},{"q":"Suspense waterfall","t":"A Suspense boundary catches any component inside it that suspends, meaning it's waiting on data through use() or a Suspense-enabled library, or on lazy-loaded code, and shows the nearest fallback until everything inside is ready. The staircase comes from fetch-on-render: the parent renders, starts its fetch and suspends, and only when that resolves do the children render and start their own fetches. That's the waterfall. Three levels means three round trips back to back. The fix is render-as-you-fetch, or preloading: start all the requests before or as rendering begins, in the route loader, in the navigation handler, or in a Server Component. Then pass promises down, children read them with use(), and everything loads in parallel. Where I put boundaries is a design call: one per meaningful region, not one per component, otherwise the page pops in piece by piece. Also, Suspense doesn't see data fetched in useEffect, that's just local loading state. And the promise has to be cached, because a new promise every render means an endless fallback."},{"q":"RSC vs SSR","t":"They solve different problems and they stack. SSR runs components on the server to produce HTML for the first paint, but that component code still ships to the browser and hydrates, so every component still costs JavaScript. Server Components run only on the server and never hydrate. Their output is a serialized RSC payload, which React on the client merges into the tree. Their code and dependencies never reach the bundle, and they can read the database directly. 'use client' marks a module as the entry into the client graph: that component and everything it imports becomes client code. Props crossing that boundary must be serializable: primitives, plain objects, Dates, Maps, JSX, even promises, but not regular functions or class instances. The only functions allowed are Server Functions marked 'use server', which is how Server Actions work. In the App Router migration at Dats.Team, the rule I pushed was to keep 'use client' at the leaves. And with streaming, loading.js is just a Suspense boundary, so the shell flushes right away and slow parts stream in."}],"kill":"<b>\"Server Components are just SSR\"</b> — SSR still hydrates and ships the component's JS; Server Components never hydrate and send a serialized payload. And <b>passing an onClick from a Server Component</b> fails because regular functions don't serialize."}},

{n:43,tag:"Frontend core · React",sec:"react",core:[58],
 ru:{"topic":"React 19: Actions и формы","qs":["Что такое Action в React 19 и что дают useActionState, useFormStatus и use() по сравнению с обычным onSubmit?","Как работает useOptimistic и зачем списку сообщений нужна форма с reducer?","Расскажите, как бы вы сделали отправку сообщения в чате: оптимистичное сообщение пользователя, потоковый ответ, кнопка Stop и откат при ошибке."],"a":[{"q":"Actions и хуки","t":"Action (действие) — это функция, синхронная или асинхронная, которая выполняется внутри transition (несрочного обновления): её передают в startTransition или в проп (свойство компонента) вроде action у формы, и тогда React оборачивает её сам. React отслеживает pending-состояние (ожидание), не блокирует ввод и после успешного action формы сбрасывает неконтролируемые поля. useActionState превращает action в reducer (функцию «старое состояние плюс событие даёт новое»): она получает предыдущее состояние и payload (полезную нагрузку), для формы это FormData, и возвращает следующее состояние. Я получаю state, функцию dispatch и isPending. Вызовы встают в очередь и выполняются последовательно, так что один медленный запрос задерживает следующий. useFormStatus читает pending, data и method родительской формы. Ловушка в том, что он работает только в компоненте, отрисованном внутри формы, а не в том, который форму рендерит, поэтому кнопка отправки становится отдельным компонентом. use() читает промис или контекст, его можно вызывать в условии, и он приостанавливает рендер до разрешения промиса, но промис должен быть закеширован или прийти из Server Component. После 19.0 в 19.2 добавили Activity и useEffectEvent, а в 19.3 ViewTransition стал стабильным."},{"q":"useOptimistic","t":"useOptimistic принимает реальное значение и необязательный reducer (функцию пересчёта состояния) и возвращает оптимистичное значение и сеттер (функцию обновления). Пока action в процессе, React показывает оптимистичное значение. Когда action завершился и реальный state обновился, оптимистичный слой снимается и видно реальное значение. Это же бесплатно даёт откат при ошибке: если action упал и реальный state не изменился, оптимистичный элемент просто исчезает. Без reducer сеттер заменяет значение целиком, для переключателя лайка этого хватает. Для списка сообщений нужен reducer, например (messages, newMessage) => [...messages, {...newMessage, sending: true}], потому что две быстрые отправки должны обе добавиться, а не перезаписать друг друга. Сеттер надо вызывать внутри action или startTransition. Снаружи React выдаёт предупреждение, и оптимистичное состояние мигнёт и сразу откатится. Чего он не делает — не показывает ошибку. Состояние «не отправлено» или toast (всплывающее уведомление) я рисую сам, иначе сообщение молча пропадает."},{"q":"Отправка в чате","t":"Подтверждённые сообщения я держу в реальном state, а сообщение пользователя пускаю через useOptimistic, так что внутри action оно появляется мгновенно. Потом создаю AbortController и вызываю fetch с его signal. Как только сервер принял запрос, я фиксирую сообщение пользователя в реальном state внутри startTransition и добавляю пустой placeholder (заготовку) ответа ассистента. Это обновление попадает в тот же рендер, в котором исчезает оптимистичная копия, так что ничего не мигает и не задваивается. Но reducer у меня всё равно пропускает id, которые уже есть в реальном state: вдруг базовый список изменится извне, пока action ещё идёт. Ответ не оптимистичный, это настоящие потоковые данные, поэтому я наращиваю заготовку кусок за куском, собирая чанки (фрагменты потока) в пачку на каждый animation frame (кадр отрисовки), а не на каждый токен. Кнопка Stop вызывает abort. На сервере abort тоже должен отменять вызов LLM, иначе я продолжаю платить за токены, которые никто не читает. На клиенте AbortError для меня нормальный исход, частичный текст остаётся. Если запрос упал до первых токенов, сообщение пользователя так и не было зафиксировано, поэтому оптимистичное откатывается само, а я возвращаю черновик в поле ввода с ошибкой и кнопкой повтора. Поток, оборвавшийся на середине, я оставляю с пометкой об ошибке, а не удаляю то, что пользователь уже прочитал."}],"kill":"<b>«Вызову useFormStatus прямо в компоненте с формой»</b>: он читает только родительскую форму, поэтому должен жить в дочернем компоненте, например в кнопке. И <b>вызов setOptimistic вне action</b> даёт значение, которое мигает и откатывается."},
 en:{"topic":"React 19: Actions and forms","qs":["What is an Action in React 19, and what do useActionState, useFormStatus and use() give you over a plain onSubmit handler?","How does useOptimistic work, and why does a message list need the reducer form?","Walk me through a chat send flow: optimistic user message, streaming reply, a Stop button, and rollback on error."],"a":[{"q":"Actions and hooks","t":"An Action is a function, sync or async, that runs inside a transition — passed to startTransition, or to a prop like the form's action, which React wraps for me. React tracks the pending state, keeps input responsive, and resets uncontrolled fields after a successful form action. useActionState turns an action into a reducer: it receives the previous state and the payload, which is FormData for a form, and returns the next state. I get back the state, a dispatch function and isPending. Calls queue and run sequentially, so one slow request delays the next. useFormStatus reads pending, data and method of the parent form. The trap is that it only works in a component rendered inside the form, not in the one that renders it, so the submit button becomes its own component. use() reads a promise or context, can be called conditionally, and suspends until the promise resolves, but the promise must be cached or come from a Server Component. After 19.0, 19.2 added Activity and useEffectEvent, and 19.3 made ViewTransition stable."},{"q":"useOptimistic","t":"useOptimistic takes the real value and an optional reducer, and returns an optimistic value plus a setter. While an action is pending, React shows the optimistic value. When the action finishes and the real state updates, the optimistic layer is dropped and the real value shows through. That also gives me rollback on failure for free: if the action throws and the real state never changes, the optimistic item just disappears. Without a reducer the setter replaces the whole value, which is fine for a like toggle. For a message list I need the reducer form, like (messages, newMessage) => [...messages, {...newMessage, sending: true}], because two quick sends must each append instead of overwriting each other. The setter has to be called inside an action or startTransition. Outside one, React warns and the optimistic state flashes and reverts immediately. What it doesn't do is error UI. I still render a failed state or a toast myself, otherwise the message silently vanishes."},{"q":"Chat send flow","t":"I keep confirmed messages in real state and send the user's message through useOptimistic, so inside the action it appears instantly. Then I create an AbortController and call fetch with its signal. Once the server accepts, I commit the user message to real state inside startTransition and append an empty assistant placeholder. That update lands in the same render where the optimistic copy is dropped, so nothing flickers or doubles. I still have the reducer skip ids already in real state, in case the base list changes from elsewhere while the action is pending. The reply is real streaming data, so I grow the placeholder chunk by chunk, batched per animation frame rather than per token. The Stop button calls abort. On the server the abort has to cancel the upstream LLM call too, or I keep paying for tokens nobody reads. On the client I treat AbortError as a normal outcome and keep the partial text. If the request fails before any tokens arrive, the user message was never committed, so the optimistic one rolls back on its own, and I put the draft back in the input with an error and a retry. A stream that dies halfway I keep with a failed marker rather than deleting what the user already read."}],"kill":"<b>\"I'll call useFormStatus right in the form component\"</b> — it only reads a parent form, so it has to live in a child like the submit button. And <b>calling setOptimistic outside an action</b> makes the value flash and revert."}},

{n:44,tag:"Frontend core · React",sec:"react",core:[59],
 ru:{"topic":"Состояние и загрузка данных","qs":["Как вы решаете, где живёт кусок состояния: локально, в родителе, глобально, на сервере или в URL?","В TanStack Query чем staleTime отличается от gcTime, и как безопасно сделать оптимистичное обновление?","Context, Zustand или Redux Toolkit — какое у вас реальное правило выбора?"],"a":[{"q":"Где живёт state","t":"Я начинаю с того, кто владеет данными. Если их использует один компонент, например открыт ли dropdown (выпадающий список), они остаются локальными в useState. Если они нужны двум соседям, я поднимаю их к ближайшему общему родителю и передаю вниз. Глобальный клиентский state — для того, что действительно нужно всему приложению и принадлежит сессии в браузере: тема, неотправленный черновик. Server state (серверное состояние) — отдельная категория: владеет им сервер, а у меня лишь кеш, который устаревает, разделяется несколькими компонентами и требует refetch (повторной загрузки), дедупликации и инвалидации (пометки кеша устаревшим). Копировать загруженные данные в useState или глобальный стор (хранилище) — классическая ошибка: появляются два источника правды и собственные баги инвалидации. Пятое место, о котором забывают, — URL. Фильтры, сортировка, активная вкладка и пагинация живут в search params (параметрах запроса в адресе). Тогда вид переживает перезагрузку, работает кнопка «назад», и ссылку можно отправить коллеге или приложить к баг-репорту. В чат-продукте я бы по той же причине держал id разговора в URL."},{"q":"staleTime и gcTime","t":"Оба — таймеры на каждый query key (ключ запроса), и измеряют они разное. staleTime — сколько данные считаются свежими. Пока они свежие, монтирование нового компонента или возврат фокуса в окно не вызывает refetch (повторный запрос). По умолчанию он ноль, то есть данные сразу устаревшие и перезапрашиваются на этих триггерах (событиях-поводах), но пока идёт запрос, старые данные всё равно показываются. gcTime, до v5 он назывался cacheTime, задаёт, сколько неиспользуемый запрос живёт в кеше после того, как отмонтировался последний подписчик, по умолчанию пять минут. Query key — это идентичность записи в кеше, поэтому всё, от чего зависит запрос, например фильтры, кладётся в ключ. Два компонента с одним ключом делят один запрос — это дедупликация. После мутации (изменения данных на сервере) я инвалидирую затронутые ключи, чтобы они перезапросились. Для оптимистичного обновления схема такая: в onMutate отменяю текущие запросы по ключу, чтобы устаревший refetch меня не перезаписал, делаю снимок текущих данных, пишу оптимистичную версию через setQueryData и возвращаю снимок. В onError восстанавливаю снимок, а в onSettled инвалидирую ключ, чтобы последнее слово было за сервером."},{"q":"Context или стор","t":"Context — это механизм внедрения зависимостей, а не менеджер состояния. Его хватает, когда значение меняется редко: тема, текущий пользователь, локаль, клиент feature flags (флагов функций). Проблема в том, что при смене value у провайдера (компонента-поставщика) перерисовываются все потребители, а селекторов нет, так что часто меняющийся объект в Context перерисовывает полдерева. Моё правило: меняется редко — Context. Если это клиентское состояние, которое меняется часто и из которого многие компоненты читают свои кусочки, например редактор или поле ввода чата с вложениями, я беру Zustand. Там компоненты подписываются через selector (функцию выборки) и перерисовываются, только когда меняется их кусок, и почти без boilerplate (шаблонного кода). Redux Toolkit я беру, когда команда большая и хочет навязанную структуру: явные actions, middleware (промежуточные обработчики), time-travel (пошаговый откат состояний) в devtools и журнал событий, изменивших состояние, что помогает отлаживать сложные сценарии. А серверные данные в любом случае идут в TanStack Query или RTK Query, а не в эти хранилища. Ловушка, за которой я слежу, — сначала выбрать глобальный стор, а потом сложить туда серверные данные."}],"kill":"<b>«staleTime — это сколько данные хранятся в кеше»</b>: это gcTime, а staleTime решает только, когда запускать refetch. И <b>копирование данных запроса в useState</b> создаёт второй источник правды."},
 en:{"topic":"State and data fetching","qs":["How do you decide where a piece of state lives: local, lifted, global, server, or the URL?","In TanStack Query, what's the difference between staleTime and gcTime, and how do you do an optimistic update safely?","Context, Zustand or Redux Toolkit: what's your actual decision rule?"],"a":[{"q":"Where state lives","t":"I start from who owns the data. If only one component uses it, like whether a dropdown is open, it stays local in useState. If two siblings need it, I lift it to the nearest common parent and pass it down. Global client state is for things that are truly app-wide and owned by the browser session, like the theme or an unsent draft. Server state is a different category: the server owns it, and what I hold is a cache that goes stale, is shared by several components, and needs refetching, deduping and invalidation. Copying fetched data into useState or a global store is the classic mistake, because now I have two sources of truth and my own invalidation bugs. The fifth place people forget is the URL. Filters, sort, the active tab and pagination belong in search params. Then the view survives a reload, the back button works, and I can paste the link to a colleague or into a bug report. In a chat product I'd keep the conversation id in the URL for the same reason."},{"q":"staleTime vs gcTime","t":"Both are timers per query key, and they measure different things. staleTime is how long data counts as fresh. While it's fresh, a new component mounting or the window regaining focus won't trigger a refetch. The default is zero, so data is stale immediately and gets refetched on those triggers, but the stale data is still shown while the refetch runs. gcTime, which was called cacheTime before v5, is how long an unused query stays in the cache after its last observer unmounts, five minutes by default. The query key is the cache identity, so everything the fetch depends on, like filters, goes into the key. Two components with the same key share one request, that's deduping. After a mutation I invalidate the affected keys so they refetch. For an optimistic update the pattern is: in onMutate, cancel in-flight queries for that key so a stale refetch doesn't overwrite me, snapshot the current data, write the optimistic version with setQueryData, and return the snapshot. In onError I restore the snapshot, and in onSettled I invalidate the key so the server has the final word."},{"q":"Context vs stores","t":"Context is a dependency injection mechanism, not a state manager. It's enough when the value changes rarely: theme, current user, locale, a feature-flag client. The problem is that every consumer re-renders when the provider's value changes, and there are no selectors, so a frequently changing object in Context re-renders half the tree. My rule: if it changes rarely, Context. If it's client state that changes often and many components read their own slice of it, like an editor or a chat composer with attachments, I use Zustand. Components subscribe with a selector and only re-render when their slice changes, with almost no boilerplate. I reach for Redux Toolkit when the team is large and wants enforced structure: explicit actions, middleware, time-travel devtools, and a log of every event that changed state, which helps when debugging complex flows. And server data goes to TanStack Query or RTK Query in every case, not into any of these stores. The trap I watch for is picking a global store first and then stuffing server data into it."}],"kill":"<b>\"staleTime is how long data stays in the cache\"</b> — that's gcTime; staleTime only decides when a refetch is triggered. And <b>copying query data into useState</b> creates a second source of truth."}},

{n:45,tag:"Frontend core · Browser",sec:"web",core:[60],
 ru:{"topic":"Конвейер рендеринга браузера","qs":["Расскажи, что делает браузер с момента получения байтов HTML до пикселей на экране. Какие изменения дорогие, а какие дешёвые?","Анимация дёргается, а в профайлере в каждом кадре фиолетовые блоки layout. Что происходит и как это чинить?","HTML пришёл быстро, но страница две секунды белая. Какие ресурсы могут блокировать рендер и чем отличаются defer, async и type=module?"],"a":[{"q":"Конвейер","t":"HTML-парсер превращает байты в токены и по ходу строит DOM (дерево узлов документа), а preload scanner (упреждающий сканер) бежит вперёд и заранее запускает загрузку найденных ресурсов. Параллельно CSS разбирается в CSSOM (дерево правил стилей). Дальше конвейер: style (вычисление стилей), где браузер сопоставляет селекторы и считает итоговые стили каждого элемента. Потом layout (расчёт геометрии): размеры и позиции блоков. Потом paint (отрисовка): запись команд рисования по слоям. И composite (сборка слоёв): слои растеризуются и собираются в кадр, в основном на GPU (графическом процессоре). На практике важно одно: каждый этап кормит следующий, поэтому изменение на раннем этапе оплачивает всё, что после него. Поменял width, и платишь за layout, paint и composite. Поменял цвет, и layout пропускается. Поменял transform или opacity у элемента на своём слое, и часто можно сразу в composite, мимо главного потока. Самая дешёвая работа та, которой нет. Это и делает content-visibility: auto: секции за экраном не проходят layout и paint, пока не приблизятся к viewport (видимой области). Я ставлю рядом contain-intrinsic-size, чтобы полоса прокрутки не прыгала. Это Baseline (поддержано всеми основными браузерами) с 2024 года."},{"q":"Reflow и thrashing","t":"Фиолетовое в панели Performance это style и layout (расчёт геометрии), и если оно повторяется много раз внутри одного кадра, почти всегда это layout thrashing (пробуксовка раскладки). Обычно браузер ленивый: когда я пишу в DOM, он просто помечает layout как грязный и пересчитывает один раз перед кадром. Но если сразу после записи я читаю геометрию, например offsetHeight или getBoundingClientRect, ему нужно отдать правильное число прямо сейчас, и он делает синхронный reflow (принудительный пересчёт геометрии). В цикле чтение, запись, чтение, запись это полный layout на каждой итерации. Лечится батчингом (группировкой): сначала все чтения, потом все записи, а записи я планирую через requestAnimationFrame, чтобы они легли прямо перед кадром. Саму анимацию я делаю на transform и opacity вместо top, left или width, потому что их может обработать compositor (поток сборки слоёв) без layout и paint. will-change: transform заранее выносит элемент на свой слой, но каждый слой стоит памяти GPU (видеокарты). Поэтому я ставлю его только тем немногим элементам, которые реально анимируются, а не всему подряд."},{"q":"Блокировка рендера","t":"По умолчанию CSS в head блокирует рендер: браузер не рисует, пока нет CSSOM (дерева стилей), иначе была бы вспышка нестилизованного контента. Обычный script без атрибутов блокирует парсер: разбор HTML останавливается, скрипт скачивается и выполняется. А если выше висит незагруженный стиль, скрипт ещё и ждёт его, потому что может читать стили. defer качается параллельно и выполняется после окончания парсинга, строго в порядке документа, до DOMContentLoaded. async качается параллельно и выполняется сразу, как пришёл, в любом порядке, и может прервать парсинг. Это нормально для независимых вещей вроде аналитики и опасно для всего, у чего есть зависимости. type=module по умолчанию ведёт себя как defer, а с async выполняется, как только готов весь его граф зависимостей. Так что для белого экрана мой план такой: заинлайнить (встроить прямо в HTML) небольшой критический CSS, держать основной стиль компактным, перевести все скрипты на defer или module и проверить, что в head ничего не тянется с медленного стороннего домена."}],"kill":"<b>«transform быстрее, потому что он на GPU»</b> — настоящая причина в том, что он пропускает layout и paint и может идти на compositor. А <b>will-change на всём подряд</b> не ускоряет, а съедает память видеокарты."},
 en:{"topic":"The browser rendering pipeline","qs":["Walk me through what the browser does from receiving HTML bytes to pixels on the screen. Which changes are expensive and which are cheap?","An animation stutters and the profiler shows purple layout blocks in every frame. What's going on and how do you fix it?","The HTML arrives fast but the page stays blank for two seconds. What could be blocking render, and how do defer, async and type=module differ?"],"a":[{"q":"Pipeline","t":"The HTML parser turns bytes into tokens and builds the DOM incrementally, while a preload scanner runs ahead and starts fetching resources it spots. In parallel, CSS is parsed into the CSSOM. Then the pipeline runs. Style: the browser matches selectors and computes final styles for every element. Layout: it calculates geometry, the size and position of every box. Paint: it records draw commands into layers. Composite: those layers are rasterized and assembled into the frame, largely on the GPU. What matters in practice is that each stage feeds the next, so a change at an early stage pays for everything after it. Change a width and you pay for layout, paint and composite. Change a color and layout is skipped. Change transform or opacity on an element with its own layer and you can often go straight to composite, off the main thread. The cheapest work is work you skip, which is what content-visibility: auto does. Off-screen sections skip layout and paint until they get close to the viewport. I pair it with contain-intrinsic-size so the scrollbar doesn't jump, and it's been Baseline since 2024."},{"q":"Reflow and thrashing","t":"Purple in the Performance panel is style and layout, and if it repeats many times inside one frame, that's almost always layout thrashing. Normally the browser is lazy. When I write to the DOM, it just marks layout as dirty and recalculates once before the next frame. But if I then read geometry, like offsetHeight or getBoundingClientRect, it has to give me a correct number right now, so it runs a synchronous reflow. Put that in a loop, read, write, read, write, and I force a full layout on every iteration. The fix is batching: do all the reads first, then all the writes, and schedule the writes in requestAnimationFrame so they land right before the frame. For the animation itself, I'd animate transform and opacity instead of top, left or width, because the compositor can handle those without layout or paint. will-change: transform promotes the element to its own layer ahead of time, but every layer costs GPU memory. So I put it on the few elements that actually animate, not on everything."},{"q":"Render-blocking","t":"By default, CSS in the head is render-blocking. The browser won't paint until it has the CSSOM, otherwise you'd get a flash of unstyled content. A classic script tag with no attributes is parser-blocking: parsing stops while the script downloads and runs. And if there's a pending stylesheet above it, the script also waits for that CSS, because it might read styles. defer downloads in parallel and executes after parsing finishes, in document order, before DOMContentLoaded. async downloads in parallel and executes as soon as it arrives, in any order, and it can interrupt parsing. That's fine for independent things like analytics and dangerous for anything with dependencies. type=module is deferred by default, and with async it runs as soon as its dependency graph is ready. So my plan for a blank page is to inline the small critical CSS, keep the main stylesheet lean, move every script to defer or module, and check that nothing in the head is fetched from a slow third-party origin."}],"kill":"<b>\"transform is faster because it runs on the GPU\"</b> — the real reason is that it skips layout and paint and can run on the compositor. And <b>will-change on everything</b> doesn't speed anything up, it burns GPU memory."}},

{n:46,tag:"Frontend core · Browser",sec:"web",core:[61],
 ru:{"topic":"Core Web Vitals: LCP, INP, CLS","qs":["Какие три Core Web Vitals, что каждая реально измеряет и что считается хорошим результатом?","Lighthouse показывает 98, а Search Console говорит, что INP плохой. Как оба могут быть правы?","Возьми каждую метрику по очереди: что ты сделаешь первым делом, если она красная? Допустим, это страница чата со стримингом ответа LLM."],"a":[{"q":"Три метрики","t":"LCP (Largest Contentful Paint, отрисовка самого крупного элемента) это момент, когда во viewport (видимой области) отрисовался самый большой элемент, картинка или блок текста. Для пользователя это ощущение «страница загрузилась». Хорошо это 2,5 секунды или меньше. INP (Interaction to Next Paint, задержка до следующего кадра) измеряет отзывчивость. Для кликов, тапов и нажатий клавиш это время от ввода до отрисовки следующего кадра, и оно состоит из трёх фаз: input delay (ожидание занятого главного потока), processing (работа обработчиков) и presentation delay (рендеринг до показа кадра). Берётся примерно худшее взаимодействие за визит, хорошо это 200 миллисекунд или меньше. CLS (Cumulative Layout Shift, суммарный сдвиг макета) измеряет визуальную стабильность: неожиданные сдвиги оцениваются по тому, какая доля экрана сдвинулась и насколько, группируются во всплески, и берётся самый большой. Хорошо это 0,1 или меньше. Что часто упускают: «хорошо» значит, что порог проходит 75-й перцентиль реальных загрузок, отдельно для мобильных и десктопа. И INP заменил FID в марте 2024 года. FID мерил только задержку первого ввода, его было легко пройти, пока приложение тормозило."},{"q":"Поле и лаборатория","t":"Потому что они меряют разное. Lighthouse это lab data (лабораторные данные): одна симулированная загрузка на замедленном профиле, без живого пользователя и без взаимодействий. Поэтому обычный отчёт в режиме navigation, тот, что даёт оценку, INP измерить не может и показывает Total Blocking Time как приближение. В лаборатории INP записывают только режим timespan в Lighthouse или панель Performance в DevTools, и только для взаимодействий, которые я выполняю сам. Search Console берёт field data (полевые данные) из CrUX (Chrome User Experience Report, отчёт по реальным пользователям Chrome): реальные люди, скользящее окно 28 дней, 75-й перцентиль. Поле видит то, чего лаборатория не увидит никогда: медленные Android-телефоны среднего класса, клики во время гидрации (оживления серверного HTML), длинные сессии, где список разросся до тысяч строк, сторонние скрипты, которые грузятся после согласия на cookies. Мой подход: полевые данные решают, что сломано, а лабораторные инструменты помогают это отладить. Я добавляю библиотеку web-vitals для своего RUM (мониторинга реальных пользователей) и отправляю INP через её attribution-сборку (с атрибуцией причин), чтобы знать, какой элемент и какая фаза были медленными, а не только число. Потом воспроизвожу конкретное взаимодействие в DevTools с замедлением CPU."},{"q":"План починки","t":"Для LCP я сначала нахожу LCP-элемент и раскладываю время на части. Если большой TTFB (время до первого байта), проблема в сервере или кешировании. Если картинка начинает грузиться поздно, её не видно браузеру заранее. Я делаю её обычным img в HTML, никогда не ставлю ей lazy-загрузку, добавляю fetchpriority=high и делаю preload (упреждающую загрузку), если она указана только в CSS или JS. Для INP правило такое: меньше работы в обработчике и yield (уступить главный поток) перед тяжёлой частью, чтобы браузер успел отрисовать отклик. Длинные задачи я режу на куски через scheduler.yield там, где он есть. В Chrome и Firefox он есть, в Safari на момент проверки нет, так что нужен фолбэк (запасной вариант) на setTimeout. Для CLS я резервирую место: width и height или aspect-ratio у картинок, фиксированные слоты под встраивания и рекламу, font-display и подогнанные по размеру запасные шрифты, чтобы текст не прыгал при подмене шрифта. В стриминговом чате вылезает и то и другое. Парсить весь markdown на каждый токен убивает INP, поэтому я коплю токены до кадра и парсю инкрементально. И ничего не должно стоять в потоке под растущим сообщением, иначе его толкает вниз на каждом токене."}],"kill":"<b>«У нас Lighthouse 100, значит с Core Web Vitals всё хорошо»</b> — Google оценивает полевые данные на 75-м перцентиле, а оценка Lighthouse считается по загрузке без взаимодействий, так что <b>INP</b> в ней нет вообще."},
 en:{"topic":"Core Web Vitals: LCP, INP, CLS","qs":["What are the three Core Web Vitals, what does each one actually measure, and what counts as good?","Lighthouse gives us a 98, but Search Console says our INP is poor. How can both be true?","Take each vital in turn: what's the first thing you'd do if it's red? Say it's a chat page streaming an LLM response."],"a":[{"q":"The three metrics","t":"LCP, Largest Contentful Paint, is when the biggest image or text block in the viewport renders. It's the user's sense that the page has loaded, and good is 2.5 seconds or less. INP, Interaction to Next Paint, measures responsiveness. For clicks, taps and key presses, it's the time from the input to the next frame being painted, and it has three phases: input delay while the main thread is busy, processing time in the handlers, and presentation delay, the rendering work until the frame is shown. It reports roughly the worst interaction of the visit, and good is 200 milliseconds or less. CLS, Cumulative Layout Shift, measures visual stability. Unexpected shifts are scored by how much of the viewport moved and how far, grouped into bursts, and the largest burst is reported. Good is 0.1 or less. The detail people miss is that good means the 75th percentile of real page loads meets the threshold, split by mobile and desktop. Also, INP replaced FID in March 2024. FID only measured the input delay of the first interaction, so it was easy to pass while the app felt sluggish."},{"q":"Field vs lab","t":"Because they measure different things. Lighthouse is lab data: one simulated load on a throttled profile, with no real user and no interactions. So the standard navigation report, the one that gives the score, can't measure INP and reports Total Blocking Time as a proxy. In the lab, only Lighthouse timespan mode or the DevTools Performance panel record INP, and only for interactions I perform. Search Console uses field data from CrUX, the Chrome User Experience Report: real Chrome users, a rolling 28-day window, at the 75th percentile. The field sees things the lab never will. Slow mid-range Android phones, users clicking while hydration is still running, long sessions where a list grows to thousands of rows, third-party scripts that load after cookie consent. My rule is that field data decides what's broken and lab tools help me debug it. I'd add the web-vitals library for our own RUM, real user monitoring, and send INP with its attribution build, so I know which element and which phase was slow, not just the number. Then I reproduce that specific interaction in DevTools with CPU throttling."},{"q":"Fix playbook","t":"For LCP I find the LCP element first and break its time into parts. If TTFB is big, it's server or caching work. If the image starts loading late, the browser couldn't discover it early. So I make it a real img in the HTML, never lazy-load it, add fetchpriority=high, and preload it if it's only referenced from CSS or JS. For INP the rule is to do less work in the handler and yield before the heavy part, so the browser can paint feedback first. I break long tasks into chunks with scheduler.yield where it exists. Chrome and Firefox have it, Safari didn't last time I checked, so I fall back to setTimeout. For CLS I reserve space: width and height or aspect-ratio on images, fixed slots for embeds and ads, and font-display with size-adjusted fallback fonts so text doesn't move when the web font swaps in. A streaming chat hits both. Parsing the whole markdown on every token hurts INP, so I batch tokens per animation frame and parse incrementally. And nothing should sit in the flow below the growing message, or it gets shoved down with every token."}],"kill":"<b>\"Our Lighthouse score is 100, so our Core Web Vitals are fine\"</b> — Google judges field data at the 75th percentile, and the Lighthouse score comes from a load with no interactions, so it has no <b>INP</b> at all."}},

{n:47,tag:"Frontend core · Browser",sec:"web",core:[62],
 ru:{"topic":"Сеть и кеширование","qs":["Как ты настроишь кеш-заголовки для HTML и JS-бандлов в приложении на Next.js или Vite? И чем no-cache отличается от no-store?","Что на самом деле поменялось между HTTP/1.1, HTTP/2 и HTTP/3, и где тут resource hints вроде preload и preconnect?","После деплоя часть пользователей несколько дней видит старую версию приложения. Где может жить устаревшая копия?"],"a":[{"q":"Кеш-заголовки","t":"no-cache не значит «не кешировать». Он значит, что браузер может сохранить ответ, но обязан перепроверить его у сервера перед каждым использованием. no-store значит не сохранять нигде, это для чувствительных ответов. Перепроверка идёт через валидаторы. Сервер отдаёт ETag (отпечаток версии ответа), браузер хранит ответ и использует его, пока тот свежий по max-age. Когда ответ устарел, или при no-cache каждый раз, браузер шлёт If-None-Match с этим ETag. Если ничего не изменилось, сервер отвечает 304 Not Modified без тела. Это всё равно round trip (сетевой круг туда и обратно), но дешёвый. Для собранного приложения схема делится по типу файлов. У JS, CSS и шрифтов хеш содержимого в имени, поэтому по одному URL контент никогда не меняется. Им max-age=31536000, то есть год, плюс immutable, чтобы браузер не перепроверял даже при перезагрузке. Firefox и Safari его учитывают, Chrome игнорирует, но он и так не перепроверяет подресурсы при обычной перезагрузке. HTML получает no-cache, потому что это точка входа со ссылками на новые хеши. Если HTML закешировать надолго, пользователи так и будут ходить за старыми бандлами."},{"q":"Версии HTTP","t":"HTTP/1.1 обрабатывает один запрос за раз на соединение, поэтому браузер открывает около шести соединений на origin (источник), и отсюда росли склейка файлов и спрайты. HTTP/2 мультиплексирует (передаёт вперемешку) много потоков в одном TCP-соединении, и мелкие запросы стали дешёвыми. Но head-of-line blocking (блокировка очереди головным пакетом) просто уехала ниже: TCP отдаёт байты строго по порядку, и один потерянный пакет стопорит все потоки, пока его не перешлют. HTTP/3 работает поверх QUIC (транспорт поверх UDP), где каждый поток упорядочен независимо, и потеря бьёт только по своему потоку. Ещё QUIC совмещает транспортное и TLS-рукопожатие, что экономит round trip (сетевой круг) на новых соединениях, особенно на мобильных. Resource hints (подсказки браузеру о ресурсах) работают поверх этого. preconnect заранее открывает соединение с важным сторонним доменом. preload тянет то, что браузер нашёл бы поздно. fetchpriority меняет приоритет. modulepreload заранее качает и разбирает модуль. Они вредят при перебаре: десять preload конкурируют с реально критичным ресурсом, лишние preconnect тратят сокеты, а неиспользованный preload это чистая потеря, о которой Chrome предупреждает в консоли."},{"q":"Устаревшее приложение","t":"Есть три места. Первое: HTTP-кеш браузера, если HTML отдали с длинным max-age вместо no-cache. Второе: CDN (сеть пограничных серверов). Если HTML кешируется на edge (пограничном узле) с длинным s-maxage и мы не делаем purge (сброс кеша) при деплое, каждый посетитель получает старую точку входа. stale-while-revalidate тут полезен: он мгновенно отдаёт кешированную копию и обновляет её в фоне. Но это значит, что после каждого изменения кто-то гарантированно получит старую версию, так задумано. Третье и самое неприятное: service worker (фоновый скрипт-прокси). Это программируемый прокси между страницей и сетью. Он может заранее закешировать оболочку приложения, отдавать из кеша, работать офлайн. Но если он отдаёт HTML cache-first (сначала из кеша), новая версия приходит только на следующем визите. А новый воркер ждёт, пока закроются все вкладки со старым. Кривой воркер может намертво привязать пользователей к сломанной сборке. Поэтому HTML я отдаю network-first (сначала сеть), версионирую кеши, показываю «доступно обновление» и держу наготове воркер-выключатель. И старые чанки (куски бандла) с хешами держу на CDN какое-то время, иначе пользователи со старым HTML ловят 404 на ленивых роутах."}],"kill":"<b>«no-cache значит, что браузер не кеширует ответ»</b> — это no-store. no-cache сохраняет ответ и перепроверяет его перед каждым использованием, обычно дешёвым 304."},
 en:{"topic":"Networking and caching","qs":["How would you set cache headers for the HTML and the JS bundles of a Next.js or Vite app? And what's the difference between no-cache and no-store?","What actually changed between HTTP/1.1, HTTP/2 and HTTP/3, and where do resource hints like preload and preconnect fit in?","After a deploy, some users keep seeing the old version of the app for days. Where could the stale copy be living?"],"a":[{"q":"Cache headers","t":"no-cache doesn't mean don't cache. It means the browser may store the response but must revalidate it with the server before every use. no-store means never write it anywhere, which is what I'd use for sensitive responses. Revalidation works through validators. The server sends an ETag, and the browser stores the response and reuses it while it's fresh under max-age. Once it's stale, or on every use with no-cache, the browser sends If-None-Match with that ETag. If nothing changed, the server answers 304 Not Modified with no body. That's still a round trip, but a cheap one. For a built app, the pattern splits by file type. JS, CSS and fonts have a content hash in the filename, so a given URL never changes content. Those get max-age=31536000, a year, plus immutable, so the browser doesn't revalidate even on reload. Firefox and Safari honor it. Chrome ignores it, but it already skips revalidating subresources on a normal reload. The HTML gets no-cache, because it's the entry point that references the new hashes. If the HTML is cached for long, users keep loading old bundles."},{"q":"HTTP versions","t":"HTTP/1.1 handles one request at a time per connection, so browsers open about six connections per origin, which is why we used to concatenate files and build sprites. HTTP/2 multiplexes many streams over one TCP connection, so small requests got cheap. But head-of-line blocking just moved down a layer. TCP delivers bytes strictly in order, so one lost packet stalls every stream on the connection until it's retransmitted. HTTP/3 runs over QUIC, on top of UDP, where each stream is ordered independently, so a lost packet only stalls its own stream. QUIC also combines the transport and TLS handshakes, which saves a round trip on new connections, and that matters most on mobile. Resource hints sit on top of this. preconnect warms up a connection to a critical third-party origin. preload fetches something the browser would discover late. fetchpriority adjusts priority. modulepreload fetches and parses a module ahead of time. They backfire when overused. Ten preloads compete with the one resource that's actually critical, extra preconnects waste sockets, and an unused preload is pure waste, which Chrome warns about in the console."},{"q":"Stale app","t":"There are three places. First, the browser HTTP cache, if the HTML was served with a long max-age instead of no-cache. Second, the CDN. If HTML is cached at the edge with a long s-maxage and we don't purge on deploy, every visitor gets the old entry point. stale-while-revalidate is useful here, because it serves the cached copy instantly and refreshes it in the background. But it also means someone gets the old version after each change, by design. Third, and the nastiest, a service worker. It's a programmable proxy between the page and the network, so it can precache the app shell, serve from cache and work offline. But if it serves HTML cache-first, the new version only arrives on the next visit. And a new worker waits until every tab using the old one is closed. A buggy worker can pin users to a broken build. So I serve HTML network-first, version the caches, show an update-available prompt, and keep a kill-switch worker ready. I also keep old hashed chunks on the CDN for a while, or users on old HTML hit 404s on lazy-loaded routes."}],"kill":"<b>\"no-cache means the browser doesn't cache it\"</b> — that's no-store. no-cache stores the response and revalidates it before every use, usually with a cheap 304."}},

{n:48,tag:"Frontend core · Browser",sec:"web",core:[63],
 ru:{"topic":"Веб-безопасность для фронтендера","qs":["У нас React, он же всё экранирует. Значит, XSS нам не грозит? Где это ломается?","Мы рендерим ответы модели как markdown в чате. Что может пойти не так?","Где бы ты хранил auth-токен, и как сюда вписываются CSRF, SameSite и CORS?"],"a":[{"q":"XSS в React","t":"Не совсем. React экранирует текст в JSX-детях и значениях атрибутов, поэтому строка с тегом script отрисуется как обычные символы. Это закрывает классические виды XSS (межсайтового скриптинга): stored (хранимый), когда payload (вредоносная нагрузка) лежит в базе, reflected (отражённый), когда он возвращается из параметра URL в ответе, и DOM-based, когда мой же клиентский код переносит данные атакующего из location или postMessage в опасное место вроде innerHTML. Защита заканчивается на лазейках. dangerouslySetInnerHTML отдаёт сырой HTML парсеру. href из пользовательских данных может оказаться javascript:. React 19 блокирует этот буквальный случай, старые версии только предупреждали, а data: или фишинговый домен всё равно пройдут. Поэтому я пропускаю только http, https и mailto. Превратить markdown в HTML-строку и вставить её — та же дыра. Прямой innerHTML через ref обходит React полностью. Как страховку ставлю строгий CSP (политику безопасности контента): script-src с nonce (одноразовым случайным значением) на каждый запрос и 'strict-dynamic', чтобы скрипты, загруженные доверенным скриптом, тоже работали без списка хостов. Внедрённый инлайн-скрипт тогда не выполнится. Это ограничение ущерба, а не исправление, и в Next.js nonce заставляет рендерить страницы динамически."},{"q":"Вывод модели","t":"Я считаю вывод модели недоверенным вводом, как комментарий пользователя. Модель может повторить всё, что попало в её контекст: найденный документ, веб-страницу, результат инструмента. Так indirect prompt injection (непрямая инъекция инструкций через данные) превращается в XSS, если я рендерю HTML. По умолчанию я разбираю markdown в React-элементы с выключенным сырым HTML. react-markdown так и делает из коробки и вырезает опасные протоколы в ссылках. Если HTML действительно нужен, я конвертирую markdown в HTML и уже результат прогоняю через DOMPurify, никогда не наоборот. Менее очевидный риск — exfiltration (утечка данных наружу). Внедрённая инструкция может заставить модель вывести картинку, в URL которой зашиты данные из чата. Браузер загрузит её при рендере, без всякого клика. Поэтому я блокирую картинки с неизвестных хостов или проксирую их, показываю адрес ссылки, ставлю rel noopener noreferrer и подкрепляю это через img-src и connect-src в CSP. При стриминге я на каждом чанке (порции ответа) заново рендерю безопасное дерево из накопленного текста, а не дописываю сырые HTML-фрагменты."},{"q":"Токены и CSRF","t":"Я предпочитаю cookie с HttpOnly и Secure. JavaScript не может её прочитать, поэтому XSS может действовать от имени пользователя, пока вкладка открыта, но не может украсть токен и использовать его с другой машины. Токен в localStorage в одной строке от утечки. XSS — это катастрофа в любом случае, cookie лишь ограничивает ущерб. Цена cookie — CSRF (подделка межсайтовых запросов): браузер прикладывает её к запросам, которые инициировал чужой сайт. Главная защита — SameSite. Lax отправляет cookie при top-level (верхнеуровневой) GET-навигации, но не при кросс-сайтовых POST, fetch или iframe. Chromium-браузеры ставят Lax по умолчанию, если атрибут не указан, но с двухминутным исключением: свежую cookie ещё отправят с кросс-сайтовым top-level POST. Firefox и Safari Lax по умолчанию не ставят вообще. Поэтому я всегда задаю его явно и держу GET без побочных эффектов. SameSite считает по сайту, а не по origin (схема, хост и порт), так что взломанный соседний поддомен всё ещё same-site. Для этого добавляю CSRF-токен или проверку заголовка Origin. CORS — другое. Он ослабляет same-origin policy (политику одного источника) и решает, даст ли браузер JS страницы прочитать ответ. Сервер он не защищает: простой POST всё равно дойдёт, а curl CORS вообще игнорирует."}],"kill":"<b>«У нас React, XSS нам не страшен»</b> или <b>«CORS защищает наш API»</b> — CORS решает только, что браузер даст прочитать JS, а запрос до сервера всё равно доходит."},
 en:{"topic":"Web security for a frontend engineer","qs":["We use React and it escapes everything. So XSS isn't our problem, right? Where does that break?","We render model responses as markdown in a chat UI. What can go wrong?","Where would you keep the auth token, and how do CSRF, SameSite and CORS fit in?"],"a":[{"q":"XSS in React","t":"Not quite. React escapes text in JSX children and attribute values, so a string with a script tag renders as literal characters. That covers the classic XSS types: stored, where the payload sits in the database, reflected, where it bounces back from a URL parameter in the response, and DOM-based, where my own client code moves attacker data from location or postMessage into a sink like innerHTML. The protection ends at the escape hatches. dangerouslySetInnerHTML hands raw HTML to the parser. An href built from user data can be javascript:. React 19 blocks that literal case, older versions only warned, and data: or a phishing domain still pass. So I allowlist http, https and mailto. Converting markdown to an HTML string and injecting it is the same hole. Raw innerHTML through a ref bypasses React completely. As a backstop I ship a strict CSP: script-src with a per-request nonce plus 'strict-dynamic', so scripts loaded by a trusted script also run without a host allowlist. An injected inline script then won't execute. It's damage limitation, not a fix, and in Next.js nonces force dynamic rendering."},{"q":"Model output","t":"I treat model output as untrusted input, same as a user comment. The model can repeat anything that reached its context: a retrieved document, a web page, a tool result. So indirect prompt injection turns into XSS the moment I render HTML. My default is to parse markdown into React elements with raw HTML disabled. react-markdown does that out of the box and strips dangerous URL protocols. If I really need HTML, I convert markdown to HTML first and run DOMPurify on the result, never the other way round. The less obvious risk is exfiltration. An injected instruction can make the model emit an image whose URL carries chat data in the query string. The browser fetches it on render, no click needed. So I block images from unknown hosts or proxy them, show link destinations, add rel noopener noreferrer, and back it up with img-src and connect-src in the CSP. With streaming, I re-render a safe tree from the accumulated text on each chunk instead of appending raw HTML fragments."},{"q":"Tokens and CSRF","t":"I prefer an HttpOnly, Secure cookie. JavaScript can't read it, so an XSS can act as the user while the tab is open, but it can't steal the token and replay it from another machine. A token in localStorage is one line away from exfiltration. XSS is game over either way; the cookie just limits the blast radius. The cost of cookies is CSRF: the browser attaches them to requests another site triggers. SameSite is the main defense. Lax sends the cookie on top-level GET navigations but not on cross-site POSTs, fetches or iframes. Chromium browsers default to Lax when the attribute is missing, with a two-minute exception: a freshly set cookie still goes out on a top-level cross-site POST. Firefox and Safari don't default to Lax. So I always set it explicitly and keep GET free of side effects. SameSite works on site, not origin, so a compromised sibling subdomain is still same-site. For that I add a CSRF token or an Origin header check. CORS is different. It relaxes the same-origin policy and decides whether the browser lets page JS read a response. It doesn't protect the server: a simple POST still arrives, and curl ignores CORS entirely."}],"kill":"<b>\"We use React, so XSS isn't a concern\"</b> or <b>\"CORS protects our API\"</b> — CORS only controls what the browser lets JS read; the request still reaches the server."}},

{n:49,tag:"Frontend core · Browser",sec:"web",core:[64],
 ru:{"topic":"Доступность (accessibility)","qs":["Коллега сделал выпадающее меню из div с onClick. Что с этим не так и как ты это исправишь?","Расскажи, как ты управляешь фокусом в модальном окне и при смене роута в SPA.","Как сделать доступным стримящийся ответ в AI-чате, и как ты вообще тестируешь доступность?"],"a":[{"q":"Семантика","t":"div не получает фокус, не реагирует на Enter и Space, а screen reader (программа чтения с экрана) объявляет его как обычный текст или в лучшем случае как «кликабельное». button даёт всё это бесплатно: фокус, активацию с клавиатуры, роль кнопки, состояние disabled. Поэтому я начинаю с семантического HTML. Настоящие кнопки и ссылки, label, привязанный к каждому полю, один h1 и заголовки по порядку, потому что пользователи скринридеров навигируют по заголовкам. И landmarks (ориентиры-регионы) вроде header, nav, main, чтобы можно было прыгать между областями. ARIA идёт вторым шагом. Первое правило ARIA: не используй её, если нативный элемент справляется, а плохая ARIA хуже, чем никакой. role button на div обещает поведение клавиатуры, которого у div нет. Из ARIA я реально беру состояния: aria-expanded на триггере меню, aria-invalid и aria-describedby на поле с ошибкой, aria-current на активной ссылке навигации. Для самого меню, если это список действий, я следую паттерну menu button из ARIA APG (сборника паттернов W3C). А часто простой disclosure (раскрывающийся блок) со списком ссылок проще и надёжнее."},{"q":"Фокус","t":"Пользователи клавиатуры и скринридеров находятся там, где фокус, и если я его не перемещаю, они теряются. Для модалки я сначала запоминаю элемент, который её открыл. При открытии переношу фокус внутрь диалога, обычно на первый контрол или заголовок. Дальше держу Tab внутри и делаю страницу за ним inert (неактивной), чтобы фон нельзя было ни достичь, ни прочитать. Escape закрывает окно. При закрытии возвращаю фокус на триггер, иначе пользователь окажется в начале документа. Нативный dialog с showModal даёт inert-фон и Escape бесплатно, но возврат фокуса я всё равно проверяю руками. Вторая ловушка — смена роута (маршрута) в SPA (одностраничном приложении). Полная загрузка страницы сбрасывает фокус, и скринридер читает новый title. Клиентская навигация не делает ни того, ни другого. Поэтому после перехода я переношу фокус на h1 или main новой страницы с tabIndex -1 или объявляю заголовок через live region (область, изменения в которой зачитываются). В App Router у Next.js есть встроенный route announcer (объявление смены страницы), но куда попадает фокус, я всё равно проверяю."},{"q":"Стриминг и тесты","t":"Если повесить aria-live на сообщение, которое стримится (приходит по частям), скринридер пытается читать каждый токен, и получается заикание или обрывки. Поэтому сам пузырь со стримом не live region. Я держу отдельную визуально скрытую область с aria-live polite, которая есть в DOM с самого начала. Когда ответ завершён, кладу туда финальный текст или короткое «ответ готов». Для очень длинных ответов можно троттлить (ограничивать частоту) до кусков размером с предложение. Во время генерации ставлю aria-busy на контейнер сообщения, но поддержка в скринридерах разная, так что настоящая гарантия — одно объявление в конце. Кнопка Stop — настоящий button, видимый и доступный по Tab, а фокус остаётся в поле ввода, чтобы можно было продолжать печатать. Я уважаю prefers-reduced-motion: убираю анимацию печати и плавный автоскролл. Тестирую так: сначала проход только с клавиатуры, потом VoiceOver или NVDA. axe и Lighthouse ловят только часть проблем, по оценке самого Deque чуть больше половины по количеству. Ориентир — WCAG 2.2 уровня AA, текущая рекомендация W3C, а WCAG 3 пока черновик."}],"kill":"<b>«Повешу role=\"button\" и aria-label — и готово»</b> — ARIA меняет только то, что объявляется, а не поведение: div всё так же не получает фокус и не реагирует на Enter и Space."},
 en:{"topic":"Accessibility","qs":["A teammate built a dropdown out of divs with onClick. What's wrong with it and how would you fix it?","Walk me through focus management for a modal and for route changes in a SPA.","How would you make a streaming AI chat response accessible, and how do you test accessibility at all?"],"a":[{"q":"Semantic HTML","t":"The div isn't focusable, doesn't respond to Enter or Space, and a screen reader announces it as plain text, or \"clickable\" at best. A button gives me all of that for free: focus, keyboard activation, the button role, a disabled state. That's why I start with semantic HTML. Real buttons and links, a label tied to every input, one h1 and headings in order, because screen reader users navigate by headings. And landmarks like header, nav and main, so they can jump between regions. ARIA comes second. The first rule of ARIA is don't use it if a native element does the job, and bad ARIA is worse than none. role button on a div promises keyboard behavior the div doesn't have. The ARIA I actually reach for is state: aria-expanded on the menu trigger, aria-invalid and aria-describedby on a field with an error, aria-current on the active nav link. For the menu itself, if it's a list of actions I follow the menu button pattern from the ARIA Authoring Practices. Often a plain disclosure with a list of links is simpler and more robust."},{"q":"Focus management","t":"Keyboard and screen reader users live where focus is, so if I don't move it, they're lost. For a modal I first remember the element that opened it. On open I move focus into the dialog, usually to the first control or the heading. Then I keep Tab inside and make the page behind it inert, so nothing in the background can be reached or read out. Escape closes it. On close I return focus to the trigger, otherwise the user lands at the top of the document. The native dialog element with showModal gives me the inert background and Escape for free, but I still test that focus comes back. SPA route changes are the second trap. A full page load resets focus and the screen reader announces the new title. A client-side navigation does neither. So after navigating I move focus to the new page's h1 or main with tabIndex -1, or announce the title in a live region. The Next.js App Router has a built-in route announcer, but I still check where focus lands."},{"q":"Streaming and testing","t":"If I put aria-live on the message that's streaming, the screen reader tries to read every token and it turns into stutter or gets cut off. So the streaming bubble itself isn't a live region. I keep a separate, visually hidden aria-live polite region that's in the DOM from the start. When the response completes, I put the final text or a short \"response ready\" into it. For very long answers I might throttle to sentence-sized chunks. While generating I set aria-busy on the message container, but screen reader support varies, so the real guarantee is one announcement at the end. The Stop button is a real button, visible and reachable by Tab, and focus stays in the composer so the user can keep typing. I respect prefers-reduced-motion by dropping typing animations and smooth auto-scroll. For testing I do a keyboard-only pass first, then VoiceOver or NVDA. axe and Lighthouse catch only part of the issues, a bit over half by volume per Deque's own estimate. My reference is WCAG 2.2 AA, the current W3C Recommendation, while WCAG 3 is still a draft."}],"kill":"<b>\"I'll add role=\"button\" and an aria-label and we're done\"</b> — ARIA changes what gets announced, not behavior: the div still isn't focusable and ignores Enter and Space."}},

{n:50,tag:"Frontend core · Browser",sec:"web",core:[65],
 ru:{"topic":"Стриминг: SSE, WebSocket, fetch-стримы","qs":["Вы делаете чат, который стримит токены LLM. Polling, SSE, WebSocket или fetch со стримингом — что выберете и почему?","Почему бы просто не взять EventSource и что ломается в продакшене с долгоживущими стримами?","Расскажите, как вы читаете поток токенов на клиенте и что происходит, когда пользователь жмёт Stop."],"a":[{"q":"Выбор транспорта","t":"Polling (периодический опрос) самый простой: клиент спрашивает раз в несколько секунд, но я плачу задержкой и пустыми запросами, так что беру его только для медленно меняющегося статуса. WebSocket даёт двусторонний канал после HTTP upgrade (переключения протокола), и это правильный выбор, когда обе стороны постоянно говорят: совместное редактирование, присутствие, голос. Но это свой протокол: нет HTTP-кеширования и статус-кодов, переподключение на мне, и он неудобен с serverless (бессерверными функциями) и некоторыми прокси. LLM-чат — это один запрос и потом односторонний поток токенов обратно. Это ровно обычный HTTP с потоковым ответом. Формат обычно SSE (Server-Sent Events, события от сервера): тип text/event-stream, события разделены пустой строкой. Сами API моделей стримят (отдают по частям) именно так. На клиенте я читаю этот поток через fetch и response.body, то есть ReadableStream, а не через EventSource, потому что мне нужно отправить разговор POST-ом. На практике получается SSE как формат и fetch как транспорт. К WebSocket я бы пошёл, только если агенту нужно постоянно и отправлять, и получать по одному каналу."},{"q":"Лимиты EventSource","t":"EventSource умеет только GET и не может ставить свои заголовки — есть только withCredentials для cookies. Чат-запросу нужен POST с историей сообщений и обычно заголовок Authorization, так что EventSource отпадает. А если его всё же взять, люди начинают класть токены в query string (параметры URL), и те утекают в логи. Зато EventSource бесплатно даёт переподключение: сервер помечает каждое событие id, и при реконнекте (переподключении) браузер шлёт заголовок Last-Event-ID, чтобы сервер дослал пропущенное. С fetch я делаю это сам, и возобновление работает, только если генерация живёт на сервере независимо от соединения, а события буферизуются. Две ловушки в проде. По HTTP/1.1 браузер держит около шести соединений на origin (схема, домен и порт), так что пара вкладок с открытыми стримами (потоковыми ответами) душит остальное приложение. HTTP/2 мультиплексирует (гоняет много потоков через одно соединение), обычно с лимитом около сотни потоков. И прокси или CDN (сеть раздачи контента) буферизуют ответ: nginx, сжатие, слои хостинга копят поток и отдают его целиком в конце. Я ставлю Content-Type text/event-stream и Cache-Control no-cache, отключаю сжатие на этом роуте (маршруте) и ставлю X-Accel-Buffering: no для nginx."},{"q":"Парсинг и отмена","t":"Я создаю AbortController и передаю его signal в fetch. Проверив response.ok, беру reader из response.body. Каждое чтение даёт Uint8Array, и я декодирую его через TextDecoder с stream: true. Многобайтовый символ вроде эмодзи или кириллической буквы может разрезаться между двумя чанками (кусками данных из сети), и без этого флага получится мусор. Декодированный текст идёт в буфер, и я режу его по пустой строке, которая завершает SSE-событие (событие потока от сервера), оставляя последний кусок. Сетевые чанки не совпадают с событиями: в одном может быть половина события или сразу три. Только у полных событий я парсю (разбираю) строки data как JSON и рендерю (отрисовываю) их. Когда поток заканчивается, сбрасываю остаток декодера и буфера. На Stop вызываю controller.abort(): чтение падает с AbortError, и я считаю это нормальным исходом, а не поводом для тоста (всплывающего уведомления) с ошибкой. Но отключение клиента само модель не останавливает. Сервер должен заметить закрытый запрос и передать abort-сигнал в вызов LLM SDK, иначе генерация продолжается, и токены, которые никто не увидит, всё равно оплачиваются."}],"kill":"<b>«Для чата просто возьму EventSource»</b> — он не умеет POST с историей и заголовок Authorization, нужен fetch и чтение response.body. А <b>abort() на клиенте</b> сам по себе модель не останавливает, сервер должен передать сигнал дальше."},
 en:{"topic":"Streaming: SSE, WebSocket, fetch streams","qs":["You're building a chat UI that streams LLM tokens. Polling, SSE, WebSocket or fetch streaming — which do you pick and why?","Why not just use EventSource, and what goes wrong in production with long-lived streams?","Walk me through reading the token stream on the client and what happens when the user hits Stop."],"a":[{"q":"Picking transport","t":"Polling is the simplest: the client asks every few seconds, but you pay in latency and empty requests, so I only use it for slow-changing status. WebSocket gives a full-duplex channel after an HTTP upgrade, which is right when both sides talk constantly, like collaborative editing, presence or voice. But it's its own protocol: no HTTP caching or status codes, reconnection is on me, and it's awkward with serverless and some proxies. LLM chat is one request, then a one-way stream of tokens back. That's exactly plain HTTP with a streamed response. The format is usually SSE, server-sent events: content type text/event-stream, events separated by a blank line. Model APIs themselves stream that way. On the client I read it with fetch and response.body, which is a ReadableStream, rather than EventSource, because I need to POST the conversation. So in practice it's SSE as the wire format and fetch as the transport. I'd only reach for WebSockets if the agent needs to push and receive on the same channel continuously."},{"q":"EventSource limits","t":"EventSource only does GET, and it can't set custom headers — there's just withCredentials for cookies. A chat request needs a POST body with the message history and usually an Authorization header, so EventSource is out. If people force it, they put tokens in the query string, which leaks into logs. What EventSource does give you for free is reconnection: the server tags each event with an id, and on reconnect the browser sends a Last-Event-ID header so the server can replay what was missed. With fetch I implement that myself, and resuming only works if generation lives server-side independent of the connection, with events buffered. Two production traps. On HTTP/1.1 browsers allow about six connections per origin, so a few tabs with open streams starve the rest of the app. HTTP/2 multiplexes streams over one connection, usually with a limit around a hundred. And proxies or CDNs buffer responses: nginx, compression or a hosting layer holds the stream and flushes it all at the end. I send text/event-stream with Cache-Control no-cache, disable compression on that route, and set X-Accel-Buffering: no for nginx."},{"q":"Parse and cancel","t":"I create an AbortController and pass its signal to fetch. After checking response.ok, I get a reader from response.body. Each read gives me a Uint8Array, and I decode it with a TextDecoder using stream: true. A multi-byte character like an emoji or a Cyrillic letter can be split across two chunks, and without that flag you get garbage. The decoded text goes into a buffer, and I split on the blank line that ends an SSE event, keeping the last piece. Network chunks don't line up with events: one chunk can hold half an event or three. Only complete events get their data lines parsed as JSON and rendered. When the stream ends, I flush the decoder and the buffer. On Stop I call controller.abort(). The read rejects with an AbortError, which I treat as a normal outcome, not an error toast. But the client disconnecting doesn't stop the model by itself. The server has to notice the closed request and pass an abort signal into the LLM SDK call, otherwise it keeps generating and billing tokens nobody sees."}],"kill":"<b>\"I'd just use EventSource for the chat\"</b> — it can't POST the history or send an Authorization header, so you need fetch and response.body. And <b>abort() on the client</b> alone doesn't stop the model, the server has to pass the signal on."}}
];
